/* 平成16年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h16.committeeSessions.push(...[{"id":"h16-20040311-3","meetingId":"h16-c-budget","date":"2004年3月11日","dateIso":"2004-03-11","committee":"予算特別委員会","time":"午前１０時０５分～午後６時２３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を162件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"私は、本日、商工費のうち２６１ページの都市型観光推進事業、それと衛生費のうちの環境衛生、２３３ページのあたりを時間があれば、お伺いしたいと思います。観光協会を初めとする観光事業関係者のこのネットワーク基盤を構築をしなければいけないんですけれども、構築をするためにはどのように区がかかわっていらっしゃるのか、本年度からの新しい事業なので、まずそれをお伺いしたいと思います。","respondent":"市川産業振興課長","answer":"これまでも実際にいろいろ品川区の観光ということについては情報発信なり事業が展開されてまいりました。ただ、意識的に行政なりあるいは観光事業者がネットワークづくりということを目的として事業を組み立てた経験がございませんでした。","voiceIndex":4,"id":"exchange-001"},{"speaker":"大沢委員","kind":"質問","question":"意識的に、自発的に、またスポット的にということなんですが、この基本調査を行う上において、今三つ述べられました意識的、自発的、スポット的、そのようなものをもとにネットワークを構築できるような体制をつくるための基本調査がなされるのでしょうか、お答え願います。","respondent":"市川産業振興課長","answer":"今回私どもで予定しております基本調査は、今、委員にご指摘していただいたような点を踏まえて、余り総花的にならないような、ある種具体的な事業を想定したようなネットワークづくりをしつつ、また事業の基本調査を行っていく、こういった考え方でおります。","voiceIndex":6,"id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"ちょっと課長のお言葉は、私にとっては非常に知識不足もありまして理解しにくい部分もありますが、それに対して、ちょっとまた再考します。観点を移します。本区の地域資源はどのようなものが観光資源と言えるのでしょうか、ちょっと具体的にお答え願えますでしょうか。","respondent":"市川産業振興課長","answer":"もう一つは、区のさまざまな行政施策による評価と申しましょうか、そういったものも一つ観光資源になろうかと考えています。","voiceIndex":8,"id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"１０５でよかったでしょうか、失礼いたしました。１０５ということで私は心得ておりましたけれども、そういう上では、地域密着型であるがゆえに他区からの来区者が少ないのが現状であると思いますが、そういう現状を持った商店街、これを都市型観光推進事業と結びつけるためには、どのように商店街に対して方策がなされるのか、ちょっとお伺いいたします。","respondent":"市川産業振興課長","answer":"一つ具体例をお示しして説明しますと、戸越銀座銀六商店街という商店街があります。これは、戸越銀座通りの三つの商店街の中では一番小さな商店街です。この商店街が数年前から独自の商店街ブランドということでさまざまな商品を出しています。","voiceIndex":10,"id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"そうしますと、新しい展開ということで、その展開という意味合いにしますと、今まで商店街に対する事業が、また別の方向あるいは事業に対して施策の多少なりとも方向修正または転換、追加があると思われるんですが、いかがなことでしょうか。","respondent":"市川産業振興課長","answer":"商店街振興策そのものの変化ということもあろうかと思いますけれども、こういう場面で、冒頭ちょっと抽象的な言葉で申し上げましたけれども、ネットワーク、つまり、例えば鉄道事業者、ホテル事業者、流通関係の事業者、こういった皆さんとネットワークを組むことによって。","voiceIndex":12,"id":"exchange-005"},{"speaker":"大沢委員","kind":"意見","question":"さて、またその散在している商店街、これを循環型の回遊路としての商店街に構築するためには、さらにどのような具体的な、これからなされる事業でありますけれども、方向性といいますか、お考えがありましたらお聞かせください。","respondent":"市川産業振興課長","answer":"今ご指摘いただいた点が、実は大きな課題であると私どもも認識をしています。一つは、やはり商店街同士、たゆまぬ競争意識というものを持ってお客さんの取り合いをしていただきたい。","voiceIndex":14,"id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"続きまして、次の質問に移ります。先ほどの衛生費のうちの環境衛生についてですけれども、鳥インフルエンザについて、入り口だけなんですが、ちょっとお伺いしたいと思います。昨今、鳥インフルエンザが問題になっておりまして、カラスにまで鳥インフルエンザがうつったということであります。","respondent":"島袋品川区保健所衛生課長","answer":"現在のところは、区独自の政策というよりも、都と連携しまして情報を集めて、例えば区の保健所にカラスの死骸があったか、鳥の死骸があったか、そういう情報を集めている段階です。","voiceIndex":16,"id":"exchange-007"},{"speaker":"大沢委員","kind":"意見","question":"鳥は飛んでくるものなので、遠くからも飛んでくるもので、１０kmぐらいということで聞いておりますので、それは本区独自というのは訂正いたしまして、やはり２３区、それから京都に発して、聞くところによりますと埼玉県のほうでも１１０羽、１０７羽ぐらいが、飼っている鳥だそうですが、公園に廃棄されたということなので、ペットで飼われていた鳥ということですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-008"},{"speaker":"若林委員","kind":"質問","question":"２２６ページの予防費、それから２４３ページの公害健康被害、時間がありましたら、２４７ページの壁面等緑化についてお願いをいたします。今の質疑、引き続きますが、鳥インフルエンザ、まずこの鳥インフルエンザというものはどういうものでしょうか。人体に与える、感染するとか、また食べ物は感染しないだとか、いろいろな言い方があります。ちょっとまとめて皆さんにお知らせ願えればと思います。","respondent":"寺西品川区保健所保健サービス課長","answer":"それで、鳥インフルエンザは、この昨年末に韓国で大流行いたしまして、日本でもと思っておるところ、１月１２日に山口県でご存じのように大量の鳥の感染が認められた後、大分県、そしてこの２月２８日に京都で実際に感染した鳥が流通したということで。","voiceIndex":20,"id":"exchange-009"},{"speaker":"若林委員","kind":"意見","question":"人には非常に感染しにくい、また政府の発表もあったということです。ＳＡＲＳのときでも問題になりましたが、その症状、どういう見分け方をしたらいいのか、あったらお願いいたします。その上で、この鳥インフルエンザで今一番問題になっているのが、今、大沢委員もご指摘がありましたように、いわゆる風評被害ということが言われております。うわさがうわさを読んでというような部分だと思います。","respondent":"寺西品川区保健所保健サービス課長、島袋品川区保健所衛生課長","answer":"その後、どういうことをするかというと、血液中の抗体検査であるとか、病原体そのものを培養をかけて、一々非常に細かい検査を進めていかないことには、これが鳥インフルエンザかどうかというのはわからないという状態です。ただ、これから情報等を集めまして、ホームページ等の活用も考えていきたいなと考えているところです。","voiceIndex":22,"id":"exchange-010"},{"speaker":"若林委員","kind":"意見","question":"今回の鳥インフルエンザのことが起こって、これは各小学校で飼われている鳥でありますとか、はたまたウサギでありますとか、いろんな問い合わせがあったように聞いておりますが、その内容と、それに対する対処の仕方、これを最後にお願いいたします。どう対処をされたのか。","respondent":"島袋品川区保健所衛生課長、谷田部学務課長","answer":"詳しいところにつきましては、我々で対応できない場合には家畜保健衛生所が都にありますので、そちらにも連絡するようにということで伝えております。その結果、屋内で飼われている鳥等は別といたしまして、屋外で飼われている、いわゆる飼育小屋で飼われている鳥小屋につきましては、私ども緊急に消毒をするということで現在準備を進めてありますし。","voiceIndex":25,"id":"exchange-011"},{"speaker":"若林委員","kind":"質問","question":"これは、足し算をすれば全体ということでよろしゅうありますか。それと、例えば品川区におきましては、山手通り、そこら辺の周囲の、例えば西五反田周辺の集中度合い、数というのはわかりますでしょうか。","respondent":"田中健康課長","answer":"品川区全般にこういう形で患者がいらっしゃるというふうに私どもは認識しています。","voiceIndex":30,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"実は今回私どもの会派の代表質問でも触れさせていただきましたが、いわゆる都市高速道路中央環状の品川線の出入り口、また換気塔の問題が今地元で非常に大きな問題になっております。ぜひこういう地域の方たちの声を、例えば健康の面でこうなんだというようなことが具体的、科学的にわかるような形で、また調べていただければなと、これは一つ要望をしますので、どうぞよろしくお願いをいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、ページ数はちょっとわからなかったんですけれども、衛生費全般にかかわるかもしれません。保健所や保健センターに寄せられている児童虐待の相談について伺いたいと思います。品川区には保健所や保健センターが３カ所あると伺いました。","respondent":"小林品川区保健センター保健サービス課長","answer":"ですから、健診の機会あるいは児童相談所、保育園、近隣の方等からいろいろな虐待に関する相談があります。今年度、現在のところは虐待とまではいきませんけれども、虐待の関連のご相談というふうで上げしますと、今のところ今年度３４件というふうになっております。","voiceIndex":34,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"区内ではさまざまなところからいろんな相談が寄せられると思うんですけれども、どのような体制で全体の把握をしているのか、虐待の統計などありましたら教えていただきたいと思います。平成４年度と平成１４年度の統計と、あと、何倍ぐらい相談の件数が増えているのか説明していただければと思います。","respondent":"辻田児童課長","answer":"品川区における虐待児童の件数の推移ですけれども、平成１３年度には品川区では５６件、それから平成１４年度には３０件、平成１５年度、これは１月現在ですけれども４４件という形で推移しております。","voiceIndex":36,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただいま件数の報告がありましたけれども、これは品川の児童相談所に寄せられた件数なのでしょうか。なぜかというと、厚生労働省の調べで、近年だけ見ても、これは国全体ですけれども、１９９９年で１万１,６３１件、その翌年の２０００年は１万７,７２５件、２００１年だと２万３,２７４件と増えている傾向があるんで、品川区はどういう状況をつかんでいるのか、もう一度説明していただきたいと思います。","respondent":"辻田児童課長","answer":"虐待の事例であるか事例でないかというのは非常に判断が難しいという状況が一つあります。","voiceIndex":38,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただいまの説明で私が率直に思うのは、区内の虐待の実態がまだまだ正確につかみ切れていない。だけれども、それをまとめる体制が整え切れていないというのが現状ではないのかなと思いますので、事態は年々深刻になっているんで、ぜひその実態をつかむ体制の整備、またどこが中心になって行っていくのか、今後のお考えがございましたら教えていただきたいと思います。","respondent":"辻田児童課長","answer":"この虐待の事例の対応につきましては、今ちょうど過渡期にあるのかなというぐあいに考えております。今般児童福祉法が改正になりまして、児童相談所の機能というものが変わってまいりました。","voiceIndex":40,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひその協議会を中心に、今後積極的に行っていただきたいと思います。厚生労働省の調査がちょうど平成４年度に始まっているんで、それぞれ平成４年と平成１４年、定数が何人で、実際に何人の方がそこで勤務されているのか、説明していただければと思います。","respondent":"田中健康課長","answer":"それで、今申し上げたのは平成４年４月１日当時がこういう形になってあります。現状は、本年度３３名が保健高齢事業部に配置をされております。","voiceIndex":42,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただいま説明があったんですけれども、平成４年度では３６人いた職員が今３３人、定数から比べても３５人の定数にもかかわらず３３人。事態が日々深刻になっているので、きちんと配置をして充実をすべきでないのかなと思います。現場ではなかなか苦労もあるとは思いますけれども、ぜひ保健師の充実をすべきではないかと思いますけれども、お考えを示していただきたいと思います。","respondent":"田中健康課長","answer":"先ほどちょっと１０年ほど前の人数を申し上げましたが、その後、例えば介護保険の導入ですとか、役割分担がいろんな中で区のいろいろな事業の中でも変わってあります。","voiceIndex":46,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"保健所というのは、児童相談所のような強制力というものをもちろん伴う権限はないですけれども、区民にとっては身近な窓口であり、健康診断を直接行うべきところですから、より充実したことが必要ではないかなと思っています。","respondent":"小林品川区保健センター保健サービス課長","answer":"今後もますます先ほどのお話のように、虐待ということについても深刻な問題になっておりますので、虐待の早期発見、早期発見ではなく予防ということで、子育ての支援、健診についてもただ疾患を発見するということではなく、虐待に至りそうなお母さま方の発見をいたしまして。","voiceIndex":48,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ保健師の拡大も含めてその事業の内容の充実をよろしくお願いいたします。人口がおよそ倍にもかかわらず、職員は８分の１というのが現状ではないかと思いますけれども、これは国の施策もあるとは思いますけれども、現状のままでいいのかという区のお考えがありましたら、教えていただきたいと思います。","respondent":"辻田児童課長","answer":"そういうような状況をかんがみまして、昨年児童福祉法の一部改正を行い、従来児童相談所の持っていた一般的な相談、療育の対応、そういうようなものを整理しまして、虐待というような、そのほかにもありますけれども、そういうようなものに児童相談所が特化していくということで。","voiceIndex":50,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"実際は、通告者に虐待かどうかの確定判断は求められているわけではなくて、これを確定するのは、当然ですけれども児童相談所や家庭裁判所が行うことですから、職員からは疑いがある場合には積極的に相談を持ち上げていく、こういう体制が必要ではないかと思いますけれども、当然、区ではそういった虐待に関する研修を行っているとは思いますが。","respondent":"辻田児童課長","answer":"昨年１月に発足しました児童虐待防止協議会、この中で、いわゆる区の職員、それから地域の方々、主任児童委員とか民生委員の方々ですけれども、そういうような方々にこの発見の大切さというのは会議などを開いて周知しております。","voiceIndex":52,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"なかなか上手に質問できないんですけれども、直接この区の職員に対しては、どういう研修が行われているのかというのが伺えればと思います。学校現場で発見する場合、保育園で発見する場合、もちろん相談窓口で発見する場合、また疑いがわかる場合、いろいろなケースで相談が寄せられていると思うんで、職員全体の何か研修が今行われていたら、最後にこれだけ教えていただければと思います。","respondent":"辻田児童課長","answer":"幾つかの、基本的には要するに仕事の中、ＯＪＴの中で実際に周知していくというのが原則だと思います。そのほかに学校であるとか、それから保健所、いろいろな機関が集まりまして、年に１回そういうような会議を持っている、そういう中で周知をしているということがあります。","voiceIndex":54,"id":"exchange-023"},{"speaker":"土井委員","kind":"質問・要望","question":"その辺の状況と、それらを含めた、品川区に来るにしろ清掃一部事務組合でやるにしろ、焼く問題があるわけですから、その辺の状況等をどう検討されていくのかということをまず１点伺いたいこと。分担金の積算方式。本来的には解散に向けてどうするかということを本当は聞きたいんですけれども、これだけやっていても２０分ぐらいかかっちゃうので、これはとりあえず要望だけにしておきます。","respondent":"島袋品川区保健所衛生課長、中山清掃リサイクル課長、市川産業振興課長","answer":"品川区の獣医師会との関係ですけれども、区のほうは、獣医師会とは従来から狂犬病予防注射でご協力願っているということで、非常に親しい関係ですけれども。人口割だけでなく、ごみのそういう減量も分担金の中に折り込まれるような仕組みが考えられないかということで検討が開始されている、こういう状況です。２点目の大崎図書館については、これは私どもの産業振興の立場から説明申し上げますが、やはり情報の収集。","voiceIndex":57,"id":"exchange-024"},{"speaker":"土井委員","kind":"質問・要望","question":"わかりました。当然のことなんですけれども、今やっているのは実際上、何ですかと言ったら、はっきり申し上げてペットボトルだけでしょうと。このプラスチックとこのプラスチックは分けていただきますけれども、これはもう燃えるごみに入れましょうということでやっていけるわけですから、これはしっかりと早急に検討していただきたいと私は思っておるんですけれども、もう一度お伺いいたします。","respondent":"中山清掃リサイクル課長、市川産業振興課長","answer":"分担金の見直しのスケジュールですけれども、現在、平成１６年度の前半に向けて方向性を示せるようにということで検討が進められているというふうに伺っております。この大崎図書館での事業の支援スタッフの件ですけれども、現在私どもがいろいろな形でおつき合いしているものづくりの関係、これは技術者のＮＰＯ、それから能力開発の専門機関のＯＢたちによるＮＰＯ。","voiceIndex":61,"id":"exchange-025"},{"speaker":"土井委員","kind":"質問","question":"ビジネス支援図書館はぜひとも、日本一の製造業のまちこれありということになっていただけるようにお願いをしておきたいなと、こんなふうに思います。初めからそうすりゃいいじゃないかということになるわけです。ですから、そこら辺はきっちり決めていただかなきゃいけませんよ、早急に決めてくださいよ、こういうことを申し上げているんですよ。どうですか、ちょっとお聞かせください。","respondent":"中山清掃リサイクル課長","answer":"確かに工場の炉のカロリー能力というものも、従来のような傷むであるとか、いわゆる排ガスの問題もなくなってきている、こういうことも踏まえて、今ご指摘のとおり、これからの適正な処理の中で、資源の有効利用という中で考えていくべきというふうに考えております。","voiceIndex":64,"id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私もちょっとただいまの質問と重なってくる部分があると思うんですが、なるべく重ならないようにお聞きしたいと思います。衛生費の中で、清掃費の中の収集運搬作業費、それが２５０ページですか、それに絡んで、環境費の中の２４７ページで資源回収事業、それと産業経済費の中の２５９ページ、中小企業事業資金融資あっせん、それともう１点が製造業マンパワー強化支援事業。","respondent":"中山清掃リサイクル課長、市川産業振興課長","answer":"各戸収集につきましては、現在約４万３,０００世帯ほどのエリアに広がっておりますが、１０月までに７万世帯を拡大して、区内７割という予定で拡大しています。製造業関係のインターンシップに関するお尋ねですが、私どもの区では、平成１１年度から今年度まで５年間にわたりましてインターンシップの推進事業ということで、主に都立工業高等専門学校、それと都立大森工業高校。","voiceIndex":67,"id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問","question":"各戸収集はまず努力はわかります。うまく伝えていなかったんで。私もこんな格好をしていないですから、普通に汚れた格好をしていて、向こうは議員だということを知らないで話していたんですよ。ですから、その方は一般に町会の人だと思って話していた中で、すごく責任を持ってやっていたんです。その部分に対する対策、区の中でどう考えているのか、それをもう１点お聞きしたいと思います。","respondent":"中山清掃リサイクル課長、市川産業振興課長","answer":"補正のご質問のときにも幾つか対応しているんですけれども、なかなか根絶が難しいという中で、もう少し区への排出の意思表示ととりにくさを明確にする仕掛けを考えていきたいとご説明いたしました。インターンシップの対象者、対象学生の拡大につきましては、私のほうもその辺は希望しているところでございまして、具体的に区内の中小企業からそういった希望が出るなり、あるいは私どもが産学連携事業の中で提携している大学に対して。","voiceIndex":70,"id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"インターンシップについては、なるべく産学連携事業で増やしていただきたいのもあるんですけれども、もう一つは、産業交流支援事業というのもありましたけれども、これは企業側の部分だと思うんですが、企業から大学派遣だと思うんですが、その辺ももう１回ご説明いただきたいと思います。","respondent":"中山清掃リサイクル課長、市川産業振興課長","answer":"それで、細かく言いますと、表示の中で考えておりますのは、この資源は私たち区民が品川区または区の契約回収業者に出したものであるから抜き取り禁止ということで。今回、従来の人材育成支援事業を組みかえて製造業マンパワー強化支援事業とした一つの柱に、今お尋ねのございました企業から大学あるいは研究機関に、いわゆる短期留学と申しましょうか、社員の能力開発。","voiceIndex":73,"id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問","question":"古紙についてはわかりました。それと大井ストックヤードの活用、土地は先ほどお話があった清掃一部事務組合が持っていて、建物は品川区になっていると思いますが、今後の点についてお聞きしたいのと、それから最近ペット・トゥー・ペットというお話も聞いております。そのまま使って再生していくという点に関してもお聞きしたい。とりあえずそこの点をお聞きしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"この１０月からですけれども、区内全域のステーションでペットボトルの回収を行いますと、そういう、ついでにやるということでは恐らく追いつかないということで、当面、従来はそういう手段もなかったわけですが、民間で梱包するという企業も出てまいりまして。","voiceIndex":76,"id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それと１個聞こうと思ったのは、容器リサイクル法上の企業者責任、この部分に対して、今、区の負担と企業側の負担率、その辺も後でご説明と、今後お話をどう考えていくかということを、お答えを後ほどお願いしたいと思います。もう１点、制度融資についてちょっと簡単にお聞きしたいと思います。その辺がクリアできたのか。その辺をよく周知できるか、そこら辺について、後でお答えをお願いいたします。","respondent":"中山清掃リサイクル課長、市川産業振興課長","answer":"この資源の中で、容器包装にかかわるものだけをコスト積算するというのは、なかなかこれは技術的に難しい部分がありますけれども、報道等で言われておりますのは、全国的な１事業者負担との割合が３分の２ぐらいが自治体、行政負担で。いわゆる一本化資金の件ですけれども、今まで鈴木委員のほうからたびたびご指摘、ご要望をいただいてきた件、最終的に実施の詰めをしております。","voiceIndex":78,"id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"私は、まず初めに２６１ページ、都市型観光推進事業についてと、あと２５９ページの融資あっせん事業についてお伺いします。都市型観光推進事業について１点お伺いいたします。この調査の依頼先は、いわゆる大手のコンサルタント会社、そういうところに調査依頼をするんでしょうか、それとも別のところに依頼するんでしょうか。その依頼したところの一番の理由、メリットというのは何なのでしょうか。","respondent":"市川産業振興課長","answer":"今の時点で詳細なことを決めているわけではございませんが、先ほど大沢委員からもご質問にございましたように、私どもこの調査を通じて同時にネットワーク形成も図っていきたいと、観光事業者によるネットワーク形成も図りつつ。","voiceIndex":82,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"融資あっせん事業についてお伺いしますが、今、鈴木真澄委員の質問の答弁で、預託金制度を廃止したのは影響がないということですが、最近の融資の動向とか、あと特徴、申し込みに対する融資実行の状況をお知らせください。","respondent":"市川産業振興課長","answer":"ここ１年ばかりの融資の動向ですけれども、これは私ども区の制度融資のみならず、区内の一般の金融機関あるいは政府系の金融機関を通じて言えることですけれども、昨年の４月からの６カ月間、今年度の上半期は大体前年度並みか、あるいは若干上回る。","voiceIndex":84,"id":"exchange-033"},{"speaker":"藤原委員","kind":"提案","question":"この廃止というのは、他区に先駆けて、たしか事業の見直しで廃止するという説明があったと記憶しているんですが、これに関連して、財政についてちょっとお伺いしたいんですけれども、今回も同様な基金の廃止が提案されていると思いますが、この融資あっせんの基金も含めて、これらの廃止はいずれもペイオフ対策とかあと財源の対策ではなく、そもそもこのこと自体が必要がなくなったということで。","respondent":"市岡企画財政課長","answer":"それで、廃止したわけですけれども、ただ財源対策として廃止したわけではありませんで、この中小企業の基金につきましても、そのうちの３分の１程度で西大井のベンチャーの財源にいたしましたし、それから残りを今進めております商店街の電線の地中化の財源として。","voiceIndex":86,"id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"品川区のこの制度融資ということでお伺いしますが、いわゆる中小企業はこの制度を利用しなくても、いわゆるプロパーの銀行と金融機関と間に入れなくてもいわゆる融資をして事業をしていくというのがあると思うんですけれども、いわゆる品川区内においての融資全体の中で、この制度融資というのがどのくらい活用されているか、わかれば数字的で示していただけますか。","respondent":"市川産業振興課長","answer":"ちなみに、これを５年前の数字と比較いたしますと、件数については５年前の倍以上になってあります。それから、金額にいたしますと５年前に比べて３倍以上の伸びとなっています。","voiceIndex":88,"id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"いわゆる制度融資を申し込んで、かかわってくるのは信用保証協会の保証制度ですが、ここで信用保証協会からノーと言われた事業主の受け皿と、それと、今何かと話題になっておりますが、東京都がつくる新銀行というのは、これからどのような影響を及ぼしてくるか、教えてください。","respondent":"市川産業振興課長","answer":"信用保証協会で信用保証を否決された事業者の受け皿ですけれども、これは非常に難しい問題です。現に私ども制度融資でも、２０％弱の否決率があります。","voiceIndex":90,"id":"exchange-036"},{"speaker":"武内委員","kind":"質問","question":"私のほうは２５３ページの清掃費の中から廃棄物減量等推進委員経費、それから２５５ページ、同じく清掃費の中で各戸収集、それから２５９ページの産業経済費の中で、商店街振興事業、２６３ページの技術ブランド創出経費についてお伺いをします。","respondent":"中山清掃リサイクル課長","answer":"廃棄物減量等推進委員は条例に基づき設置している組織でございまして、現在約４７０名の方を区長から委嘱しています。","voiceIndex":93,"id":"exchange-037"},{"speaker":"武内委員","kind":"意見","question":"いろいろ大変なお仕事をされているようなことですが、これから各戸収集に伴いまして、徐々に集積所がなくなってくる中で、個々の家の前にという形になりますけれども、今後この方たちが役割としてどのように変わっていくのか、また状況として減っていくのか、それとももうちょっと増えていくのか、その辺ももし方向性がありましたら、お示しください。","respondent":"中山清掃リサイクル課長","answer":"当初６００人ほど委嘱したいということでお願いしたんですけれども、やはりなかなか町会・自治会の規模等もありまして、現在はこのような人数ですけれども、やはりこういうごみや資源の問題は、地域のみずからのことと考えていただく。","voiceIndex":95,"id":"exchange-038"},{"speaker":"武内委員","kind":"質問・要望","question":"先ほどちょっとお仕事の内容で、先ほどもありました抜き取り対策のそういったことも注意ということですけれども、いろいろ権限等の問題とかあると思いますので、その辺明確にして、お仕事をやりやすいような形でよろしくお願いしたいと思います。これは要望ということでお願いいたします。","respondent":"中山清掃リサイクル課長","answer":"なかなか先ほどもありましたが、上空を飛びということですから、区内の生息数の把握というのは非常に難しい部分もありますが、集積所の被害状況の調査というものを、これは年に１回、２回なんですけれども、やっております。","voiceIndex":97,"id":"exchange-039"},{"speaker":"武内委員","kind":"意見","question":"非常に望ましい、好ましいことだと思うんですけれども、これから各戸収集が増える中で、今現在もかなりのところが各戸収集をやっているので、私はマンションなもので、ちょっとその辺が余りぴんと来ないんですけれども、実際にポリバケツ、各家庭の方で使っている方がいると思うんですけれども、ある地域の方が清掃事務所のほうに問い合わせをしましたら。","respondent":"中山清掃リサイクル課長","answer":"いずれにしても、必要な容器については、きちんと使っていただいて結構だというふうに認識しております。","voiceIndex":99,"id":"exchange-040"},{"speaker":"武内委員","kind":"質問","question":"そういった中でカラスネットの役割も、マンション等の集合住宅以外は、これからもうなくなってくると思うんですけれども、その中で、ちょっと二、三出ているのが、個々の、さっき言ったポリバケツの話もそうですけれども、個々のネットみたいなのがないのかという区に問い合わせが何件かあるらしいんですけれども、そういった問い合わせは来ていますでしょうか。","respondent":"中山清掃リサイクル課長","answer":"区でそういうものを用立てして配る考えはございませんが、適切に使える有効な用具であれば、そういう地域、区民の方に紹介するというふうなことは、これから考えていきたいというふうに思っております。","voiceIndex":101,"id":"exchange-041"},{"speaker":"武内委員","kind":"質問・要望","question":"要望としてお願いいたします。それから次は、２５９ページの産業経済費の商店街振興事業のところでお願いしたいと思います。こちらにつきましては、ちょっとここに当てはまるのかどうかわからないんですけれども、一応商店街振興事業の、簡単にちょっと事業概要をお願いいたします。","respondent":"市川産業振興課長","answer":"その他、アーケードのある商店街、それからアーチのある商店街、こういったところにそれぞれ装飾灯なり電灯の１本について定額の補助金を定めまして執行しているものです。","voiceIndex":103,"id":"exchange-042"},{"speaker":"武内委員","kind":"質問","question":"いずれにしても商店街の振興のための補助ですが、ちょっとずれるかもしれませんけれども、同じ商店街ということで、今まで商店の道路上にせり出した問題で、今まではどちらかというと土木関係のほうで対応していただいている経緯があると思うんですが、例えばここのちょっと商店街振興事業じゃないかもしれませんけれども、いろいろなこの商店街、同じ振興の中で。","respondent":"市川産業振興課長","answer":"やはり商店街、守るべきルールは守った上で、そこで私ども支援すべきものは支援する、こういうスタンスを明確に打ち出していきたいというふうに考えてあります。","voiceIndex":105,"id":"exchange-043"},{"speaker":"武内委員","kind":"質問","question":"いろいろ大変だと思いますけれども、ぜひよろしくお願いいたします。いろいろＮＰＯとの連携の中で、先ほど特許を申請したというふうにお伺いしましたけれども、ここに１,１３３万６,０００円の計上をされておりますけれども、これは例えば開発経費ということなんですけれども、ＮＰＯのほうで負担をされている、区との割合というか、率というのがもしあれば、お教えください。","respondent":"市川産業振興課長","answer":"今回のこのセキュリティシステムの開発につきましては、基本的に区とＮＰＯの負担は折半ということで考えてあります。","voiceIndex":109,"id":"exchange-044"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、単純にこの倍の金額がこういった経費という形でよろしいでしょうか。そうすると、これは、もしかしたら、もう発表されていると思うんですが、ちょっと私が知らないで、いつごろ完成の予定でしょうか。","respondent":"市川産業振興課長","answer":"９月に実際の通信機器の試作機を使って開発した通信ソフトのぐあいを見た上で、その上で通信ソフトの最終的な設計、開発の完了と機器の開発を行って、平成１７年度のなるべく早い時期に使えるような形でやっていきたいということで。","voiceIndex":111,"id":"exchange-045"},{"speaker":"川西委員","kind":"質問","question":"初めに保健所の事業に関係してお尋ねいたします。恐らく２２９ページから２３１ページにかかるのだろうと思いますけれども、ここにがん検診、区民健康診査いろいろありますけれども、恐らく健康診査普及事業に入るんでしょうか。ああいう健診、それから個人企業の方の単独で行く健診のことを申し上げているんですけれども、詳しい説明、事業内容をお知らせください。","respondent":"小林品川区保健センター保健サービス課長","answer":"委員ご指摘の一般の企業の方の健診につきましては、やはり中小零細企業の健診については、なかなか自前でできないということで、保健所の健診、使用料は一般の医療機関で受けられるよりも低額でできますので。","voiceIndex":116,"id":"exchange-046"},{"speaker":"川西委員","kind":"質問","question":"保健所でやりますと６,０００円以下で済むというようなことで、費用の点で大変かかるなという経験をいたしました。そういうことで、若い世代の人たちの支出を増やしていくのは区の姿勢かなというふうにちょっと感じたものですから、３月ぐらいだけでもそういう機会を設けていただけないかなというふうに感じておりますが、いかがでしょうか。","respondent":"小林品川区保健センター保健サービス課長","answer":"委員のご趣旨はわかりますが、会社、就職のための健診、入学のための健診といいましても、例えば大学に入学する場合は、初年度については高校３年のときの健康診断の結果でいいというふうにされていますし、２浪以上の方が健康診断書を求められると思うんですが。","voiceIndex":118,"id":"exchange-047"},{"speaker":"川西委員","kind":"質問・要望","question":"希望だけ述べておきます。こういう新しく資源の回収に参加しようとする人たちに対してのＰＲ活動をどのように行っていかれるのか、お伺いいたします。それから、先ほど武内委員のほうからも啓蒙ということでご質問がありまして、ダブっていて申しわけないんですが、そういう点でお答えいただきたいと思います。地域によって違うんでしょうか、なさったらいかがかと思いますが、お答えをください。","respondent":"中山清掃リサイクル課長","answer":"そのことによって、分別の意識や出す時間、ごみの減量まで考えていただくという仕掛けですので、それによる効果をねらっているものです。資源回収の充実等、これから各地域に入る際に、よりわかりやすく説明を丁寧にやっていきたいというふうに考えております。","voiceIndex":120,"id":"exchange-048"},{"speaker":"川西委員","kind":"質問","question":"衣類のことをちょっと忘れました。衣類ですが、私たちの資源に出した衣類はどんなふうに行くのかということを、よく主婦の間で質問が出ます。最近はこういうものが出回っておりまして、新しいものもどんどん資源の中に出しています。そういう点でのＰＲもよろしくお願いいたします。","respondent":"中山清掃リサイクル課長","answer":"それ以降については明確な捕捉はできませんけれども、ウエスとして利用されるものと、それからまだ再利用できるものは一部海外に行って再利用されているというふうに伺っております。","voiceIndex":122,"id":"exchange-049"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私は、２３１ページの区民健診およびがん検診、あと２３３ページの成人歯科検診について伺いたいと思います。日曜日もやっている。そういうかかりつけというのは品川区内の医療機関なんですよね。私が言っているのは品川区民が例えば大田区あるいは目黒区等にかかった場合も区民健診としてできるというふうにしていただけないかということなんですけれども、検討はできないものでしょうか。","respondent":"田中健康課長","answer":"区によっては、私どものように４０歳以上延べてではなくて、飛び飛びといいますか、４０歳、５５歳とありますので、正直言いまして、費用も違いますし、そういう意味での相互乗り入れは現状ではできないというふうにお答えするしかないと思います。","voiceIndex":125,"id":"exchange-050"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、私は同じ基準をつくれとかということを言っているのではなくて、品川区民がほかの自治体でも受ける、例えば品川区民が大田区で、いつも１日中大田区にいるから、品川区の区民健診を大田区の医療機関でできる、そこで受けたらちゃんと費用も払いますよ、そのかわり品川区の内容でやってくださいということはできるんではないですかということを言っているんです。","respondent":"田中健康課長","answer":"いろいろなメニューというのは、それぞれ品川区のメニューにという特定を大田区の医療機関が知っているわけではございませんで、私どもは品川区、荏原両医師会を通じまして、メニューの選択、対応できる診療所というのを特定してやってありますので、それを大田。","voiceIndex":127,"id":"exchange-051"},{"speaker":"宮崎委員","kind":"質問・要望","question":"いわゆる他区で保育を受けたり、そういう場合にはやりとりをちゃんとやっているわけですから、なぜ健診だけできないのかというのはさっぱりわからない。これはやればできるというふうに思いますので、引き続いてこれは要望しておきたいと思います。新年度の予算でも成人歯科検診は１,１００件の予算です。非常に少ないんですけれども、昨年までの受診率がわかったら教えていただきたいというふうに思います。","respondent":"田中健康課長","answer":"そのうち今年度の受診等も７０１件という数字でございまして、そういう意味で、これは年度途中でございましたので、例年１,０００件から１,１００件程度ということで、現在予算計上しています。","voiceIndex":129,"id":"exchange-052"},{"speaker":"宮崎委員","kind":"質問","question":"今のは成人歯科検診ですか、歯周疾患のほうも合わせてですか。","respondent":"田中健康課長","answer":"今のは成人歯科検診ですけれども、現状は実は４０歳と５０歳については歯周疾患検診という形で内容をちょっと変えてありますので、それを一緒にした数字です。","voiceIndex":131,"id":"exchange-053"},{"speaker":"宮崎委員","kind":"質問","question":"これは、検診というのは、早期発見、早期治療というふうなわりには非常に目標が低過ぎるというふうには思っているんですが、区のほうの感想はどうなんでしょうか、そこのところをまずお伺いしたい。治療を進めていく、あるいは歯ブラシを勧める、そういう動機づけには非常に効果があるというふうに思っておりますが、こういうところでの内容の充実についてもあわせてお伺いしたいと思います。","respondent":"田中健康課長、寺西品川区保健所保健サービス課長","answer":"私ども４０歳以上というのは老人保健法の年数に合わせてですので、当面はそういう意味合いでの若い方というのは、なかなか対称にしても検診にはおいでいただけない方が多いんではないかというふうに考えてあります。だから、その辺も含めて、今後の検討課題ではないかと思います。","voiceIndex":133,"id":"exchange-054"},{"speaker":"宮崎委員","kind":"質問","question":"ぜひその局所を撮るものを含めて画像診断の導入をお願いしたいと思います。でも、私は大事なのは、健康診断、健康診査ですから、これは痛くなってからということじゃなくて、痛くなる前に受けさせる、この啓蒙も含めてやるわけですから、こういう観点も含めて、これは受ける人が少ないから年齢が高いままだという理屈は全くないと思うんですけれども、ここのところの考え方をもう一度お伺いしたいと思います。","respondent":"田中健康課長","answer":"若い方の部分ですが、どうしても若い方はご自分の身体を、歯も含めて関心が薄いこともありますし、特に妊婦の方に関しては、そのころいろいろ健康学習等でいろいろな形の啓蒙等、検診を行っておりますので、そのような形でご理解いただきたいと思います。","voiceIndex":136,"id":"exchange-055"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ぜひ、内容の充実をしていただきたいということを求めて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-056"},{"speaker":"本多委員","kind":"質問・要望","question":"清掃事業の中間処理、地域処理の検討から、昨年１１月の区長会での方針決定までのそれぞれの経緯につきまして、流れは大体把握をしているつもりなんですが、その変わったポイントというんですか、その重要的なところの経緯を教えていただきたいのと、この分担金の平成１６年度の予算というものは、当然これは平成１７年度までは、ある一定の決まった分担金だと思うんですけれども。","respondent":"中山清掃リサイクル課長","answer":"初めに清掃一部事務組合の現段階に至るまでの経過を簡単にご報告いたしますけれども、当初平成１３年度から１４年度にかけて、いわゆる地域処理、ブロックによる清掃工場の処理の検討を、清掃所管を中心に行いまして、助役会を通じて報告を上げたです。","voiceIndex":140,"id":"exchange-057"},{"speaker":"本多委員","kind":"質問・要望","question":"それで、助役会への下命ということなんですけれども、当分の間、共同処理ということなんですけれども、そういったことを踏まえて、これからの助役会で下命をされるということなんですけれども、各区の意見が反映できるように積極的に見直すというところで、これは本会議での答弁でもこれから助役会が開かれるということで、これからということだったんですけれども、その検討に当たりましての。","respondent":"濱野助役","answer":"これはもう既に何回か話し合いが持たれたところで、品川区は、当分の間というその当分の間は多分一番短く考えている区だろうねというような議論もあったわけでありますけれども、当然これは当分の間でありますから。","voiceIndex":142,"id":"exchange-058"},{"speaker":"本多委員","kind":"質問・要望","question":"ぜひその当分の間、積極的に品川区がリードしていって、助役会のほうをお願いしたいと思いますが、地域処理の考え方としまして、今、その当分の間は共同処理なんでしょうが、地域処理の考え方にちょっと戻りまして、清掃一部事務組合自体でなく、各区ならびに２３区がその地域処理のシミュレーションを考えるべきだと思うんですけれども、シミュレーション、搬入路ですとか。","respondent":"中山清掃リサイクル課長、高橋区長","answer":"今、助役がご答弁申し上げたように、当分の間ということで、とりあえず清掃一部事務組合の見直しについては検討されておりますが、当然２３区として地域。ブロックを組むときにどのブロックを組んだほうがいいだろうかというふうな問題がありまして、結局、助役会から上がりました四つの案につきましては、区長会でほとんど検討をしないで、それはそれとして。","voiceIndex":144,"id":"exchange-059"},{"speaker":"本多委員","kind":"質問・要望","question":"清掃一部事務組合の抜本的な改革ということで、これから助役会を中心に議論をされていくということなんですけれども、この清掃一部事務組合の構成人員を見ましても、今現在平成１５年度１,５２３人のうち、焼却という人員が１,１６１人、あとは管理ですとか不燃、粗大、し尿でということで、不燃ですとか粗大、し尿は、やはりこれは最初から分けて、切り離していたものですから、どうしても。","respondent":"高橋区長","answer":"具体的な問題につきましては、これから検討に入るわけですが、清掃一部事務組合につきまして、現在の清掃一部事務組合でいいかというと、いいという区は１区もございませんでした。","voiceIndex":147,"id":"exchange-060"},{"speaker":"本多委員","kind":"意見","question":"本当にぜひ引き続きお願いしたいと思います。ちょっと話が飛ぶんですが、都議会でも取り上げられて、非常にこの清掃事業、収集運搬ですとか、何か今までの清掃局がやっていたのと変わらないじゃないか、そんなような非常に残念な発言があったんですが、その辺につきまして、品川区の今までの取り組み等を含めまして、ちょっと感想をお願いしたいと思います。","respondent":"高橋区長","answer":"そういうようなことが言われるということは、やはり事務当局でこの清掃業務に対する主体性を持ち得ない、持てなくなってきた、そのような考えが浸透しているんじゃないのかなという気がしています。","voiceIndex":149,"id":"exchange-061"},{"speaker":"大西委員","kind":"質問","question":"私のほうからは、衛生費１３５ページ、４目の保健指導費と、それと、これは２５６ページ、１目消費者対策費、そして時間がありましたら２６５ページの４目プラン２１習熟度別学習推進校指導助手についてお尋ねします。つきましては、今、区のほうでその発見に対する何らかの仕組み、こういったものはありますでしょうか。","respondent":"小林品川区保健センター保健サービス課長、田中健康課長","answer":"仕組みと言いますよりも、先ほどご答弁申し上げましたように、保健所、保健センター、保健相談所は、基本的には全員の子どもの状況を把握できる、お母さま方の状況も把握できるという立場にありますので。こことの連携をきちっと図っていくということが最大のルールかなというふうに私どもは今認識しております。","voiceIndex":152,"id":"exchange-062"},{"speaker":"大西委員","kind":"質問","question":"例えば保健所であれば、どういうかかわりかわかりませんけれども、お年寄りをある程度の時々に訪問して、その身体の状態を見るとか、来てもらうとか、その辺ちょっとわからないんですけれども、何らかのそういう方法で行政が虐待を早急に発見するという明確な仕組みをつくるべきじゃないかと思うんですけれども。","respondent":"辻田児童課長","answer":"品川、目黒、大田の３区に限って言えば、実母以外の母親の方がいじめをしている、虐待をしているという例は全然ございません。","voiceIndex":155,"id":"exchange-063"},{"speaker":"大西委員","kind":"質問・要望","question":"私は、これはできる限りサービスを提供したいのか、委員としては、なるべくそういうことをお年寄りのためにやってやりたいということなので、もし答弁される場合は、今はよりよく区民に使いやすくなったんですよという、ハードルが高いんじゃないかと言っていることに対しても、もう少し丁寧な答弁があってしかるべきじゃないかなと思いますので、これは要望としてお願いいたします。","respondent":"長田区民課長","answer":"こういったことが現状で、今年に入ってからの相談件数も、こういった部分の相談がかなり増えてきてあります。","voiceIndex":157,"id":"exchange-064"},{"speaker":"大西委員","kind":"質問","question":"もうこれはあやしいというのが一目瞭然で私は思うんですけれども、こういう人たちを、はいこれ、はいこれと手を挙げて、手を挙げてということで洗脳しちゃうというんですか、そういう形で、あるところにみんな連れていって、そして大変高額なものを買わなきゃ損だという思い込みにさせて買わせるということが最近頻発しておるところもあります。そういう点の把握はなさっておられますでしょうか。","respondent":"長田区民課長","answer":"今、委員のお尋ねの、駅頭なんかでキャッチセールスですとか、あるいは霊感商法、こういったものがやられているのも事実です。こういったものに対しては、私どもといたしましては、できるだけそういう被害に遭わないようにというようなことで、機会をとらえてＰＲをしています。","voiceIndex":159,"id":"exchange-065"},{"speaker":"大西委員","kind":"質問・要望","question":"布団を１個買うと、次から次に業者が尋ねてきて、布団を１人で住んでいるのに８組も買っているという例もあります。しかしながら、現実的には指導助手の数が少な過ぎて、私はちょっと人数が足りないんじゃないかな、もう少しアルバイトの学生でも何でもいいんですけれども、少しこれは人数を増やしてきめ細かなサービスをしてもらえればと思うんですけれども、その辺どうでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-066"},{"speaker":"嶋委員","kind":"質問・要望","question":"私のほうからは盛りだくさんで、６項目についてお尋ねいたします。二つ目には２２９ページ、保健事業費、三つ目には ２３３ページ、精神保健費から地域生活支援センター整備についてお伺いします。四つ目には２６１ページ、都市型観光推進事業について、五つ目には、ちょっと余り表現が好きではありませんが、公衆便所について、それから６番目にはペットボトル回収についてお伺いをいたします。","respondent":"田中健康課長","answer":"今のご質問の件は、区のほうのかかわりといいますか、ちょっとどこの事業かがわかないので、今もう一度お願いしたいと思います。","voiceIndex":166,"id":"exchange-067"},{"speaker":"嶋委員","kind":"質問・要望","question":"済みません、早口で大変申しわけない、聞きづらいということで申しわけございません、今回小児科が電話を通じて、夜間や休日にも相談に応じる電話相談事業が４月からスタートする、これは準備が整い次第、もちろん都道府県からスタートして、全国どこでも短縮番号ダイヤル＃８０００を押すと居住地域の小児科の携帯番号につながっていくという。","respondent":"田中健康課長","answer":"今お尋ねの件につきましては、品川区のほうには内容的なものがまだ来てございませんので、申しわけありませんです。そういう意味では、東京都がひまわりという医療情報で紹介システムを持ってありますので、夜間等はそれで対応することが可能というふうに以前から制度はあります。","voiceIndex":168,"id":"exchange-068"},{"speaker":"嶋委員","kind":"質問・要望","question":"小児医療の体制の充実、そういう意味では、近くから本当に小児科がなくなっていくということで、お母さん方が心配していることです。そういう意味で、小児科の確保と人材の確保という意味では、品川区はどのようにお考えか、お聞かせいただきたいと思います。","respondent":"田中健康課長","answer":"そういう意味で、現在、小児科が非常に経営上とかいろいろな問題がございまして、減りつつあるというふうな問題もありますが、小児に対する救急的なもののニーズは非常に高うございまして、平日の小児の夜間診療ですとか。","voiceIndex":170,"id":"exchange-069"},{"speaker":"嶋委員","kind":"質問・要望","question":"ますます小児科、お母さんの子育て支援の安心ということで、ぜひ拡充を、体制の充実をしていただくよう、よろしくお願いいたします。二つ目の保健事業費についてお伺いをいたします。そういう意味では、平成１６年度の品川区の地域の保健サービスについて、お話を聞かせていただきたいと思います。ご決意でも結構なんですが、品川区の独自のものがあれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":172,"id":"exchange-070"},{"speaker":"嶋委員","kind":"質問・要望","question":"健康の仕組みということで、大変すばらしいことなので、ぜひよろしくお願いをいたします。そういう中で、私も一般質問で品川区の死亡は乳がんが１位ですが、今はやはり脳卒中がいろいろやっぱりもう一歩対策として脳卒中の予防が必要ではないかということであります。今後お考えがあるのかをちょっとお聞かせをいただきたいと考えています。","respondent":"小林品川区保健センター保健サービス課長","answer":"脳卒中の基礎になるものといいますのは、高血圧ですとか高脂血症といったものですので、この血圧の高い方、高脂血症のある方、それから糖尿病で血管が動脈硬化を促進していくということで、そういった疾患の早期発見になっておりますし、そういった病気を予防するために。","voiceIndex":176,"id":"exchange-071"},{"speaker":"嶋委員","kind":"質問・要望","question":"２３０ページの精神保健費ということで、地域生活支援センターということで、いよいよ品川区も大崎第一地域センターの跡地をかえて、法人化をすることで今進めていらっしゃると思います。そういう意味で、今回つくられる、法人を立ち上げていくこの精神障害者のいわゆる生活支援センターを、ちょっとわかっている範囲でよろしいですので、内容をお聞かせをいただきたいと思います。","respondent":"田中健康課長","answer":"ホームヘルプも始まりましたし、グループホーム等のものもあります。それから医療との関係等の相談、指導、助言、こういうものを目指して皆さんの社会復帰をバックアップしたいというふうに考えておるところです。","voiceIndex":178,"id":"exchange-072"},{"speaker":"嶋委員","kind":"質問・要望","question":"わかりました。いやし系の環境整備ということで、お考えがあったらぜひ進めていただきたいと考えていますので、正式にいろんな形がなったときにお考えをまたお聞かせをいただきたいと考えていますので、よろしくお願いいたします。済みません、時間がなくて、前に進ませていただきます。２６１ページの都市型観光推進事業ということで、今までも委員がいろいろな意味でお話をされております。","respondent":"榎本行財政改革担当課長","answer":"公園等の地域もありますけれども、その中で、あの地域に本当にそういう高いものが建てられるかどうかという規制等もありますので、その辺も勘案して、今後の検討課題とさせていただきたいと思います。","voiceIndex":180,"id":"exchange-073"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひ実現をさせていただきたいと考えています。私もちょっとすぐ行けなかったものですから、今朝行ってまいりました。やはり女性用のトイレでございましたけれども、二つあって一つがやはり大変汚くて、とても使用する状況じゃなくて、そういう意味では、観光またしながわ区民公園の入り口ということで、ぜひこのトイレの清掃とか、そういう整備をどのようにされていらっしゃるのか、お伺いをします。","respondent":"松代道路公園課長","answer":"今後ちょっと検討させていただければと思います。","voiceIndex":182,"id":"exchange-074"},{"speaker":"嶋委員","kind":"質問・要望","question":"折り畳みの簡単な３０cmのものですので、ボルトやねじでつけられるものですので、ぜひご検討をいただきたいと考えています。それからあと、項目に公衆便所と書いてありますが、公衆トイレでは表現はいいのか悪いのかをちょっとお聞かせをいただきたいと思います。","respondent":"松代道路公園課長","answer":"名称の問題ですけれども、一応こちらは法令上の廃棄物の処理および清掃に関する法律だとか、あと私どもの品川区公衆便所の設置および管理に関する条例とか、そういったものを根拠にやってございまして、そこの中で公衆便所というようなことで、整理をしています。","voiceIndex":184,"id":"exchange-075"},{"speaker":"嶋委員","kind":"質問・要望","question":"わかりました。各家庭のいろいろな集積所には、シールを外し、キャップを外し、中を洗って踏んで、ペチャンコにして捨てる。そうしますと、それがあると必ずキャップを外して入れるというのが、捨てる人が自然にキャップを外してここに入れるんだなという認識ができますので、そういうのを、これから品川区にもぜひ配置をしていただきたいと考えていますが、いかがでしょうか。","respondent":"中山清掃リサイクル課長","answer":"キャップを外す場所の設置、これは事業者の負担でコンビニ等でやっていただいている部分ですけれども、確かにそういうものがあれば、きちんとより外すというのが自然にできるという部分もあるかと思いますので、そういうお店等への持ちかけをぜひやっていきたいと考えています。","voiceIndex":186,"id":"exchange-076"},{"speaker":"西本委員","kind":"質問","question":"私のほうからは、２３９ページのかかりつけ医機能推進事業と、かかりつけ歯科医機能推進事業、それから２４７ページの品川区版環境にやさしいシステム、学校ＩＳＯ、家庭ＩＳＯについてお聞きしたいと思います。","respondent":"田中健康課長","answer":"その中でも、特に在宅で療養されている方につきまして、現在までそういう方のための訪問歯科診療というものが高齢者を中心にあったわけですけれども、その部分を大きなファクターで見直しをする中で、新たな意味でのそういう紹介を含めた機能を。","voiceIndex":189,"id":"exchange-077"},{"speaker":"西本委員","kind":"意見","question":"かかりつけ歯科医のシステムのほうが変わるということなんですが、その中で、特に窓口の設置というところがかかりつけの歯科医の紹介という形になろうかと思うんですが、この辺のやり方といいますか、どういう形で紹介をしていくのか、そこら辺はこれからどういうふうにつくられていくのか、ご説明をお願いいたします。","respondent":"田中健康課長","answer":"今回新たに考えておりますのは、受付の段階から委託をして、そういう意味でのシステムを歯科医師会のほうでやっていただこうという考え方です。","voiceIndex":191,"id":"exchange-078"},{"speaker":"西本委員","kind":"質問","question":"すべてが歯科医師会のほうに登録されているとは思えないところもありますので、そこら辺の紹介の仕方であるとか、それは地域の歯科医師の方たちとのやりとりとかというのをこれからどういうふうな形をとっていかれようとしているんでしょうか。","respondent":"田中健康課長","answer":"今、検討に向けまして、品川と荏原の両歯科医師会のほうで、各診療所に、例えば標榜の小児歯科ですとか、口腔歯科ですとか、そういう形のものですとか、それから、車いす対応ができるかとか、いろんなアンケートをとる作業を現在始めております。","voiceIndex":193,"id":"exchange-079"},{"speaker":"西本委員","kind":"質問","question":"非常にかえって難しいという点があります。そこら辺を歯科医師会のほうで把握をし、適切な判断がされて、きちっとした形で障害者の方たちが相談されたときに適切なアドバイスができるという形までできるようなことは考えておられるのか、そこら辺はいかがでしょうか。","respondent":"田中健康課長","answer":"ちょっと私どもは事務的なベースで、歯科医師会のほうで内部の各診療所のアンケートを今やっているんですが、その中では、例えば視覚障害の方、聴覚障害の方等々を治療したことがあるか、それとも対応ができるか、これはいろいろな形の知的障害の方ですとか。","voiceIndex":195,"id":"exchange-080"},{"speaker":"西本委員","kind":"質問・要望","question":"そこも今アンケートをとられているという状況ですので、わりかし子どもに対して熱心にされている医者もあろうかと思いますので、その辺も考慮していただいて、ぜひ区民のために有効に活用していただけるようにお願いしたいというふうに思っております。次に、学校ＩＳＯ、家庭ＩＳＯという形なんですが、これの内容、それから進め方をちょっとご説明をお願いしたいと思います。","respondent":"上山ＩＳＯ担当課長","answer":"具体的には、学校ＩＳＯにつきましては平成１６年度から全校で実施をいたしまして、１年間の取り組みを終えた後、区のほうにご報告をいただいて認定証を交付する、そういったことです。","voiceIndex":197,"id":"exchange-081"},{"speaker":"西本委員","kind":"質問・要望","question":"７校で実施したということなんですね。これを踏まえて拡大という形、学校ＩＳＯのほうについてはそうだと思いますけれども、どういう内容だったのか、どういう取り組みでどういう効果があったので、それを小学校全校に、それでさらに家庭へというふうに至ったのか、ちょっともう少し具体的なところを教えていただきたいと思います。","respondent":"上山ＩＳＯ担当課長","answer":"品川版学校ＩＳＯにつきましては、今年７校でモデルを実施いたしました。具体的なモデル校の取り組み例を取り上げますと、例えば省エネ、省資源につきましては、冷暖房や照明のスイッチを小まめに切るなどの方法により、電気やガスを節約します。手洗いの水量を細めに調整する。","voiceIndex":199,"id":"exchange-082"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろと取り組みがなされて効果があったということなんですが、その取り組みによって、例えば省エネという形で考えた場合に、どれだけ消費削減になったのかということは当然必要になってこようかと思います。そこら辺のＰＲと、それから予算が計上されているんですが、どういったところにこれが使われていくのかをちょっと教えていただきたいと思います。","respondent":"上山ＩＳＯ担当課長","answer":"学校の先生方からは、具体的に数値化があらわれてくるので、児童にとっても非常に理解されやすいし、励みになるというようなお言葉もいただいておりますので、４０校全校実施に当たりましても今回のモデル校の実施例を行っていきたいというふうに考えております。","voiceIndex":201,"id":"exchange-083"},{"speaker":"原委員","kind":"質問","question":"私のほうからは３点お伺いをします。衛生費が１点、産業経済費が２点ということです。衛生費のほうは２３９ページに該当するのかなと思うんですが、保健所管理運営費になるのかなということで、東京都のほうの担当だとは思うんですが、薬物の乱用防止対策ということについてお伺いをします。そこで、東京都の脱法ドラッグ対策取組方針というのがこの２月２６日に健康局より出されております。","respondent":"島袋品川区保健所衛生課長、市川産業振興課長","answer":"それからあとは、特別調査班を編成しまして、重点的な監視指導を実施していく。それから情報収集推進員、情報ウォッチャーというのにつきまして情報連絡体制を整備していく。この２００万円は、先ほど大崎図書館でのビジネス支援の場面で、各分野にわたるＮＰＯの協働で支援事業をやっていただきたいという具体的な中身として、年間を通じて講演会、講座を開いていただく費用、それから。","voiceIndex":204,"id":"exchange-084"},{"speaker":"原委員","kind":"質問","question":"大崎の図書館のほうですけれども、なぜ大崎図書館で始められるかというちょっと質問に対してお答えがなかったので、後ほどいただければと思いますけれども、いろいろなＮＰＯを連携をした形でここで力を発揮していただこうと、こういう形でそこには恐らくコーディネーターが必要だろうと思うんですが、そのコーディネーターはどういう形で、ここにお呼びをしてきて。","respondent":"島袋品川区保健所衛生課長","answer":"脱法ドラッグに関する調査の件ですけれども、区独自でやっているということではございませんけれども、東京都のほうで、最近先ほど委員のおっしゃったインターネットで買えるということで、それは都の研究センターのほうで調査をする、そのようなことをやっております。","voiceIndex":207,"id":"exchange-085"},{"speaker":"原委員","kind":"質問・要望","question":"区のほうも指導員を中心にして事務局の拡充を図るですので、ぜひぜひ特にこの学生、要するに生徒、青少年に対する考え方をしっかり持っていただいて、あくまでもそこの手を出さないような形をぜひぜひ教育現場でもつくっていただきたいというふうに要望をいたしておきます。ですから、そのところが一番肝心なところじゃないかなと思います。これも要望です。","respondent":"古里品川図書館長","answer":"その後の使用状況、それからデータベースをもっとご利用なさりたいというご要望があった場合に、有料等も視野に入れて検討していかなければならないかなというふうに考えております。","voiceIndex":214,"id":"exchange-086"},{"speaker":"原委員","kind":"質問","question":"最後にもう１点お伺いをするんですけれども、西大井のベンチャー支援事業もそうですし、それから、ここのビジネス産業の、この大崎図書館もそうですし、ものづくりに対する大きな期待感というのが今後の中で十分出てきているわけなんですが、区内のものづくりの地図、こういうところではこういうものづくりをしていますよという、そういうような作成をするような考えは、今後の中ではいかがでございましょう。","respondent":"市川産業振興課長","answer":"その辺をちょっとにらみ合わせながら、今ご質問いただいた趣旨について、品川区のものづくりということの情報発信という観点で、今後の検討課題とさせていただきたいと思います。","voiceIndex":216,"id":"exchange-087"},{"speaker":"菊地委員","kind":"質問・要望","question":"先に融資のあっせん事業の問題ですけれども、午前中に何人かの委員の皆さんとの質疑がありましたけれども、その中で、制度融資を、これは全体だと思いますけれども、２０％の否決率があるんだというお話がありましたけれども、これが実際に今の不況の状況下の中で多いのか、少ないのか、この辺の見解を少しお話をしていただければなというふうに思います。","respondent":"市川産業振興課長","answer":"信用保証の否決に関するお尋ねですが、２０％近い数字が多いのか少ないのかですけれども、これは午前中の答弁のときにも申し上げたことですが、融資の利用申し込みの絶対数が年々増えてあります。","voiceIndex":219,"id":"exchange-088"},{"speaker":"菊地委員","kind":"質問","question":"なかなか厳しい不況の中で、実際に返せなくなるというケースは多々あるというようなお話ですけれども、実際にこういう状況の中で、じゃあ、どういう融資の制度がいいのかという、先ほど一本化の話もありましたけれども、実際にこういう状況が廃業、倒産という形につながっていく現象だと思いますけれども。","respondent":"市川産業振興課長","answer":"返済期間の長い融資メニューを用意できないかですけれども、今の金融環境から申し上げますと、返済期間を長くすると、これは業種とか業態によっても大分違いますけれども、必ずしも利用者にとって有利なわけではございませんで。","voiceIndex":221,"id":"exchange-089"},{"speaker":"菊地委員","kind":"提案","question":"商店街の問題なんですが、これは２日目でしたでしょうか、他の委員の方もお聞きしていたんですけれども、今、商店街のど真ん中にマンションがどんと立ち上がって、ワンルームが多いようですけれども、今回の建設委員会の中でも戸越の商店街にマンションが立つということで請願が出ておりましたし、大井町駅近くのすずらん通り商店街にも今マンションが建設をされておりまして。","respondent":"市川産業振興課長","answer":"ただ、個々の相談事例に応じてこれまでも対応してきたところですけれども、やはりこの問題については、商店街の当事者能力と申しましょうか、組織としての力がどれだけついているか、ここのところが一つのポイントになるもんだというふうに考えてあります。","voiceIndex":223,"id":"exchange-090"},{"speaker":"菊地委員","kind":"質問・要望","question":"商店街に建てるマンションに対して、区の指導指針ですとかそういったもので、一定程度１階の一部は店にしてほしいとか、そういう指導指針的なものを、もし可能であれば考えていただきたいなというふうに思います。","respondent":"島袋品川区保健所衛生課長","answer":"そのときに水をかけられたんですけれども、状況としましては、ごみ屋敷というよりも発泡スチロールをいっぱい並べていまして、そこに水をいっぱい入れておくという、直接私どもは警察権限がありませんけれども、衛生上の指導ということで、２人行きました。","voiceIndex":225,"id":"exchange-091"},{"speaker":"菊地委員","kind":"意見","question":"先ほど隣にはしごをかけられたお宅で苦情を言ったところ、何やらその発泡スチロール類についても全部庭に投げ込まれたとか、そんな話も聞いています。それから、今、発泡スチロールに水を入れているという話がありましたけれども、あれも道路に散乱をするという状況があるようです。こういう問題が、悪質なケースというのかどうかわかりませんけれども、ぜひ指導の強化をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":227,"id":"exchange-092"},{"speaker":"木下委員","kind":"質問","question":"初めに、また鳥かと言われるかもしれないんですけれども、鳥インフルエンザの件について、先ほど何人かの委員のほうからもこのことについて質問があったかと思うんですけれども、途中、都と連携して情報収集に当たっているということで、その後どういうふうな対策をされるのかということをちょっと聞いておりませんでしたものですから、なぜかといいますと。","respondent":"島袋品川区保健所衛生課長","answer":"現段階では、先ほど申したとおりに、まず鳥が死んでいるとか、小鳥が弱っているとか、そういう情報を個々に集めて、それを東京都のほうにまとめるということで、それ以後の、例えばどこか同じ地区で大量の死が続いたとか、そういう情報を把握した場合には。","voiceIndex":230,"id":"exchange-093"},{"speaker":"木下委員","kind":"質問","question":"こういう場合、例えば警察がそれを引き取った際に、すぐ消毒して回ったですとか、そういうのも紙面に書かれていたんですが、ただ聞いてそれをやるというだけじゃなしに、すぐ対応として、消毒ですとか、そういう何らかの処置というのはおやりになられるんでしょうか。","respondent":"島袋品川区保健所衛生課長","answer":"インフルエンザが陽性だという場合には、当然家畜保健衛生所のほうで消毒等をやります。","voiceIndex":232,"id":"exchange-094"},{"speaker":"木下委員","kind":"質問","question":"わかりました。時間もあることですので、次に移らします。廃棄物対策費、先ほど鳥インフルエンザでカラスのお話をさせていただきましたけれども、各戸収集、区内の７０％になられるということで、これはカラス対策でもあると、平成１３年度比でカラス被害が半分になるという話を聞いたんですが、何件が何件になって半分になったのか、ここら辺をちょっとお聞かせ願えますでしょうか。","respondent":"中山清掃リサイクル課長","answer":"これは１日の調査ですから、ずっと捕捉、継続的にやっているから、これをすべてうのみにしていいのかという部分はありますが、平成１３年度に集積所の中で、要するに被害を受けた場所というのが約４％という数値でございました。","voiceIndex":234,"id":"exchange-095"},{"speaker":"木下委員","kind":"質問","question":"これからも各戸収集のほう、できるだけ早めに１００％行けるようにお願いをしたいと思います。先ほど品川区が持ち去り禁止のシールを張る云々という話がありましたけれども、こういう形でいい結果が出ている、持ち去り禁止条例ですとか、そのことについて区の考え方としてはいかが考えていらっしゃるのか、お聞きしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"したがって、区としても、条例の検討もさることながら、実効ある対応というものをまず先行しようというのが現段階の考えです。","voiceIndex":236,"id":"exchange-096"},{"speaker":"木下委員","kind":"質問","question":"実効ある対応をしようということは、持ち去り禁止ということで、それはパトロールですとか、そういうのを行おうだとか、何か強化しようという意味合いでしょうか。","respondent":"中山清掃リサイクル課長","answer":"それで、今これはいろいろ詰めが必要だと思っていますが、仮に継続的に見回るにしても、そういう行政が直接対応を、職員がある種時間をかけてやるというよりは、もう少し区内、例えば企業のようなきちんとシステムとしてコントロールできるようなところと連携をとるというふうな。","voiceIndex":238,"id":"exchange-097"},{"speaker":"木下委員","kind":"質問・要望","question":"１日一生懸命やっても二、三千円になるかならないかでやっていらっしゃる方なんか見ると、そういう方々は、その持ち去り禁止というシール普及によって、そういう方々、弱者の対策等なんかは少しは考えていらっしゃるのでしょうか。","respondent":"中山清掃リサイクル課長","answer":"したがって、先ほど申し上げたとおり、資源回収に分別して協力することがばかばかしいというふうに思われるようなことは決してないようにやっていこうですので、したがって、あえて業者であるとか規模の大小だとか、そういう生活の状況によって。","voiceIndex":240,"id":"exchange-098"},{"speaker":"木下委員","kind":"質問","question":"続きまして、商工費の中小企業対策費のほうに移らします。既存のスーパーも落ちている。そういう地域の声に対して、何か助成ですとかそういう部分、区としてはお考えがあるのかどうなのか、またそういうような地域からシンボル的なものでもって、商店街ですとか地域の活性化を図るという場合には、またその応援等を考えていらっしゃるのか、ちょっとお聞かせ願えますでしょうか。","respondent":"市川産業振興課長","answer":"一概にこれがこうだというルールはないと思いますけれども、基本的に、やはり商店街の商いの道具として設定するのは、負担の原則はやはり商いをする者が負担をする。その上で、行政としてどういう支援が可能なのか、こういった検討の手順になろうかと思います。","voiceIndex":242,"id":"exchange-099"},{"speaker":"木下委員","kind":"質問","question":"やはりそれはその地域の方々が負担するというのは、それは原則なんですけれども、ゴジラの、そういうのをつくるとなると四、五千万かかるような話も聞いておりますし、そういうまちづくり協議会ですとか商店街の方々の努力だけじゃ、なかなかそれをクリアできない部分もありますから、音頭取りですとか、そういう部分でご協力していただければなというふうに思いますけれども、そういう点はいかがでしょうか。","respondent":"市川産業振興課長","answer":"むしろ、私どもが行政が今一番力を入れているのは、その商店街の底力に相当する商店街の基礎体力、これをまずつけることが必要だと思いまして、各種の支援策を講じているところです。","voiceIndex":244,"id":"exchange-100"},{"speaker":"木下委員","kind":"意見","question":"区のほうの考え方はよく理解できました。やはりそういう人参でつってもなかなかその後リピーターといいますか、やっぱりここへ来て楽しかったというのがないと、例えば六本木ヒルズなんかにしても、なかなかあれだけの集客はできなかったんじゃないかなと思いますので、これからも商店街の活性化といいますか、基礎体力づくりにお力をかしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":246,"id":"exchange-101"},{"speaker":"田中委員","kind":"質問・要望","question":"その中には、メリットとしてコストの軽減が図れる、これは既存の商店街の更新に合わせてということですが、またそのシステム構築を、新たに参入する商店街にとってもそういうメリットがあるということ、また複数商店街のカードを持たずに１枚で対応がとれるというようなことが書いてありますが、改めまして、今回のポイントカードシステム導入に対するメリットをどのように認識されているのか。","respondent":"市川産業振興課長","answer":"この学習をしたそもそものきっかけというのは、単独にポイントカード事業を実施している商店街にとって、大体４年ないし５年でシステムのリニューアルという問題があります。","voiceIndex":248,"id":"exchange-102"},{"speaker":"田中委員","kind":"質問・要望","question":"そんな中で、区としての役割は、いかに共通のカードシステムを構築し、共通のインフラを構築した後に、より適切な形での各商店街での独自性をどのように発揮させていくかという、その区としての役割はそういった、それぞれの商店街に対する指導というんでしょうか、そういったものが今後求められてくるのかなと考えていますが、そこまでの、その点について、それぞれお考えをお聞かせいただきたいと思います。","respondent":"市川産業振興課長","answer":"今委員からご指摘がありましたけれども、いかにこういった高機能を持ったカードを商店街全体の利益として使っていくのかということの議論に結びつけていく、これが私ども一つ行政の役割かと認識をしています。","voiceIndex":250,"id":"exchange-103"},{"speaker":"田中委員","kind":"質問・要望","question":"そのときに私も一般質問をした記憶がありますが、そのときの区の役割としては、区内への区民に対する一斉売り出しの呼びかけだけではなくて、場合によっては区外の近隣区に対する発信というものもそのときは必要だったんではないかなという思いがあるんですが、今のお話、まさにインフラが共通化することによって、お客さんの囲い込みが非常に難しくなるということに対しては、やはり区はどういうツール。","respondent":"市川産業振興課長","answer":"ただ、そのときに、使うほうと使われたほうの利害なり思惑が一致するかどうか、この辺が今後の検討課題だというふうに認識しています。","voiceIndex":252,"id":"exchange-104"},{"speaker":"田中委員","kind":"質問・要望","question":"そういった、このＩＣ機能をより発展させて活用していく上でも、そういう観点からも、区の指導といいますか、区の役割というのはまだまだたくさんあるのかなと考えていますので、ぜひ将来的なことに向けての抱負といいますか、意気込みをお聞かせをいただきたいと思います。","respondent":"市川産業振興課長","answer":"今後の検討に当たりましては、今多々ご指摘のあった点も含めて、商店街の活性化につながる有効策として進めてまいりたいと思ってあります。","voiceIndex":254,"id":"exchange-105"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。私が取り上げたいのはこのことではなくて、先日の林委員長の一般質問にもございましたし、昨日、山村委員からの質問もありましたが、かかりつけ薬局ということに関して少し触れていきたいと思います。一方、一番最初に申し上げた、一般用の医薬品が小売店でも販売されるとなると、いわゆる重複による副作用というんでしょうか、が心配されるということで、懸念があります。","respondent":"寺西品川区保健所保健サービス課長","answer":"将来の課題として、今言われたように薬を一つのかかりつけの薬局を持たれて、その薬剤師の方が管理していくというのは非常にすばらしい制度だと思いますが、区としてどういう仕事をしていくかということに関しては、今後の課題かなと考えています。","voiceIndex":256,"id":"exchange-106"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ、まず必要性の認識を共通に持っていただきたいなということ、また、じゃあ区が何をするかということは、ぜひ今後の課題で検討をいただきたいんですが、まずは薬歴管理の必要性を広報していただくというんでしょうか、区民に対してその必要性があるということをお知らせをするという広報活動というんでしょうか、そういった観点からぜひ進めていっていただきたいな、そのことが認知された上で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":258,"id":"exchange-107"},{"speaker":"山路委員","kind":"質問","question":"最初に給水施設監視指導ですが、今までは予算書に受水層とか水質検査とか、あるいは溢水検査とか、いろいろ載っていたんですが、平成１６年度の予算には載っていないんですけれども、ブースターが普及しまして受水層が要らなくなった家がかなり多いのかなともちょっと感じたんですけれども、その辺の衛生試験の機能はどういうふうになっているか、説明していただけますでしょうか。","respondent":"島袋品川区保健所衛生課長","answer":"給水施設監視指導の件数のことですけれども、従来から予算書のほうには件数は載っていなかったです。","voiceIndex":260,"id":"exchange-108"},{"speaker":"山路委員","kind":"提案","question":"わかりました。いずれにいたしましても、安全な水ということで、飲み水は検査のほうをしっかりよろしくお願い申し上げます。続きまして、品川区版の環境にやさしいシステムにつきまして、環境ＩＳＯといいますと、我が党の三上委員初め各委員が機会あるごとに学校版、家庭版ということで、平成１２年の第２回定例会以来、細かく提案をしてまいりました。","respondent":"上山ＩＳＯ担当課長","answer":"生徒と家庭への還元をどのように考えているかですけれども、ＩＳＯの仕組み自体が、先ほども申し上げましたように継続的な改善ということに大きく特徴を持っております。","voiceIndex":262,"id":"exchange-109"},{"speaker":"山路委員","kind":"質問・要望","question":"区の取得にも、大きな目的の一つが児童・生徒を初め区民意識の啓発を一層図るですので、情報のネットワーク化をさらに進めて環境に取り組んでいっていただきたいと思います。続きまして、廃棄物対策費に関連いたしまして、全体で言いますと大きなことになりますが、世界的にゼロエミッションという研究構想がありますね。それについてちょっと認識を説明していただけますでしょうか。","respondent":"中山清掃リサイクル課長","answer":"廃棄物、ごみの減量等と言われておりますけれども、基本的にはもうなくすことを目指す、廃棄物ゼロを重大な使命、目標として、いろいろな取り組みをやっていくという取り組みであるというふうに認識しております。","voiceIndex":264,"id":"exchange-110"},{"speaker":"山路委員","kind":"質問・要望","question":"日本におきましても、文部科学省、経済産業省とか、それぞれゼロエミッション技術の開発に乗り出しております。それで、本を読んだ範囲ですけれども、フランスではビールをつくって、そのかすといいますか、その廃棄物にお金が非常にかかって処理に困っていた。関東にもごみをなくしていこうという研究構想があるそうですが、それにつきまして、お知りでしたら、ちょっと説明していただきたいと思います。","respondent":"中山清掃リサイクル課長","answer":"ゼロエミッションというのは、非常に企業、自治体の中にも目標としてという部分はありますが、組織立ってそういうものが立ち上げられているのは、申しわけございませんが、情報をまだ入手してございません。","voiceIndex":266,"id":"exchange-111"},{"speaker":"山路委員","kind":"質問・要望","question":"今後のこれは検討課題と思いますが、市町村と企業と、それと工場が組みまして、ごみを循環型社会を真に目指していこうということで、埼玉県にあるそうですので、今後これが大きくなりますと、さらに資源型、ごみを少なくしていくシステムが可能になってくるかと思いますので、研究をしていただきたいと思います。続いて、チャレンジマート事業につきまして説明をしていただきたいと思います。","respondent":"市川産業振興課長","answer":"比較的広い幅で事業内容が決められる制度です。それで、初年度において、施設改修費１,０００万円、その他家賃補助、販促経費、こういったものを補助いたしまして、家賃補助のみ３年間継続いたします。","voiceIndex":268,"id":"exchange-112"},{"speaker":"山路委員","kind":"質問","question":"先日、町会の方とお話ししていたら、高齢者の方が、今まで安いところか、品物の多いところに買い物に行っていた。足が大分弱くなって、もう行けなくなったんで、地元の商店街に買いに行った。その地元にない品物を売ってくれる、例えば魚屋がなかったら魚屋を広く品川区から募集して、そこで売ってもらうような調整をできないかという話があったんですが、どのようにお考えでしょうか。","respondent":"市川産業振興課長","answer":"そのご商売の採算性、これはその店舗の立地ですとか商圏範囲、こういったものが非常に関連してまいりますので、難しい問題ではありますけれども、地元の商店街からそういう意味での相談があれば、私どもその相談に乗っていく、こういう体制にはあります。","voiceIndex":270,"id":"exchange-113"},{"speaker":"井上委員","kind":"提案","question":"私のほうからは、衛生費の２３２ページ、環境衛生費、２４５ページ、環境啓発事業、ノーレジ袋運動推進事業、そして２４６ページ、リサイクル推進費、２５４ページの廃棄物対策費について伺います。私もホームページで見ましたけれども、そのことについてはどういうことなのかということと、遺伝子組み換え表示の監視などについてもどのようなお考えがあるのか、お聞かせください。","respondent":"島袋品川区保健所衛生課長","answer":"〔「遺伝子組み換えについて」と呼ぶ者あり〕遺伝子組み換えの件ですけれども、この監視計画の中の適正な食品表示への対策ということで、この中に遺伝子組み換えに関する表示の問題等を重点的に監視項目としていきたいなと考えているところです。","voiceIndex":273,"id":"exchange-114"},{"speaker":"井上委員","kind":"質問・要望","question":"意見交換の時期が未定ということで、お答えがなかったんですけれども、ちょっとあとがたくさんありますので、後ほど伺わせていただきたいと思います。前回は昨年度の場合は小型プレス車が５台分ということだったんですけれども、平成１８年度末全域に拡大されたときに、この小型プレス車はどのぐらいの見込みをされているのかということをお聞かせください。","respondent":"島袋品川区保健所衛生課長、中山清掃リサイクル課長","answer":"例年消費者懇談会というのをやっておりますので、それを今年もやったんですけれども、ちょっとやり方をいろいろ考えて、工夫してやっていきたいと考えています。ですから、確実な数というのは、ちょっとその段階の作業計画と申しますけれども、係数化にゆだねていきたいと思いますが、今現在、直営、雇い上げを含めて、ほぼ１００台近くの車両がごみと資源で稼働しておりますので。","voiceIndex":275,"id":"exchange-115"},{"speaker":"井上委員","kind":"質問","question":"各戸収集の拡大によって増える分というのは、少し見込みとしてはわかりますでしょうか。","respondent":"中山清掃リサイクル課長","answer":"約７割というところでこの１０台というのが出ておりますから、これにもう数台加算かなというふうには思われます。","voiceIndex":278,"id":"exchange-116"},{"speaker":"井上委員","kind":"質問","question":"平成１３年度の場合には、ふれあいサポートシステムとの連携という事業が各戸収集にはついておりましたけれども、この事業についての連携というのはどうなっているんでしょうか。","respondent":"中山清掃リサイクル課長","answer":"こういうものについては、非常に地域のある種の弱者の方の情報ですので、地域センターを通じて、この情報を清掃事務所から送っていく、こういう意味の連携ですので、これについては引き続きやってあります。","voiceIndex":280,"id":"exchange-117"},{"speaker":"井上委員","kind":"質問","question":"２億円の経費を今回１億９,７００万程度あるわけですから、かけているんですが、これによるごみの減量の効果をどのように推測されていますでしょうか。","respondent":"中山清掃リサイクル課長","answer":"このエリアだけの数値というのもなかなかとるのは難しゅうありますけれども、モデル実施をやった際に、６ないし８％ほどのごみの減量という数値が出ておりました。それで、現在のごみの量が微減という状態です。１％から２％減るかどうか。","voiceIndex":282,"id":"exchange-118"},{"speaker":"井上委員","kind":"質問・要望","question":"費用対効果というところでは、さらに検討を加えていっていただきたいと思います。それから、ペットボトルの回収の拡大なんですが、２００４年度１０月からペットボトルの回収を全集積所１万５００カ所で始めます。それで、資源回収で、とりわけペットボトルの資源化コストは一番かかるんですけれども、拡大に踏み切った基本的な考え方をお示しください。","respondent":"中山清掃リサイクル課長","answer":"したがって、モデル事業の検証もやりつつであったんですけれども、かなり中間処理のコスト等もこの間下げられる見込みも出てまいりましたので、区民の方の資源であるという思いに着目して、今回もう思い切って全面的に集積所回収を進めようと判断した次第です。","voiceIndex":284,"id":"exchange-119"},{"speaker":"井上委員","kind":"質問","question":"そういう意味では大変お金がかかるということを、もう少し区民の方も知るべきだと思うんですけれども、今回、ペットボトルは大井ストックヤードの古紙を処理するところで代用していますが、回収量が増えるということは保管場所も不足するということ、また梱包機材をどうするのかという問題がもう既に持ち上がっているかと思うんですけれども、大井ストックヤード拡大、設備の工事費。","respondent":"中山清掃リサイクル課長","answer":"したがって、これは雇い上げではなくて、基本的に委託でやる予定ですので、これが集積所の回収分の総経費というふうに考えられます。","voiceIndex":286,"id":"exchange-120"},{"speaker":"井上委員","kind":"質問・要望","question":"そういうことをやっぱり知っていただく、また決算特別委員会で品川区として自治体の負担が大きいことをどう考えるかということを質問いたしまして、区長会等で負担軽減を要望しているという回答もいただいたんですけれども、今回のペットボトルの回収拡大というのは、さらに自治体の負担を増やしていくという、考え方としては逆行しているように思うんですけれども、江戸川区なんかは、こういったところで。","respondent":"中山清掃リサイクル課長","answer":"したがって、こういう負担の部分につきましては、午前中の鈴木真澄委員のご質問にも答えましたとおり、事業者の負担の明確化は別の場面では訴えていきたいというふうに考えております。","voiceIndex":288,"id":"exchange-121"},{"speaker":"井上委員","kind":"質問・要望","question":"やっぱりペットボトルを買った方が店舗に持っていくというようなことも、そうすることで税金の負担が少なくなるんだということもやっぱり啓発をしていってほしいということを思います。先ほども答弁がありましたけれども、やっぱり企業がリサイクル費用を負担をする仕組みを徹底することを自治体からさらに要望していただきたいと思います。次はノーレジ袋啓発推進事業について伺います。","respondent":"金井環境課長","answer":"ノーレジ袋運動の目的ですけれども、ご案内のとおり、今日の地球環境の問題も含めまして、品川区といたしましては、環境との共生を目指して循環型社会の転換を図る、この一環といたしまして、使い捨て文化の象徴であるレジ袋について、ノーレジ袋運動という形を展開して。","voiceIndex":290,"id":"exchange-122"},{"speaker":"井上委員","kind":"質問・要望","question":"このノーレジ袋運動は２００２年１０月にスタートいたしまして２年目の事業となるわけですが、早速事務事業評価がＣということになっておりますけれども、どうしてスタートして２年目でＣなのかという理由をお答えいただきたいと思います。見直しの段階では三つ項目がありますが、この三つのうちのどの見直しする事業ということになるのでしょうか。","respondent":"金井環境課長","answer":"今年度はそういう見直しをしながら、省包装でありますとかレジ袋を扱っていないお店、こういったところも対象にしていきましょうですとか、消費者への還元、今２５０枚集めないとなかなか還元になりませんけれども、そういった問題も含めて。","voiceIndex":292,"id":"exchange-123"},{"speaker":"井上委員","kind":"質問・要望","question":"私たちの実感として、商店街はそういう動きになっているのかもしれないんですけれども、なかなか見えてきませんので、この見直しがさらなる拡大ということですので、ぜひ啓発に力を入れていただいて、たかがレジ袋といわず、削減によってＣＯ2がどれだけ削減されたのかということも、先ほどのＩＳＯではないですけれども、子どもたちに知らせるとか、そういった意味でぜひ頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":294,"id":"exchange-124"},{"speaker":"須貝委員","kind":"質問","question":"２４９ページのリサイクル活動についてと、２６１ページ、産業振興についてお伺いいたしたいと思います。従来ごみだったものを資源として回収し、社会にリサイクルさせるもので、今集合住宅が品川区の中に大変増えておりますけれども、その品川区にとって、ごみの減量対策としては現在最も重要な手法であると思いますが、その辺のご見解をまずお聞かせください。","respondent":"中山清掃リサイクル課長","answer":"集合住宅に限った施策というのはとりわけございませんが、ただ、集合住宅の割合というのがどんどん増えてきている中で、例えば保管の仕方、出し方の問題、こういうものについてはきちんとしたスペースを持ち、出し方をきちんとしていただくということは重要なことですので。","voiceIndex":296,"id":"exchange-125"},{"speaker":"須貝委員","kind":"質問","question":"それは続けます。区民が品川区のリサイクル事業のために用意していました資源を民間の業者が持っていく、いわゆる抜き取りですか、一部の自治体では、先ほどまでお話もありましたけれども、条例をつくって抜き取り禁止をしてまで頑張っておりますが、現在、もう時代の流れとしてはどうなんでしょう、リサイクルも民間事業化に進んでいるんじゃないか。ちょっと環境清掃事業部としてご意見をお伺いしたい。","respondent":"中山清掃リサイクル課長、市川産業振興課長","answer":"先ほどのちょっとご質問の中で答えるべきだったかもしれませんが、集団回収というふうなものについてはきちんとルールを決め、日を決め、お金はかけませんけれども。一般論ですけれども、地域雇用が創出されるという前提は、やはりその地域社会のコンセンサス、これが前提になると考えています。","voiceIndex":298,"id":"exchange-126"},{"speaker":"須貝委員","kind":"質問・要望","question":"今お話をお聞きしましたけれども、どうなんでしょう、集団回収、これも有効だというお話もいただきました。そういう方向性をもう考えてもいいんじゃないかなということで、考えていただきたいということで要望しておきます。次に、産業振興についてお聞きしたいと思います。今、ある商店街では、お店の中の８０％がテナント貸しをしているという商店街があります。何が何でも。じゃあどうすればいいんだ。","respondent":"市川産業振興課長","answer":"この今申し上げたことをいかに年間を通じて継続していくか、それで、こういった一つのイメージの上に立って、実際には商店街の中では個店の販売力を強化して、商店街組織としての組織力を強化していく、個店の販売力、商店街組織の組織力を強める、こういった。","voiceIndex":301,"id":"exchange-127"},{"speaker":"須貝委員","kind":"意見","question":"行政でできることとなると、やはり環境をできるだけ構築してやる、お金を出して助成するということがすべてじゃないんで、その辺も今後ともよろしくお願いいたします。最後に、ちょっと後継者の育成について、私の考えもあるんですけれども、どうかなと思いまして、産業振興課の意見をお聞かせ願いたいと思います。子どもに後継として譲りたい。その辺をちょっとお考えをお聞かせください。","respondent":"市川産業振興課長","answer":"そういった特性を生かして、そういう後継者の育成という場面に使えるものがあれば、今後ひとつ検討させていただきたいと思います。","voiceIndex":303,"id":"exchange-128"},{"speaker":"石田委員","kind":"質問","question":"これは非常にいいことで、地域の方もこれをやっていこうとしているんだけれども、点はできるんだけれども、なかなか面的整備に今行っていないのかなと考えていますが、ここら辺のところで、せっかくこういうふうな形で点でも出てきたということで考えていくならば、この点をもう１回行政側がしっかり後押ししてあげて、どうやって広げていくかということを考えていらっしゃると思うんで。","respondent":"田中健康課長","answer":"昨年３月に区民健康づくりプラン品川を示させていただきまして、やはり身近な地域で取り組んでいただける健康づくりをということを一番の目玉にしてございまして、そういう意味では、各地域に今回モデル実施ということで。","voiceIndex":306,"id":"exchange-129"},{"speaker":"石田委員","kind":"質問・要望","question":"昨日も話が出たけれども、筋力向上トレーニングはリハビリでやっていくということなんだけれども、ここら辺の元気な高齢者の方のこういう筋トレ教室というのもさまざまなところで少しずつ始まってきていて、週２回、そういう形でやってきて、千葉なんかは２年間実績をとると、医療費が確実に落ちたというような結果も出ているなんていう例もあるわけで。","respondent":"田中健康課長","answer":"そういう意味で言いますと、今いろいろなメニューをこれからどのような形で組み合わせて、それを地域の原点でどのように組み合わせていくかというのは、これは先ほど申し上げましたふれあいサポートのさまざまな活動とも。","voiceIndex":308,"id":"exchange-130"},{"speaker":"石田委員","kind":"質問・要望","question":"私もそんなになのかなと思っておりましたが、都の動物愛護相談センターで致死処分をしているということなんですが、年間１万何千という話らしいんですが、猫だけでも一時期４万ぐらいのときもあったなんていう形らしいんですが、私がここで言いたいのはモラル的なことで、例えば、どういう区民にそういう飼い方のモラルをやっていらっしゃるのか、年に２回ぐらいやっているのかどうかわかりませんが。","respondent":"島袋品川区保健所衛生課長","answer":"動物のほうの致死処分の件ですけれども、東京都の動物愛護相談センターというところでやってございまして、平成１４年度は１万１,３２２頭を致死処分いたしました。そのうちの９割が、約１万匹が猫だです。","voiceIndex":310,"id":"exchange-131"},{"speaker":"石田委員","kind":"確認","question":"要は売れなくなると言ったほうがいいのかな、そういうことの中で処分をされている犬、猫が結構いるというような話を聞いたんだけれども、それはうそか本当かわからないので、そういうのは確認されているのかどうか教えてください。","respondent":"島袋品川区保健所衛生課長","answer":"そういうときは、先ほど申しました東京都の動物愛護相談センターのほうへということで、区では引き取っていないということをはっきり言っていますので、今、委員のおっしゃった業者云々というのは、ちょっと承っておりません。","voiceIndex":312,"id":"exchange-132"},{"speaker":"石田委員","kind":"質問","question":"それはそれでとめておきますが、ぜひ私もこの数字を聞いてびっくりしていまして、そんなに致死処分されているのかなと考えています。東京都だけでそれですから、ぜひもしそういう関係の話があったら、少しそういう飼い方とかそういう教室の中で、さまざまそういうことがあるんだというのを皆さんに言っていただいて、大切に育ててくださいよというようなことを言っていただければと思います。","respondent":"榎本行財政改革担当課長","answer":"この緊急地域雇用事業につきましては、平成１４年度当初からスタートしまして、総トータルでは１９事業をやってあります。それで、継続的に３年間で終わる事業もありますけれども、それ以外に今後とも継続していかなければいけない考え方に基づくような事業もあります。","voiceIndex":314,"id":"exchange-133"},{"speaker":"石田委員","kind":"意見","question":"この部分の雇用創出は、ここにほかのところに入れていくけれども、ここの部分はないから、違うところで全部そういう補完をしていくのか、ここで得た雇用の分の人数ぐらいは雇用創出で何かほかのところで全部同じぐらいの規模でどこか手当をしていこうとお考えなのか、一つだけとると少なくなっちゃうわけですよ。そこら辺の考え方もどういうふうに考えてられているのか。","respondent":"榎本行財政改革担当課長","answer":"雇用の創出の面からいきますと、確かに例えば戸籍電算化ですともう事業が今年度で終了するということで、その事業自体がなくなってしまうということですけれども、雇用創出の面で、ほかの事業についても幾つか平成１６年度から始まるものもありますので、実際上。","voiceIndex":316,"id":"exchange-134"},{"speaker":"石田委員","kind":"意見","question":"それをこれでお金が出てきているから、これをやっているということではなく、内容から入っていただいて、なおかつこれぐらいのお金を使って来年もやっていくかやっていかないかというような、もちろん事業からあるわけだけれども、せっかくこういう形で雇用創出をしていこうというのであれば、それはある程度、来年度もこれぐらいの規模で残していこうというお考えなのか。","respondent":"市岡企画財政課長","answer":"ただし、一方、例えば商店街のクリニック事業のように、財源がこういう形で１０分の１０来なくても、今後区内の商店街の活性化対策として、どうしても私どもとしてはやらなければいけない、区民の期待も非常に強いものについては一般財源を入れても今後やっていく。","voiceIndex":318,"id":"exchange-135"},{"speaker":"山村委員","kind":"質問","question":"私からは２２６ページ、予防費についてと、２３２ページ、環境衛生費、そして２３９ページの保健所管理運営費、あと時間がありましたら、２５６ページ、中小企業対策費についてお伺いしたいと考えています。そういう意味で、鳥のふんの有害性とかそういうことは、どのようにとらえているのか教えていただければと思います。","respondent":"寺西品川区保健所保健サービス課長","answer":"ですから、今回のカラスでインフルエンザで死亡しているカラスを見つけたという例は、すべて今回は京都の近辺のカラスであったかと思いますが、そういうカラスは確かに鶏舎に入り込んでふんも含めたえさとかをついばんだ可能性はありますが。","voiceIndex":321,"id":"exchange-136"},{"speaker":"山村委員","kind":"質問","question":"ということは、東京のほうまで鳥インフルエンザのカラスが蔓延するようになってきたときに、鳥のふんの処置をある程度していかないと、鳥のふんから人間に感染するという可能性が出てくると思うんですが、その対策とかは今考えられておりますでしょうか。","respondent":"寺西品川区保健所保健サービス課長","answer":"ただ、一番最初のこの委員会でご報告したように、鳥のふんから人への感染力という意味では、今現在でもタイとベトナム以外では全く報告されていない事実から考えて、余りこう不安をあおるような対策というのは難しいかと思いますが、一般的な清掃管理。","voiceIndex":323,"id":"exchange-137"},{"speaker":"山村委員","kind":"意見","question":"他の動物から、猫などからの蔓延ということは、鳥インフルエンザは１９２５年スペイン風邪が、あれは豚に一度うつってからウイルスの形が変異して人間に蔓延したということ、品川区に豚が余り多くいるとは思っていませんので、豚はそんなに心配していないんですが、ＳＡＲＳのことなどを考えますと、猫やほかの動物からも人体にそういう感染症がうつっていく可能性が今後あると思うんですが、それに対しては。","respondent":"寺西品川区保健所保健サービス課長","answer":"鳥あるいは家禽、アヒルであるとか、そういうものに関しての感染力は非常に強いんですが、いわゆる犬であるとか哺乳類のほかの動物に非常に感染力が高いということは現状証明されていないのではないかなと思います。","voiceIndex":325,"id":"exchange-138"},{"speaker":"山村委員","kind":"意見","question":"わかりました。最後に、感染症を想定した危機管理マニュアル、これからは、はやらないことを祈るばかりですが、もし大流行ということになった場合、ＳＡＲＳおよび鳥インフルエンザなどの感染症を想定した危機管理マニュアルというものをつくる予定がありますかどうかをお答えください。","respondent":"島袋品川区保健所衛生課長","answer":"昨年度、健康危機管理マニュアルというのを保健高齢事業部内でつくっておりまして、いわゆる健康危機管理マニュアルをつくっております。それで、感染症についても、感染症が原因が不明のときは健康危機管理マニュアルで職員は対応するということになってあります。","voiceIndex":331,"id":"exchange-139"},{"speaker":"山村委員","kind":"質問","question":"川崎とかだと１００％助成なんですが、今後ＳＡＲＳとか関係して野良猫とかのことの駆除等を考えると、飼い猫の去勢とかの補助はもっと出したほうがいいんじゃないかと私は思っているんですが、今後増加するような考えはあるのかどうかを教えていただけますでしょうか。","respondent":"田中健康課長","answer":"ですから、飼い猫を不妊手術して、それで捨てないということであれば、地域猫と言われるいわゆる野良猫は寿命が五、六年ということなんで、そういう捨て猫をしなければ自然にいなくなるというふうに一般的には言われておりまして。","voiceIndex":333,"id":"exchange-140"},{"speaker":"山村委員","kind":"質問","question":"去勢、増加するかどうかということを質問させていただいたんですが、それは今のお答えでいいとしまして、犬の登録というものを品川区ではされていると思うんですが、そういう意味で、今後、ＳＡＲＳの場合も野生動物からということですが、さまざまなペットが現在品川区でも飼われていると思いますが、犬以外の動物に関して登録というものをするようには考えられているのかどうかをお答えください。","respondent":"島袋品川区保健所衛生課長","answer":"ただ、ほかの、例えば今委員のおっしゃったペット等につきましては登録という法の制度はございませんので、現在のところは登録はないです。","voiceIndex":335,"id":"exchange-141"},{"speaker":"山村委員","kind":"質問","question":"そうしますと、結構危険な肉食獣系のペットを飼っていても、品川区等ではわからないということなのかもしれないんですが、今後は国がやっていないからというのではなく、何かしら考えて、ある程度、鳥などのペットについても把握するのは必要かと思われるんですが、どうでしょうか。","respondent":"島袋品川区保健所衛生課長","answer":"あくまでもこの東京都の動物の愛護および管理に関する条例というのは特定動物という形でやっているもので、すべてを把握するのは難しいだろうと考えております。","voiceIndex":337,"id":"exchange-142"},{"speaker":"山村委員","kind":"質問","question":"保健所長は現在は医師免許の資格をお持ちの方以外はなれないということになっているんですが、いろいろな地方自治体の方から保健所の所長が医師免許を持っている方以外でもなれるようにというような陳情を国に出しているような場合があるようで、ただ、今後こういうような鳥インフルエンザみたいなものがはやっている現状下においては、専門分野が特に必要になってくる部分があると思うんですが。","respondent":"青山品川区保健所長","answer":"現在この問題につきましては、厚生労働省の保健所長のあり方検討会の中で検討が進められておりまして、それで、本年度中に結論を出すべく最終的な詰めが行われているところです。","voiceIndex":339,"id":"exchange-143"},{"speaker":"南委員","kind":"質問・要望","question":"一つ目は、子どもたちの健康を大気汚染からいかに守るかということで、新たな施策をぜひともつくっていただきたいという立場で質問したいと思います。それで、そのほかの地域にもあるんだろうと思うんですけれども、東京都の医療費の助成制度、年々新たな認定がなくなったということで、あるわけですけれども、この数年間のこの助成を受けていらっしゃる方々の数字を改めてご紹介していただきたいと思います。","respondent":"田中健康課長","answer":"平成１２年が１,３６８件、平成１３年度が１,３８０件、平成１４年度が１,３５９件、ちなみに平成１６年２月は１,２９８件というふうになってあります。","voiceIndex":343,"id":"exchange-144"},{"speaker":"南委員","kind":"確認","question":"それで、改めて私どもも、この間の大気汚染の状況が品川区内の定点で測定されているところの、いただいている公害の資料を見せていただいて改めて確認したんですけれども、０.０６ｐｐｍという環境基準をずっと上回っているという地点がありますけれども、それはどこでどのくらいの数値なのか、環境課長のほうからちょっと教えていただければと思います。","respondent":"金井環境課長","answer":"その地点がちょっとよくわかりませんけれども、八潮に測定局を設置をしておりますけれども、これは一般大気の測定局です。ここは窒素系とＳＰＭも測定しておりますが、環境基準を一部達成したこともありますけれども、現在は達成してございません。","voiceIndex":345,"id":"exchange-145"},{"speaker":"南委員","kind":"質問","question":"これについての回答は１１月２０日時点で区長名でお出しになっていますが、中身を見てみると、この区の回答については、かなり高濃度の汚染で非常に環境に、区民の生命、健康を守る立場である品川区として住民感情を考慮すれば受け入れは大変困難な状況と判断していると、こういうふうに。","respondent":"金井環境課長","answer":"区としては、こういうケースは初めてですけれども、内容を検討いたしました。それで結果として、今委員がご紹介されましたように、大変困難な状況というふうに判断をしている。","voiceIndex":347,"id":"exchange-146"},{"speaker":"南委員","kind":"確認","question":"それで八潮に持ってくるということで、これは何が出るかわからない、爆発が実際にあるわけですから、こういう危険な状況をどこまで私は品川区としてはきちんと確認されたのか、そこもちょっと伺いたいと思うんです。産業廃棄物処理会社がどういう根拠のもとでこういう判断をされたのか、そして、本当にこの技術は大丈夫なのかというところをどこまで確認されたのか、そこをちょっと伺いたいと思います。","respondent":"金井環境課長、田中健康課長","answer":"それで、そうした経過のもとに選定をされて、その一部についての焼却を区で行うですので、その辺については区が技術がどうのこうの、その爆発の危険性があるどうのこうのという問題以外に。健康診査という形で。そういう流れもありますので、それから、学校に向けていろんな把握もされているということで、特にそういう意味での調査をまた別途考えるということは現在考えておりません。","voiceIndex":349,"id":"exchange-147"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっと健康調査のほうは大変残念です。その確認をちょっとしたいのと、それから、処理をするのであれば、産業廃棄物処理会社と委託業者、それから品川区もそれぞれの責任で実施前、処理前、処理の中間、あるいは終わった後で土壌検査なり住民の健康調査をするべきだというふうに思うんですけれども、これについてはどうでしょうか。","respondent":"松本環境清掃事業部長","answer":"そういう意味で、ただ品川区の責任者としては、区民感情を考えると、できればよそでやってほしいという気持ちは持っておりますけれども、やはり基本的な部分では、地域的なものではなくて、私どもは受け入れるべきと考えています。","voiceIndex":352,"id":"exchange-148"},{"speaker":"三上委員","kind":"質問","question":"私は、２５９ページ、商店街活性化推進事業について関連して何点かお伺いしたい。それから２４５ページのノーレジ袋運動に関係するかな、それとも資源回収事業、２４６ページですね、ここらあたりのこと、それから２３５ページの公衆便所の維持費について、それから２３３ページの食品衛生推進員事業になるのか母子保健指導費になるのか、ちょっとお伺いしたいと思います。こういうものがあるわけですよね。","respondent":"市川産業振興課長","answer":"それで、特に技術に関係する、５年前に先端技術と言われていたものがもう今は一般技術になっているわけですが、具体的に申し上げますと、武蔵小山商店街がポイントカード事業に取り組んだおよそ１０年前、このときは。","voiceIndex":355,"id":"exchange-149"},{"speaker":"三上委員","kind":"質問","question":"それは十分わかる範囲ですよね。ですから、そこの商店街としては、やっぱり自分のところを守ろうとすれば、商圏を守ろうとすれば、一緒にはやりたくないという気持ちだって当然起きてくる。こういうふうに思う、これは私の心配で終わればいいんですけれども、そこらあたりをもう一度しっかりと、どういうふうに取り組んでいこうとされるか、お伺いしておきたい。","respondent":"市川産業振興課長","answer":"ただ、やはりコストと効果というものは見合わせながら、きちんと検討していくものだと私どもも思っておりますので、そういう視点で、商店街と今後共同作業を進めていきたいというふうに考えてあります。","voiceIndex":357,"id":"exchange-150"},{"speaker":"三上委員","kind":"質問","question":"これについてはぜひ武蔵小山、中延、先行して取りかかろうとするところですから、今後十分協議し、やはり喜んで参加していただけるということであるようにお願いしておきたいと思います。それからプラスチックの関係で、ペットボトルの質疑を私もずっと何回かやってまいりましたけれども、現在でも全国平均での回収率というのは４０％程度ですか。","respondent":"中山清掃リサイクル課長","answer":"国の直近のデータはちょっと時間が、すぐ出ればと思いますが、全世界でトップ水準になってきているということで、たしか回収率が５割に達したかというふうな報道があったかと思います。","voiceIndex":359,"id":"exchange-151"},{"speaker":"三上委員","kind":"質問","question":"そうすると、品川区の場合は、私が以前に質問したときは、平成１２年、拠点回収と、それからいろんなところが取り組んでいる回収と相当開きがあって、拠点回収を今回１万５００カ所でやるという予定でありますよね。これをやっていった場合に、数字的な目標値は出ていますけれども、これでいった場合には、どの程度の品川区の回収率というのは上がってくるんでしょうか。","respondent":"中山清掃リサイクル課長","answer":"区の中での発生数という分母がなかなか把握ができませんので、これで区の中の回収率がどれだけ上がるかというのは、ちょっと今すぐには積算できないかと思います。","voiceIndex":361,"id":"exchange-152"},{"speaker":"三上委員","kind":"質問","question":"これが本当にこういうふうに上がっていくんであればいいんですけれども、今のお話を伺っていると、果たしてこういう形で上がってこればいいんだけれども、期待の目標値になっているのではないかなという感じがするんですけれども、どうなんでしょうか。","respondent":"中山清掃リサイクル課長","answer":"それで、従来のコンビニ等の店頭回収、これが４００ｔ近くになっておりますから、多少その分の影響減があったとしても７００ｔを超えるというふうに見込んでいるものです。","voiceIndex":363,"id":"exchange-153"},{"speaker":"三上委員","kind":"質問・要望","question":"どちらにしても、こういうふうにして再資源化できるというものについては大事にしていくべきだと私は基本的に思っておりますし、しっかりと取り組んでいっていただきたい、こうお願いしておきたいと思います。それから、公衆便所の件でありますけれども、小破修理というのはどのような修理というのが一番多いんでしょうか。","respondent":"松代道路公園課長","answer":"公衆便所の小破修繕です。これは主にやはりいたずらによるドアを壊されましたり、詰め物をされましたり、あとはガラスを割られましたり、そういったものが主な修繕項目です。","voiceIndex":365,"id":"exchange-154"},{"speaker":"三上委員","kind":"質問","question":"そうすると、そういった修理ということがほとんどだということであれば、要するに便器そのものの水の関係とかといういたずらというのは、そうはないんでしょうか。特にちょっとお伺いしておきたいのは、和式トイレとか洋式トイレというのが、今どれぐらい比率的に、具体的な数字が出ればいいんですけれどもいかがですか。","respondent":"松代道路公園課長","answer":"数字的なものはちょっとつかんでおりませんけれども、従前は便器等もよく壊されました。最近では少しその辺が減ってきたというふうに報告を受けていますが、水を扱う、例えば手洗い、蛇口等のいたずらによる損傷、修繕等は少ないというふうに承知しています。","voiceIndex":367,"id":"exchange-155"},{"speaker":"三上委員","kind":"質問","question":"そうしますと、今は数が出てまいりませんけれども、やはり公園を中心にする、どちらかというと公共施設をずっと見ていったときに、古い施設なんかを見ていてもまだ和式というのが相当ありますよね。やはり公衆便所も同じ形態のほうが多いというふうに見ていていいんでしょうか。","respondent":"松代道路公園課長","answer":"洋式の便所もごくわずかですけれども、設置等々を検討してつけたところもあるんですけれども、ほとんどが和式です。","voiceIndex":369,"id":"exchange-156"},{"speaker":"三上委員","kind":"質問","question":"目の前にある。それを手で押すのか、足で踏みつけるのか。ところが基本的には手でやってほしいという、本当は理事者の皆さんにあなたはどういうタイプですかと伺ってもいい話なんですけれども、そういうふうなことで、使い方によってはそういうふうにどう使ったらいいんだろうか悩んでいるという、こういうふうな一つの記事が載っていたことがあるんです。私も悩むんですけれども、どうですか。","respondent":"松代道路公園課長","answer":"先ほどの質問の中で和式と洋式便器というところでのちょっと補足で説明しますが、最近では身障者トイレのさらにグレードを上げまして、だれでもトイレというものをつくってあります。そういったところには洋式を設置しています。","voiceIndex":371,"id":"exchange-157"},{"speaker":"三上委員","kind":"質問","question":"使い方によっては中をのぞくわけにいかないのであれですけれども、今、言われてきているのは、和式トイレの出荷数というのは全体のもうほぼ１割にも満たなくなってきている。ということになれば、高齢社会というこのことも考えてみると、やはり公衆トイレももう一度見直す時期にも来ているんじゃないかな、こういうふうに思えるんですけれども、いかがでしょうか。","respondent":"松代道路公園課長","answer":"従前から計画的に古いトイレ等は改修をしています。そういった中で、そういったいろいろな利用者の方の声を聞いて、今後和式、洋式、どういうふうにしていくのか研究課題とさせていただきまして、検討させていただきたいと思います。","voiceIndex":373,"id":"exchange-158"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これは、抜き取り対策は税負担で行っていきますので目的を明確にしていただきまして、例えば袋を配付するとか、それから、ハード的な対応については、資源回収を始めた各種団体、それから協力していただく企業等に限っては税負担で対処していただきたい、そのほかのところにつきましては現行の法令、それからさまざまな市場等を十二分に調査しながら対処していくべき。","respondent":"中山清掃リサイクル課長","answer":"抜き取りの問題というのが、こういう無秩序な状況が出ていることについてきちんと行政が役割を果たしながらコントロールしていく、そういう部分で言えば、今おっしゃったような、めり張りをつけての対応というのが基本かと思います。","voiceIndex":376,"id":"exchange-159"},{"speaker":"伊藤委員","kind":"質問・要望","question":"何点か確認をさせていただきたいんですが、一つは、清掃一部事務組合の抜本的な改革案を助役会に下命されたということがありますので、その区長会に対する助役会の回答期限はありますでしょうかということを一つお伺いしたい。それから、もしなければ、助役がぜひこの助役会をリードしていただきまして、なるべく早く回答案を区長会に上げていっていただきたいと思うんですが、いかがでしょうか。","respondent":"濱野助役","answer":"それで、今は清掃一部事務組合のあり方についてやっているんですが、それとそろそろ同時並行でやらなければいけないのが、都の職員を平成１８年度から今度受け入れるわけですので、その勤務条件をどうするかという問題、これも緊喫な課題になっておりますので。","voiceIndex":378,"id":"exchange-160"},{"speaker":"伊藤委員","kind":"質問","question":"そのことを考えてまいりますと、その背景には、いわゆる２３区のほうが清掃工場建設には莫大な費用とそれから大変厳しい区民感情を乗り越えていく、特に工場のない区はそれを乗り越えていかなきゃいけない、ですけれども、そういうふうなものを実は各区の自己決定、自己責任のもとに真剣に取り組んでこなかった、むしろ２３区同一だよ、２３区一緒だという隠れみのの中に。","respondent":"高橋区長","answer":"そういうふうな面を含めて、清掃一部事務組合が最少限度どの程度必要なんだろうかというふうなことの検討に、これから入っていくものじゃないかと考えています。ただ、中にはまだまだ清掃工場がある区とない区とではかなりの温度差があります。","voiceIndex":380,"id":"exchange-161"},{"speaker":"伊藤委員","kind":"質問・要望","question":"先ほどもお話をさせていただきましたように、うちの会派が出した質問状に対する回答、それから先ほど区長がお話しされたように、ほかの２２区も今の清掃一部事務組合だったらいけないとみんな思っているということですから、となると、これからぜひ区長に区長会もぜひリードしていただきまして、今後のこの清掃一部事務組合に対する取り組み、それから戦略、それから抜本的な改革と近い将来に向けた。","respondent":"高橋区長","answer":"これからもあると思います。だけれども頑張ってまいりたいと考えています。","voiceIndex":382,"id":"exchange-162"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=828#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":127760,"voices":384}},{"id":"h16-20040312-3","meetingId":"h16-c-budget","date":"2004年3月12日","dateIso":"2004-03-12","committee":"予算特別委員会","time":"午前１０時０５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を137件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時０５分開会 おはようございます。ただいまより予算特別委員会を開会いたします。 第５号議案、平成１６年度品川区一般会計予算","agenda":"○午前１０時０５分開会 おはようございます。ただいまより予算特別委員会を開会いたします。 第５号議案、平成１６年度品川区一般会計予算","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"おはようあります。１項土木管理費のうち、２６７ページの、駅周辺等放置自転車対策費についてお伺いをします。それは何かと言いますと、置いてはいけない場所に対して、置いてはいけないんだけれども、そこに置いてはいけないから、ほかへ置いてしまう。そういう現状についてどのようにお考えになり、また、どのような対策を講じられているのでしょうか、お答えをお願いいたします。","respondent":"奈良交通安全担当課長","answer":"そこの私道部分を管理している方々がそれぞれご了解をいただければ禁止区域をかける検討もしますけれども、ただ、私道上の部分につきましては、通勤、通学の方だけでなくて、私道部分を管理している方々も自転車をお止めになっておりますので、そうしますと、そこをかけた場合に。","voiceIndex":4,"id":"exchange-001"},{"speaker":"大沢委員","kind":"質問","question":"子どもが下敷きになってしまう場合も、路地というのは子どもが遊ぶ場所も多く見受けられますので、そういう可能性もなきにしもあらずだと考えますけれども、４階、５階、比較的高くもない、低くもないという集合住宅、ないしは集合住宅に入居している店舗の前、そういうところに駐輪場の付置義務というのがないようには思われるんですが、そこのところの正確なところをお教え願えますでしょうか。","respondent":"浜脇住環境整備課長","answer":"その中に、集合住宅として２０戸以上の集合住宅、それから、延べ面積が２,０００m2以上の建物、あるいは敷地が１,０００m2以上というようなことになりますと、今委員のおっしゃったように、もしかすると、集合住宅であっても２０戸以下。","voiceIndex":6,"id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"次にいきます。しかしながら、防犯のみならず、防災、さらに自転車の放置、まちの中のいろいろと困りごと、生活安全ですから、困りごとということに対処する目的も少なからず要素としてあると思います。その部分において、生活安全サポート隊、地域をパトロールするわけですけれども、そういった場合、駐輪対策についてどのように係わりを持たれていくのか、お答えをお願いいたします。","respondent":"奈良交通安全担当課長","answer":"今委員ご指摘の、生活安全サポート隊と違法駐輪との関係ですけれども、生活安全サポート隊につきましては、それぞれの任務が付与されておりますけれども、ただ、将来的には生活安全サポート隊と。","voiceIndex":8,"id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"できた当初で、連携というのもまだ整備していないとは思いますけれども、将来的とはおっしゃらずに、近いうちになるべくスムーズに連携をとっていただけるように、切にお願いを申し上げます。連携が明確になりました。今後連携という場合において、どの程度まで、どの範囲まで区は、警察行政といいますか、関係機関に対してお手伝いができるのか、どの程度までというのを教えていただけますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"今の部分は個人的にお伺いをいたします。次、自転車の返還率を簡単にお伺いします。品川区の自転車返還率、２３区のうちではちょうど真ん中あたりになりますけれども、下にありますように、撤去、返還、委託ということで、委託をして返還をしてもらっています。ところが、委託返還という部分で、返還率を上げるにはどのようにしたらいいのか、簡単に教えていただけますでしょうか。","respondent":"奈良交通安全担当課長","answer":"昨年、不動前保管所を開設して以来、順調に返還率が伸びておりまして、昨年の１０月、１１月、１２月の３カ月をとってみましても、平均しますと大体５６％から５７％ぐらいの返還率がいっておりますので。","voiceIndex":12,"id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"これからも各委員から放置自転車の問題が出ると思いますが、放置自転車は、品川区のみならず、２３区が抱える問題であります。いろいろと問題のところがありますが、今後とも自転車問題よろしくお願いを申し上げまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006"},{"speaker":"若林委員","kind":"質問・要望","question":"２８３ページの公園関係、２８５ページの大崎駅周辺地区再開発をご質問します。公園のほうです。たしか昨年の９月あたりより緑と花のボランティアの募集が始まりました。昨年から今年にかけてホームページ上で犬の散歩についてのモニターをかけておられましたけれども、そこら辺の結果をお知らせていただきたいと思います。","respondent":"松代道路公園課長","answer":"緑と花のボランティアです。これは平成１５年度試行的にやってあります。平成１６年度から本格的に実施をしたいと考えています。平成１５年度で実施をしている中で、２０件ほどすでにボランティアで活動をしていただいております。","voiceIndex":16,"id":"exchange-007"},{"speaker":"若林委員","kind":"確認","question":"９月の世論調査の動向を見て最終の運びになるというふうに理解をしてよろしいでしょうか。一応確認をします。ここに添付されているチラシの中には、道の清掃という、道路清掃という文字がありませんでしたので、ここら辺をどういうふうにされていくのか、道路があるのかないのか、ちょっと確認をします。","respondent":"松代道路公園課長","answer":"先ほど、平成１５年度現在でやっている件数を間違えまして、実施しているボランティアとして団体で登録していただいているのは４件でございまして、あと２０件等はいろいろと問い合わせをして、今そういったお話をさせていただいている件数です。訂正します。","voiceIndex":18,"id":"exchange-008"},{"speaker":"若林委員","kind":"質問・要望","question":"これは、こういう言い方が当たっているのかどうかわかりませんけれども、平成１６年度においての目標値というものがありましたら、お知らせ願いたいと思います。例えば花壇のない公園とか、その近辺の方が、花壇はないんだけれども、これから私たちの公園を花でいっぱいにしたいんだというような相談があった場合に、そこに新しく花壇をつけるというようなお考えにあると思っておるんですが、確認をします。","respondent":"松代道路公園課長","answer":"公園に花壇等がない場合の対応ですけれども、四季を通じて花を植えていただくというのは、区民の方も関心をお持ちです。そういった意味では、一画に花壇を設けまして、そういったものを四季を通じて管理していただくという形で考えてあります。","voiceIndex":20,"id":"exchange-009"},{"speaker":"若林委員","kind":"質問・要望","question":"私はどんどん広げていただきたいなと思います。このお考えをお聞きしたいと思います。ですから、何かをやるということではなくて、例えばその方たちを顕彰するという意味で、花壇にその人たちが名付け親になって、この花壇は、公園は、私たちが今つくっていますよ、こういうようなネーミングをしてあげるとか、そういう顕彰の仕方もあるのではないかなと思いますが、以上３点、お考えをお聞きいたします。","respondent":"松代道路公園課長","answer":"３点目の顕彰です。ネーミング、名付け親等々のご提案ですけれども、これも何らかの形でやりがいを持ってやっていただけるようなものを今後検討してまいりたいと考えています。","voiceIndex":22,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"２６７ページ、放置自転車の委託の問題と、２７３ページ、都市計画道路放射２号線の問題です。２７５ページ、目黒線の立体交差事業に伴う地盤沈下の問題をお伺いします。私もすぐに現地に行ってきましたが、結構広い範囲に被害が出ています。本日夜に地元の説明会があるということですが、先立って何点かお伺いをしたいと思います。１点目は、経過と、原因についてご説明をお願いします。","respondent":"中島街路事業担当課長","answer":"初めに経緯ですけれども、２月の上旬、施行業者のほうから地下水位、これは定期的に観測しているわけですけれども、地下水位が低下しているというのを確認しています。これが２月５日頃です。それを受けまして、施工者におきまして調査を開始いたしました。","voiceIndex":26,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"土留壁からの出水ということですけれども、何日ぐらい水が流れていて、どのくらいの量が流れていたのか、お聞かせいただきたいと思います。","respondent":"中島街路事業担当課長","answer":"出水量ですけれども、推定ですけれども、一番多い時点で、１分間に約２００ｌ、ドラム缶１本ぐらいの水が流水していたということを現時点で推定しています。","voiceIndex":28,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"どのくらいの期間流れていたかは推定できるんでしょうか。","respondent":"中島街路事業担当課長","answer":"２月の上旬から２月末ぐらいまで、約１カ月弱というふうに考えてあります。","voiceIndex":30,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"専門家に伺ったら、地下水の水位のチェックというのは基本のきであると言われたんですけれども、この辺がどうしてチェックがきちんとできなかったのかというところが大変疑問なんですけれども、その辺については検討されたんでしょうか。","respondent":"中島街路事業担当課長","answer":"当然この工事につきましては、そういった地下水を常に調査して、観測をして、それに沿った対応を常にしていますけれども、今回につきましては、地下の水位が低下したのは確認できたんですけれども、原因が判明するまでに時間がかかったということで。","voiceIndex":32,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"私はかなり厳しいチェックがされる必要があると思うのと、原因の場所というのは凄く分かりやすくて、線路沿いで、音がジャージャー流れていましたけれども、分かりやすいところというところでは、こういう事態を生んだということでは、工事の甘さというか、ずさんな面があったのではないかなと思うんですが、あってはならない事故なので、再発防止の対策はとられているんでしょうか。","respondent":"中島街路事業担当課長","answer":"そういった部分で私どもは東京都、東急電鉄を通して、事業者につきまして呼びまして、きちっと指導はしていますけれども、今後二度とこういうことがないようにということで、私ども事業者としても注意を怠りなくやりながら進めていきたいというふうに考えてあります。","voiceIndex":34,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"再発防止のために今後努めていただきたいと思います。今後の対応がとても大事だと思うんですが、この間の調査内容と、被害状況、そして家屋調査などがどのくらい行われたか教えてください。","respondent":"中島街路事業担当課長","answer":"家屋調査をすべてしています。ただ、今回地盤変状が起きた部分がその３０ｍより外側になってありますので、そちらにつきましては、家屋調査を実施してございませんので、今般説明会の後に早急に家屋調査を含めて被害状況の把握も併せてやっていきたいというふうに考えてあります。","voiceIndex":36,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"安心してあの地域で生活をしていただくためには、まずは十分な説明、その後は十分な補償が必要と思うんですが、当面の対策とか、長期的な対策というあたりは、今日の夜に向かってできているんでしょうか。","respondent":"中島街路事業担当課長","answer":"その次に実際の被害の状況をきちっと把握した上で、今後の対応を責任を持って事業者としてやっていくということが肝要ではないのかなというふうに考えてあります。","voiceIndex":38,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"今日の説明会は分かったんですが、今日参加できなかった方、漏れてしまわれた方への対応も考えていらっしゃるでしょうか。","respondent":"中島街路事業担当課長","answer":"先ほど申し上げましたけれども、本日の説明会の後に全戸調査に入ります。被害状況も含めて調査に入りますので、その中で今日の説明会に参加できなかった方につきましては、改めて個別の説明をさせていただこうというふうに考えてあります。","voiceIndex":40,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"意見","question":"品川区がどのような立場をとられているのか、今後どういうふうに進められていくのか。","respondent":"藤田都市計画課長","answer":"今後についてですけれども、優先整備につきましては、本年３月、この後もうしばらくすると、こういった方針が固まってくるものですので、それに合わせて今後、放射２号線につきましては東京都の施行する路線ですので。","voiceIndex":44,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問","question":"そういった面で区民の皆さんの声をどう聞いているのかというのが大変重要だと思うんですが、この点はいかがでしょうか。","respondent":"藤田都市計画課長","answer":"この後、４月１日号でも最終的に決定した路線について改めて掲載をしていく予定ですので、そういった形での周知を図っていくということと、今後東京都のほうで事業化を進めていく中で、事業認可等を取る中で、事業の時期を明確にしたお話をしていくということで。","voiceIndex":46,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"意見","question":"ホームページには載っていました。東京都のほうは平成１５年１２月１９日から平成１６年１月３０日までにご意見をお寄せくださいということなので、この中身を建設委員会で報告されたのが１月２０日なんです。はきちんと説明をする、言葉の上では、住民の理解を得るということですけれども、この辺の進め方が住民の立場に立っているかどうか大変重要だと思うので、もう一度お答えください。","respondent":"藤田都市計画課長","answer":"今回、建設委員会への報告ですけれども、東京都のほうのプレスの発表の時期と建設委員会の時期がちょっとタイミングがずれてしまったということでございまして、ただ、区民の皆様の関心は非常に高い項目だというふうに考えてありますので。","voiceIndex":48,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"一応のご説明はいただいたんですが、やはりそこに住んでいらっしゃる住民の方に、自分たちのまちづくりがどうなっていくのかというところをまずは伝えていくのが大事だと思います。特にまちづくりというのは、どれだけの道路が必要なのかという観点と、そこの住環境をどう守っていったらいいのかというところのバランスだと思うんです。区でできることは一体どういうことなんでしょうか。","respondent":"藤田都市計画課長","answer":"今回のケースは事業主体が東京都だですけれども、こういった形で全体の優先整備路線が提示されてきてありますので、それらにつきましては、区のほうといたしましても、区民の皆様に十分周知を図っていきたいと考えているところです。","voiceIndex":50,"id":"exchange-022"},{"speaker":"大西委員","kind":"質問・要望","question":"駅周辺放置自転車対策、これは私は何度もご質問を申し上げて、ご答弁もいただき、今日も朝ビデオで先般の一般質問のときの答弁をよく見てきたわけですけれども、少しずつ進んでいるのかなという実感は持っているんですけれども、最初に基本的なことで大変恐縮ですけれども、まちづくり事業部の基本的なコンセプトを教えていただきたいと思います。","respondent":"中谷まちづくり事業部長、奈良交通安全担当課長","answer":"放置自転車対策に対する区の基本的な考え方ですが、先般来議会でもこの問題については大きく皆さんからのご意見が出され、区としても放置自転車対策については懸命に取り組んできている。併せて、大井町駅周辺の放置自転車対策につきましては、まちづくり事業部長が申し上げたとおり、平成１３年度から整備有料化とか、撤去活動の強化、指導啓発の強化とかをやっておりまして、いろいろなこういった対策を進めた結果。","voiceIndex":53,"id":"exchange-023"},{"speaker":"大西委員","kind":"質問","question":"そしてまた、そこを駅に向かう、通行して帰っていく人たちが非常に通りにくくなって、人１人が通るのがやっと、自転車であれば、押しては通れないということ等があって、非常に問題かなと。２６７ページの下のほうに、駐輪対策協議会経費というのが載っておりますけれども、具体的にはこの会合というのは何回ほど開かれ、どういうふうな議論になっているかを教えてください。","respondent":"奈良交通安全担当課長","answer":"それで中心核にふさわしいまちづくりをするために、民間の各団体、行政機関と民間企業、これは鉄道事業者とか、大規模店舗、銀行、町会、商店街等の協力をいただいて、そういった協議会を設置しまして、活動を通じて、お互いに緊密な信頼関係を築きながら、駐車問題、駐輪問題。","voiceIndex":56,"id":"exchange-024"},{"speaker":"大西委員","kind":"質問","question":"これはおそらく行政側の働きかけかなというふうにも思っています。これは私からすると、先般の決算特別委員会でも質問をしたところですけれども、そういうことでもし事故が起こった場合、これは未必の故意に当たるんじゃないかということをお尋ねしました。私は未必の故意を相当認めるのではないかなと思ったんですけれども、この辺、部長どんなものでしょうか。","respondent":"中谷まちづくり事業部長","answer":"委員から自転車の放置は未必の故意に当たるのではないかというご質問ですが、私どもの理解しているところでは、未必の故意と申しますのは、行政側が対策を何もとらないで事故が起こった場合については責任を問われるということもあり得ると思いますが、区としては。","voiceIndex":58,"id":"exchange-025"},{"speaker":"大西委員","kind":"質問","question":"ということは、もしそこでけがが起こった場合には、そのことが議場にのぼる可能性がある。夕方非常にたくさん自転車があるという認識を区がされている。では、夕方に対しては平日どのような手だてをとられているんでしょうか。","respondent":"奈良交通安全担当課長","answer":"放置防止指導啓発員の方についても、従来は午後５時までだったんですけれども、それを１時間延長して、午後６時までということで、夕方に対する自転車の啓発活動とか、撤去活動を強化してまいります。","voiceIndex":60,"id":"exchange-026"},{"speaker":"大西委員","kind":"質問・要望","question":"１店舗に関しては非常に優秀だというふうに、私は議員研修会に出なかったんですけれども、ショッピングに行くたびに苦情がある、その苦情に対してどのように対処したかというのを、きめ細かく書いているというところで徹底されている。品川区が一流の自治体であると。そういう点で、ぜひ名実ともに一流としての対応をしてほしい。この問題もなるべく短期の間に解決を図っていただきたい、このように思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-027"},{"speaker":"大西委員","kind":"意見","question":"失礼しました。東品川海上公園整備について、具体的にはどういう中身を整備するのかを聞かせてください。","respondent":"岩田管理工事課長","answer":"平成１６年度予算で計上をしていますのは、残りの約１万４,０００m2のうち、約半分程度の整備が平成１７年度に一部できる予定ですので、その部分の詳細設計の経費を計上させてもらっているものです。","voiceIndex":64,"id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私は、２６７ページ、駅周辺等放置自転車対策、有料自転車駐車場運営費、別の方向からお聞きします。それから、地籍調査事業、２８２ページ、公園管理費、２９１ページ、木造住宅耐震診断支援事業、この点について質問をします。もう１点、地籍調査について質問をします。地籍調査自体今度初めての予算が計上されてきて、我々自民党としては政策要望の中でここ数年来要望しておりました。","respondent":"市岡企画財政課長、岩田管理工事課長","answer":"しながわ中央公園のオープニングが３月３０日にあります。これはすべて国庫補助対象事業になりますので、残りの三級基準点の未整備約６８ポイント、これを全部平成１６年度で実施しようというものです。","voiceIndex":67,"id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"三級基準点は今年で終わるということで、今後においては四級というのは進めていくのかどうかというその辺を後で教えてください。地籍調査のほうについてお伺いします。私もその辺、あまり細かくはわかっていない部分ですが、これから品川区として進めていく中で、どういう難しさがあるのか、官と民の問題、民と民の問題、いろいろ絡んでくると思いますが、その辺についてご説明をいただきたいと思います。","respondent":"岩田管理工事課長","answer":"三級基準点だけではあまりにも遠過ぎますので、調査ができませんので、もっと細かいメッシュで四級基準点も合わせて整備していくというものです。","voiceIndex":70,"id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"震災は起きてほしくないのがまず第一ですけれども、そのときの対応ということで、今年度５,０００万円ぐらいですが、この中で大体どの辺の地域をどのぐらい予定しているのか。莫大な費用になると思うんですが、その辺はどのぐらいになってくるのかなということで、お答えをいただきたいと思います。","respondent":"岩田管理工事課長","answer":"総事業費ですけれども、概算で約７０億円程度はかかるだろう。これは予算的なものもありますので、ここで何年ということはなかなか難しいんですけれども、３０年を一つの目安にして事業化計画を立てていきたいと考えております。","voiceIndex":72,"id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"歳入のほうで見ていくと、国庫補助金が４分の２、東京都が４分の１、一般財源が４分の１となっていました。３０年であがればいいという状況だと思うんですけれども、長い期間になると思いますけれども、徐々に進めていっていただきたいなと思います。２カ所ほど、品川シーサイドの有料駐輪場と、天王洲アイルの有料駐輪場、現在の使用率というのはどのぐらいになっているかなという点をお聞きしたい。","respondent":"奈良交通安全担当課長、片田建築課長","answer":"利用率ですけれども、天王洲アイルにつきましては３５％、品川シーサイドにつきましては２０％弱ぐらいです。木造住宅耐震診断の専門機関というお話ですけれども、私どもで今検討しているのは、社団法人の東京都建築事務所協会品川支部という機関があります。","voiceIndex":74,"id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"品川シーサイドと、天王洲アイル、非常に利用率が低い。その中でどのようにりんかい線を考えていったらいいのかなと。それから、木造耐震診断は品川支部２７社ということで、うまく使っていただきたいと思います。その中で、逆に診断の結果によって改修しなければいけなくなったとき、そこをどのように結びつけていくのかについてお答えをいただきたいと思います。","respondent":"藤田都市計画課長、片田建築課長","answer":"それはりんかい線の影響だけということに特定するのは難しいですけれども、店舗側の努力と、りんかい線の全線開業というものと合わせた相乗効果によるものではないかというふうに考えてあります。その中で改修につきましては、品川区の中で住宅修築資金のあっ旋ということがありますので、それを十分活用していただくという方向を考えてあります。","voiceIndex":77,"id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"りんかい線に関しては状況は分かりましたが、まだちょっと疑問点があるのは、品川区の職員の方に対してもりんかい線の定期代は出ないんですよね。もう１点、住宅修築資金、これも保証人だけというのが、保証制度に変わったということもあると思うので、その辺もうまく利用していただいて、せっかくでしたら、相談から、最後の補強工事まで一貫してうまく使っていただきたいと思います。","respondent":"市岡企画財政課長","answer":"なかなか辛いところでありますが、職員の旅費につきましては、一番合理的で最も安いところをとるというのが原則ですので、願わくば、お台場等に出かけて、個人としても、職員の皆さんにせいぜい利用していただきたい、こういう苦しいところですが、よろしくお願いいたします。","voiceIndex":80,"id":"exchange-034"},{"speaker":"本田委員","kind":"質問・要望","question":"その後２０年後の東京港を見越して、さまざまな都市計画を定めていくという基本方針が出されました。そういう点で大変な拠点が大井ふ頭で今整備も完成して、着々と運航されているというふうに聞いておりますが、そういう現況等を含めて、それから、交通安全対策にも係わってまいりますが、都市計画といいますか、臨海部のまちづくりに係わりますので、まずこの特徴点をご説明いただきたいと思います。","respondent":"藤田都市計画課長","answer":"先ほどお話がありましたけれども、その中ではコンテナの大型化に対応したような形での整備を進めていくこと、それから、もう一つの視点といたしましては、水辺の特性を生かした土地利用を展開していこう、こういったような観点も踏まえながら、物流拠点としての東京港を革新する。","voiceIndex":83,"id":"exchange-035"},{"speaker":"本田委員","kind":"質問","question":"ここでお尋ねしておきます。その辺の検討と言いますか、対策と言いますか、水上警察の管轄だと思いますけれども、現状の道路の安全対策がどのようにされているのか、道路が車の置場になっているという現状、かつて、まさか中央に車があるなどと思わないで走った車が正面衝突して死亡事故もここでは起きておりますので、交通安全の面からも現状を改善する必要があると思うんですが、まずこの点をお尋ねします。","respondent":"上野都市開発課長","answer":"東京都のほうといたしましては、あそこの道路、港湾道路、あるいは都市計画上の２８号線ということで都道ですけれども、そういった中でもう少し一般の方々も安心して通行できるような形での整備について、今検討をしているところというふうに聞いてありますので。","voiceIndex":85,"id":"exchange-036"},{"speaker":"本田委員","kind":"質問","question":"現状の改善を急いで図るように、大きな事故等が起きてからでは遅いですから、お願いをしておきたいと思います。品川区では京浜運河、勝島運河、天王洲運河等がありますけれども、これは品川区にとりましてはどういう具体化の方向が今後打ち出されていこうとしているのか、お尋ねしたいと思います。","respondent":"上野都市開発課長","answer":"先日、歳入のときの山路委員にもお答えしていますけれども、運河を新たな観光の視点から見直して、まちづくりと一体となった運河の活用を目指すといったものでございまして、この具体化に向けて天王洲地区につきましてモデル地区として位置づけて。","voiceIndex":87,"id":"exchange-037"},{"speaker":"本田委員","kind":"意見","question":"今、天王洲のお話が出ました。具体的に進んでいくことを期待をしております。勝島運河についても、こういう方針の中で、積極的な規制緩和を活用しながら、もうちょっと地元の方々の自主性に協力をしながら、対応ができるのではないかと思うんですが、その辺はまだ検討をされていないのか、これからの課題なのか、お尋ねします。","respondent":"上野都市開発課長","answer":"具体的な緩和の内容等につきましても、平成１６年度以降そういった検討をこれからやっていくです。今はどういった課題があるか、今委員ご指摘のような課題があるということを認識しているという段階です。","voiceIndex":89,"id":"exchange-038"},{"speaker":"本田委員","kind":"意見","question":"第７次の基本計画は、東京港の２０年後のあるべき姿を明確にしながら、それに向けてそれぞれまちづくりを進めていく。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":91,"id":"exchange-039"},{"speaker":"武内委員","kind":"質問","question":"私は短めに４点ほど、２６７ページの駅周辺等放置自転車対策費、交通安全対策費、２７１ページの街路樹整備費、２７５ページの道路バリアフリー事業をお伺いしたいと思います。放置自転車対策費ということで、民間のマンション等に違法駐車をしまして、そのままおそらく乗り捨てて、取りに来ない、そういった民間のマンションの敷地内の自転車というのはどちらのほうで撤去していただけるか、お教えください。","respondent":"奈良交通安全担当課長","answer":"今委員お話の、民間のマンションの駐輪場に放置された自転車につきましては、基本的にはマンションの管理する管理者の方から処分していただくというのが基本原則です。","voiceIndex":93,"id":"exchange-040"},{"speaker":"武内委員","kind":"質問","question":"その際、例えば撤去すると言っても、捨てる場合、八潮とか不動前のほうの保管所のほうに持っていってもらうことは、有料であればできるんでしょうか。","respondent":"奈良交通安全担当課長","answer":"もし持ち主の方がいれば、それは持ち主の方が正規の廃棄物として５００円を払っていただいて、処分してもらう。もし持ち主がいなくて、数年も経っているということであれば、マンションの管理人の方に費用を負担していただいて処分をしていただくというのが基本原則です。","voiceIndex":95,"id":"exchange-041"},{"speaker":"武内委員","kind":"質問","question":"そこのマンションに係わりのない、例えば酔っぱらいがどこかで自転車を乗り捨てて行ったようなケースの場合はどのように対処したらいいでしょうか。","respondent":"奈良交通安全担当課長","answer":"もし盗難被害であれば、当然それは警察のほうの扱いになるです。","voiceIndex":97,"id":"exchange-042"},{"speaker":"武内委員","kind":"質問","question":"続きまして、交通安全対策費ということで、スクールゾーンについてお伺いしたいんですが゛この安全対策ということで、車止めという表現が正しいかどうかわからないんですけれども、午前８時から午前９時の通学時間帯に、区のほうで近隣の方に依頼をしていただいて、出していただくということがなされていると思うんですが、これについて、必ずこれは出さなければいけないのか。","respondent":"奈良交通安全担当課長","answer":"スクールゾーンは区内に相当の数がありますけれども、スクールゾーンの入口部分に協力される方がいれば、パイプ柵を置いていただいている。もしご協力していただけない方につきましては、現在はそういったものは置いておりません。","voiceIndex":99,"id":"exchange-043"},{"speaker":"武内委員","kind":"質問・要望","question":"先日この協力をされている方からご質問と要望等があったんですが、長年自分のお子さんがその地域の学校にお世話になっているということで協力をしてきたんですけれども、今回協力をやめようと思っているというお話があって、なぜですかという話を聞いたら、もちろん大変ということもあるんですが、実際に出すんですけれども、どうしても通学時間というのは通勤時間にも重なるものですから。","respondent":"奈良交通安全担当課長","answer":"私どものほうもそういったお話をいただければ、これは当然取り締まるのが当たり前のことですから、私どものほうもそういった場所が分かれば、地元の警察にお願いをして取り締まりをするのが一番効き目があると思いますので、そういった場所がありますれば。","voiceIndex":101,"id":"exchange-044"},{"speaker":"武内委員","kind":"質問","question":"続きまして、２７１ページの街路樹整備費についてお伺いします。これの害虫駆除委託等ということで、害虫駆除なので消毒等もやられると思うんですけれども、消毒をやられる際に近隣の民家等に周知をされているようでしたら、どのような形でされているかお教えください。","respondent":"松代道路公園課長","answer":"その際には十分周辺の方への周知、事前にお知らせをして、窓等を閉めていただく、また、例えば公園の場合であれば、公園を利用される方には、その場でその付近には入れないような形もとりまして、十分な安全性を確保して害虫駆除を実施ているところです。","voiceIndex":103,"id":"exchange-045"},{"speaker":"武内委員","kind":"質問","question":"街路樹は苦情がきた場合にやるということですけれども、公園のほうは定期的にやっていらっしゃるんでしょうか。","respondent":"松代道路公園課長","answer":"以前は事前にという形をとっておりましたが、あくまでも農薬等ですので、毛虫等が発生して、通報をいただいて、すぐに対応するという発生主義をとっております。これは街路樹も公園も同様です。","voiceIndex":105,"id":"exchange-046"},{"speaker":"武内委員","kind":"質問","question":"その際に地域の方に何の連絡もないものですから、特に近い住宅の方が被害をこうむって、消毒の非常に強いものもありますので、そういう声が寄せられて、個々に対応すればいいんでしょうけれども、そういった苦情等というのは区のほうにはきていますでしょうか。","respondent":"松代道路公園課長","answer":"これは農薬使用者すべての者が農薬が飛散することを防止するために必要な措置な講じるよう努めなければならないというものを規定したものです。こういったものを受けまして、東京都のほうでは東京都病害虫防除基準というものをつくってあります。","voiceIndex":107,"id":"exchange-047"},{"speaker":"武内委員","kind":"質問・要望","question":"最後になりますけれども、２７５ページの道路バリアフリー事業ということで、バリアフリーの考え方で、以前に横断歩道をバリアフリーにしてくれということでちょっとお願いしたことがあったんですけれども、横断歩道は２cm段差というんですか、目の見えない方の杖が当たるようにということで、２cmぐらいの段差が設けられているというふうにお聞きしたんですけれども。","respondent":"岩田管理工事課長","answer":"前にもお答えしたと思うんですけれども、品川区は平成６年頃からこつこつとバリアフリー、いわゆるゼロ段差と言っているんですけれども、これを試行的に行っております。これは国の基準では２cmの段差を付けなければならないというふうに昨年までなっておりました。","voiceIndex":109,"id":"exchange-048"},{"speaker":"武内委員","kind":"意見","question":"先日板橋駅か何かでちょっと出ておりましたけれども、一部段差があって、３分の１ぐらいをバリアフリーで車椅子等が通れるようなそういった段差のがありまして、私も見てきたんですけれども、またそういったものも工夫されながら、ぜひ段差のない道路をよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":111,"id":"exchange-049"},{"speaker":"石田委員","kind":"質問・要望","question":"その中でもごく一部の人がずっと袖看板でちゃんとお金を払っている人がいるのであれば、公平、公正の立場に立てば、もう一回商店街等にそれをお願いして、ある一定度のパーセントに、もし回収率がいかないのであれば、その商店街にはほかの意味での助成金は払わないというような政策を打ってほしいと思いますが、まずその点の考え方と、パーセントの調査の実態を教えていただきたい。","respondent":"岩田管理工事課長、片田建築課長、藤田都市計画課長","answer":"各商店街連合会を通じまして、区から、こういう実態ですよということを明らかにさせていただいて、個々の商店街にも説明をして。そういったものについては、行政サービスの対価としてそういう部分も、すべてではございませんけれども。ただ、現在品川区ではワンルームマンションが極めて多いというような状況ではございませんので、今後品川区の将来ビジョンを検討する。","voiceIndex":114,"id":"exchange-050"},{"speaker":"石田委員","kind":"質問・要望","question":"建築確認のほうですが、今は半数ということで、これで推移していくということであれば、今おっしゃったように、電話だ何だということがありますが、窓口業務の方は非常に大変だと思いますので、そこら辺のところは認定でも何でもそういうことで徴収できる部分はしっかり徴収していただきたいと思います。今の要綱から条例ということでありますが、この点はもう１点お聞きしたいと思います。","respondent":"浜脇住環境整備課長","answer":"そういうことでありまして、品川区の全域からそういう声ということではなくて、私どもが聞いているところでは、ある一定のところで出ているわけですので、そういった意味では、今都市計画課長が申しましたように、あるまちづくりの中で。","voiceIndex":118,"id":"exchange-051"},{"speaker":"石田委員","kind":"質問・要望","question":"町会参加もお願いしている。ファミリータイプの方は大分努力をしてやっている部分もあるけれども、ワンルームの部分は非常に難しいというところがあるのであれば、そこら辺の点は地区計画でも構わないけれども、そういう話があったときには、要綱だって限界があるわけだから、もちろん条例でもあるんだけれども、その点をもう１段進んでやっていただきたいというのは、要望にして、これでやめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-052"},{"speaker":"菊地委員","kind":"質問・要望","question":"私のほうからは、２８７ページの大井町駅周辺の開発、ＪＲ広町地区の開発についてお尋ねをしたいのと、もう１点、石田委員と同様に、紛争調整事務費についてお伺いをしてまいりたいと思います。もう１点ですけれども、昭和６２年にプレイス構想をつくったときというのは、２８haで、工場から住宅、区庁舎なども構想に入っていたようですけれども、今回の事業の範囲について教えていただきたいと思います。","respondent":"上野都市開発課長、市岡企画財政課長","answer":"広町プロジェクトに関します幾つかのご質問ですけれども、まずＪＲとの協議の進捗状況ですが、今回の第１回定例会の代表質問でもご答弁をしているところでございまして、昨年来ＪＲと実務レベルでも何回か協議をしてきておりまして。原っぱ公園は平成４年、５年、６年にかけて買っておりまして、総額が１７１億円余です。","voiceIndex":122,"id":"exchange-053"},{"speaker":"菊地委員","kind":"意見","question":"私もプレイス構想というのは、昔の冊子を見るしかわからないんですけれども、品川区の今後のまちづくりにとって極めて重要な拠点になるというふうに当時も位置づけをされているんですけれども、現在の位置づけですとか、目的とそう変わっていないというように思うんですけれども、もう少し詳しいところはどうなんでしょう。","respondent":"上野都市開発課長","answer":"その協議を進めるにあたりましては、大井町駅周辺地域の現状も踏まえまして、どういった課題があるのか、例えば交通ネットワークの形成とか、大井町西地区の開発動向の動きとか、そういった周辺の動向も見据えながら、課題の抽出を行っているとか。","voiceIndex":125,"id":"exchange-054"},{"speaker":"菊地委員","kind":"質問","question":"品川区の中心核というのが、今回プロジェクトを組んでいった、説明の中にありますけれども、区庁舎が構想の中に入っていないというのは、中心核にしていくんだという目的から見ると、別に開発を進めろと言っているわけではないんですけれども、非常におかしな感じがするんですけれども、現時点では入っていないけれども、これからの協議の中でどうなるかわからないよという立場なのかどうか。","respondent":"上野都市開発課長","answer":"ただ、大井町全体の中心核をつくっていくときにどういうふうにしていくかということについては、周辺区域との関連を考えていかなければいけませんから、そういう意味で隣接している区役所の敷地、その中でも。","voiceIndex":127,"id":"exchange-055"},{"speaker":"菊地委員","kind":"質問・要望","question":"もう１点ですけれども、１７１億円で種地を買ったということですけれども、この開発の種地というのは、性格上どんなものにでも転用していくということが可能なものなのかどうか。","respondent":"上野都市開発課長","answer":"種地の性格ですけれども、これはまちづくり事業用地として取得したものですから、将来のまちづくりに備えるといった性格の土地です。","voiceIndex":129,"id":"exchange-056"},{"speaker":"菊地委員","kind":"質問","question":"天王洲の、今森ビルに等価交換ということで、床をベンチャー企業に貸していくということでやっていますけれども、あれも開発の種地として買われたわけですけれども、今のご返事ですと、あの土地はあくまでも再開発のためのもので、転用できないという話なんでしょうか、ちょっとそこをお願いいたします。","respondent":"上野都市開発課長","answer":"先ほど将来の開発のためにというふうに申し上げましたけれども、現在は１０年間は原っぱ公園として利用する。","voiceIndex":131,"id":"exchange-057"},{"speaker":"菊地委員","kind":"質問・要望","question":"いずれにしても、この問題というのは、もう少し広く区民を交えた、商店街、あるいは実際にこのアパートには多くの皆さんが住んでいらっしゃるわけですから、こうした皆さんも含めた協議の場というのをぜひ設けていただきたいなというふうに思います。","respondent":"浜脇住環境整備課長","answer":"今回の改正したときに検討したものですと、中高層の建築に絡むものにつきましては、解体についても一緒に説明をするようにということで、現在検討をしているところでございまして、７月の条例改正に向けてそれらを整理してまいりたいというふうに考えているところてあります。","voiceIndex":133,"id":"exchange-058"},{"speaker":"菊地委員","kind":"質問","question":"例えば木造の家屋であろうと、あるいはＳＲＣの建物であろうと、とにかく後にマンションが計画をされるものについては、その対象だということなんでしょうか。紛争の際に事業主が言うのは、更地にしてから買ったので、前のことはわかりませんという言い逃れがよくありますけれども、そうしたものが対象になっていくのかどうか、そこをお聞かせください。","respondent":"浜脇住環境整備課長","answer":"今の件ですけれども、これはあくまでも中高層の建物を建てるという前提の方について、セットしてもらうということでございまして、将来何に使うかわからないというものについては、今の検討の中では含まれていないような検討をしています。","voiceIndex":135,"id":"exchange-059"},{"speaker":"菊地委員","kind":"質問・要望","question":"今もお話ししましたように、前段の改築によるほこりとか、騒音が業者の大概の口実になるわけですよね。ここはこれからつくっていくということですから、ぜひこの辺は十分に考えて盛り込んでいただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-060"},{"speaker":"嶋委員","kind":"質問・要望","question":"私のほうからは、大きく二つお伺いをします。一つは、２６７ページ、交通安全対策費、２７５ページの道路バリアフリー事業に関連して、京浜急行線の青物横丁駅周辺と、りんかい線、品川シーサイド駅周辺について、モノレール、大井競馬場駅周辺についてお伺いいたします。二つ目には、２８３ページ、公園・児童遊園維持管理費についてお伺いをいたします。","respondent":"藤田都市計画課長","answer":"それに加えまして、平成１５年、りんかい線全線開業後、これは年度途中ですので、１２月までのデータの平均ですけれども、４万２,０００人というふうに聞いてあります。","voiceIndex":155,"id":"exchange-061"},{"speaker":"嶋委員","kind":"質問・要望","question":"今はりんかい線が通りましたけれども、青物横丁駅周辺の道路、歩道整備というのが以前と変わっていないという中の今回の人数、５,０００名ですが、朝は大変厳しくて、ジュネーヴ平和通りにも最近マンションができまして、そのマンションの方たちとか、青物横丁駅をご利用される方たちが駅に向かうときに、とても前に進める状況でないということで、どうにかならないかというお話がありまして、今のところ。","respondent":"上野都市開発課長","answer":"そういった形で優先整備路線になってありますけれども、その中身がどういった中身かと申しますと、現在概ね道路のほうはでき上がっておりますけれども、あと５ｍほど道路が広がる予定になってあります。","voiceIndex":157,"id":"exchange-062"},{"speaker":"嶋委員","kind":"確認","question":"そこの交差点ですが、特に夜間ですが、タクシーが横断歩道にずっと駐車をしている。特にふ頭橋から海岸通りに出てくるときに、左折をする車がほとんどそこに、タクシーが駐停車をしていますので、そこから出てくる歩行者を確認することが厳しいということで、タクシー乗り場にはなっていないんですが、バス停留所のところにタクシーがそのまま何台か並んでいるということです。","respondent":"松代道路公園課長、上野都市開発課長","answer":"先ほどから委員ご指摘のとおり、そこの交差点、早朝、通勤されるサラリーマン等で非常に歩行者動線、安全対策、そういったものが必要ということで、私どもも認識しています。ふ頭橋から左折してくるタクシーの計画が当初どうであったかですけれども、ＪＴの用地を開発するときに、将来のものとして考えていたものは、品川シーサイド駅の駅広の計画については、バスとか。","voiceIndex":159,"id":"exchange-063"},{"speaker":"嶋委員","kind":"質問","question":"住民が今まで以上に、また安心して住める住環境整備をぜひお願いをしたいと思います。正しい言葉があるかどうかわかりませんが、仕切り線みたいなのが何かあると、混んだときに、自転車を走る人は何となくこっち、歩く人はこっちと自然に流れができるのではないかなというふうに思っておりますが、大井競馬場通りの歩道に関してちょっとお聞きをしたいと思います。","respondent":"松代道路公園課長","answer":"私ども今できておりますのは、看板等を設置しまして、注意を促すというようなことをしております。今日の提案とも、少し流れ等も含めまして、検討をさせていただければと思います。","voiceIndex":164,"id":"exchange-064"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。自転車道路と決めることはなくて、仕切り線というソフトな部分で自然と人が流れを自分たちでどっちかを選んでいくという形にぜひしていただきたいと思います。それから、次に、２８３ページの、公園・児童遊園の維持管理費、まず最初に、公園と児童遊園の仕切りみたいものをお知らせいただきたいと思います。","respondent":"岩田管理工事課長","answer":"ただ、区民の方から見ても、名前が違うだけで、同じというのは事実でございまして、私ども管理する側においても制限とか、そういった違いというのは特にございません。","voiceIndex":166,"id":"exchange-065"},{"speaker":"嶋委員","kind":"質問・要望","question":"日だまりの横の八潮北保育園の横の公園のことですが、ただ、1)公園でしかなかったものですから、私は１番地区公園と呼ばせていただいておりますが、ここには日だまりにいらっしゃる方、隣が保育園、北小学校があるということで、何もない、逆にシンプルな公園ということで、皆様がゆっくりとされるところです。","respondent":"松代道路公園課長","answer":"加えまして、八潮の公園ですけれども、これは都営住宅が敷地内に設けた公園だというふうに認識しています。そういった要望等があれば、私どもからも向こうのほうに伝えたいと思います。","voiceIndex":168,"id":"exchange-066"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひお願いをして、児童遊園、私のほうに要望があったのは、区立浜川児童遊園でございました。地域の皆様のご要望ですので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":170,"id":"exchange-067"},{"speaker":"原委員","kind":"質問・要望","question":"私のほうからは、２点、毎回お伺いをさせていただいているんですが、また今回もよろしくお願いをいたします。２６７ページ、交通安全対策費で、自転車の安全走行についてお伺いをいたします。それから、２７３ページ、都市計画道路の補助２０５号線、光学通りのお話をさせていただきたいと思います。これでどのぐらいの平米を買収しようとしていらっしゃるのか、ちょっとお伺いします。","respondent":"奈良交通安全担当課長、中島街路事業担当課長","answer":"今月中には各自転車店、それから、二つの保管所、それから、自転車等を扱っているスーパー、各警察署等に配布をする予定にしております。それと、道路整備費の１億５,０００万円ですけれども、こちらは補助２０５号線につきましては、ただいま小野学園の前の部分と、第２期区間と申します、東京浴場から補助１６３号線の出口のところ、２カ所道路整備をしてございまして。","voiceIndex":172,"id":"exchange-068"},{"speaker":"原委員","kind":"質問","question":"これをどう取り締まったらいいのかというのが大事なんで、確かにその中ではパンフレットを配ることも必要な一つだろうと思うんですが、現状はあまり変化のないところで、どう取り締まっていこうか考えていらっしゃるかどうかお伺いいたします。土地を買う場合は相手があることですから確かに更正減額されるかもしれませんけれども、道路整備の上ではこんなに残ってしまうということはどういうことなのか。","respondent":"奈良交通安全担当課長、中島街路事業担当課長","answer":"そうしない限りは自転車のマナーはよくならないということで、警視庁本部のほうから各警察署のほうへはきちんと指示が出ているそうですので、私のほうも署にお邪魔するたびに、見てみぬふりをしないで、きちんと指導。２点目の、工事費が大きく減額ですけれども、これにつきましては、午前中に企画財政課長のほうからも申し上げましたけれども、平成１５年度中にＣＣボックスの工事と、道路整備まで完成させる予定でございましたけれども。","voiceIndex":175,"id":"exchange-069"},{"speaker":"原委員","kind":"質問・要望","question":"補助２０５号線のほうですけれども、分かりました。ここのところは、今回１７０m2、それを予定をされていて、全面開通するまでにまだ時間がかかりますね。全面開通はいつ頃の予定を組んでいらっしゃいますか。そうすると、全面開通で、あそこで止まってしまうということは、当初の計画ではおそらくなかったんだろうと思うんですけれども、その辺のところの考え方を教えていただきたい。","respondent":"中島街路事業担当課長、藤田都市計画課長、奈良交通安全担当課長","answer":"もう１点、補助２０５号線で、１階のエリアで１人の権利者が全部係わっているところがございまして、そこにつきましては。補助２９号線につきましては、さまざまな意見がありますけれども、まちづくりの観点から。私のほうでも、生活安全サポート隊とどういう連携がとれて、どういう方法でできるのか、よく検討をしてみたいと思います。","voiceIndex":178,"id":"exchange-070"},{"speaker":"木下委員","kind":"質問・要望","question":"私のほうは、２８７ページ、都市開発費の都市防災不燃化促進事業、それから、密集住宅市街地整備促進事業、２９１ページ、建築行政費の中高層建築物開発指導費、建築物紛争調整事務費の件についてお尋ねしたいと思います。品川区は震災の際一番危険だと言われている地域なども一部ありますので、こういう考えがあるのかどうなのか、その部分についてお答え願えますでしょうか。","respondent":"片田建築課長","answer":"ちょっと前後いたしましたけれども、私どもの建設委員会の３月２日の委員会の中で、新たな防火制度の導入についてといったことで、区の考え方としてご説明させていただいた経緯がありますけれども、具体的には昨年の３月、東京都のほうで建築安全条例の一部改正を行いまして。","voiceIndex":183,"id":"exchange-071"},{"speaker":"木下委員","kind":"質問","question":"金融公庫と提携して、１０年間は金利が２.５％、１１年目から３５年目は３.５％、これは普通の住宅金融公庫の融資で受けられる融資と全然変わらないから、どういうメリットがあるかというのをお聞きしたんです。","respondent":"片田建築課長","answer":"通常ですと、公庫の融資を受ける場合には、敷地面積が１００m2以上であるとか、一定要件が必要になってくるんですけれども、今回の場合は敷地面積が７０m2以上であればよろしいとか、一定程度隣地の空きを５０cm以上設けるとか。","voiceIndex":185,"id":"exchange-072"},{"speaker":"木下委員","kind":"質問","question":"融資を受けられる、条件が軽減されたですね。それと、さっきもう一つ、墨田区、中野区、荒川区の一部では準耐火構造以外の建築以外は建設できないように規制すると。それは品川区のほうも規制されるというふうな考えでよろしいんでしょうか。","respondent":"片田建築課長","answer":"品川区においてもそういう制度を検討するにあたって、制度としてはこれまでの防火構造と言われるものができづらくなるといったような状況です。今、現況としての地域についての検討をこれから検討していきますといったような内容です。","voiceIndex":187,"id":"exchange-073"},{"speaker":"木下委員","kind":"質問","question":"２番目の項目として、先ほどほかの委員からもワンルームマンションの話がありましたけれども、理事者の感覚と、我々のいつも地元の住民の方々と接している委員との感覚のずれがあるかなというのを、先ほど聞いて感じたんですが、品川区にワンルーム建設指導指針というのがあるようですけれども、どのように機能しているのか、また、効果が上がっているのか、お教え願えますでしょうか。","respondent":"浜脇住環境整備課長","answer":"その中ではワンルームマンションの３階建てで、２５m2未満の床面積の１５戸以上をワンルームと呼んでいるわけですが、それにつきましても、周辺との環境ということで、建築計画の説明でありますとか、管理人の管理人室を設けることとか、自転車の車庫を設けることとか。","voiceIndex":189,"id":"exchange-074"},{"speaker":"木下委員","kind":"質問","question":"先ほどの質問に加えて、効果が上がっているのかどうなのか、後でまたお知らせいただければと思います。文京区のような、例えば管理人を置かなければならないですとか、もうちょっと要綱を厳しくするような考え等はありますでしょうか。","respondent":"浜脇住環境整備課長","answer":"そういったことで、私どもから見れば一定の成果は上がってこれまでやってきたなというふうに思ってあります。それから、５０戸以上のワンルームにつきましても、管理人を置くように、中でも設けておりまして、管理人がいるワンルームもあります。","voiceIndex":191,"id":"exchange-075"},{"speaker":"木下委員","kind":"質問・要望","question":"時間もございませんので、委員の要望として、そういう声がありますので、これからも厳しく指導をしていただくようにお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":193,"id":"exchange-076"},{"speaker":"西本委員","kind":"質問","question":"公園管理ですが、公園を区民の方が借りるときと、区主催、共催も含めて、いろいろ使われる場合とで、使い方の規定というのはあるんでしょうか。こういう場合に使ってはいけないというところでの制約といいますか、それは両者間での違いがあるのでしょうか。それをお聞きしたいと思います。","respondent":"松代道路公園課長","answer":"利用にあたっては、お使いになる時間帯等をこちらで制限をします。公園等はなるべくお子さんを中心として、学校が終わった放課後などにはなるべく団体利用を避けて、お子さんに優先的に使っていただく。そういったものがありますので、そういったものの制限をしています。","voiceIndex":195,"id":"exchange-077"},{"speaker":"西本委員","kind":"質問","question":"その辺はある程度分かっているんですが、例えば公園の中での火でありますとか、それからお金のやりとりでありますとか、そこら辺の違いというのはどうなんでしょうか。","respondent":"松代道路公園課長","answer":"もちろん今委員がおっしゃいましたように、火を使うということはできません。唯一火を使えるところはしながわ区民公園のデイキャンプ場とか、そういった限られた施設です。そのほかにも禁止事項が幾つかあります。","voiceIndex":197,"id":"exchange-078"},{"speaker":"西本委員","kind":"質問","question":"一番初めの質問ですが、制限に対して、区主催でいろいろ行事をされる場合と、区民の方が借りて利用される場合とでの違いはあるのでしょうか。","respondent":"松代道路公園課長","answer":"そういった場合には当然優先的に公園を使ってやっていただくケースがあります。町会行事とか、地域の行事、そういったものがあります。そのほかにも、今申し上げましたようなリサイクルの観点からフリーマーケットとか、そういったものもあります。","voiceIndex":199,"id":"exchange-079"},{"speaker":"西本委員","kind":"質問・要望","question":"しかしながら、私が係わった中で、区民の方たちに利用していただきたいという行事をしたときに、２,０００人弱の方が集まります。そこを申請の段階できっちりさせるとか、あとは実績を見ていただくとか、ということで、公園の使い方についてもう少し緩和できるような方向性にいっていただけないものかなというふうに希望を持っているんですが、その辺のお考えはいかがでしょうか。","respondent":"松代道路公園課長","answer":"そういう中では、ほかの利用者の安全とか、そういったものの観点からご注意は申し上げますけれども、なるべく地域の皆さんがそういった中でご利用いただく、また地域の方が責任を持ってやっていただくという範疇で、私ども原則はきちんとありますけれども、実際使われるときには。","voiceIndex":201,"id":"exchange-080"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、それだからと言って、あまりにも広げてしまうと管理も大変と思いますので、そこら辺は団体等の話をきちんとしていただいて、できるだけ要望に応じる。次に、２８７ページの区民の自主的なまちづくりの支援というふうになっておるんですが、これはどういう内容なのか、新しく始まるものなのか、もしも今までの実績があるのであれば、どういう実績があるのか教えていただきたいと思います。","respondent":"浜脇住環境整備課長","answer":"事業の目的ですけれども、区民の方々が自主的に地域特性に応じたまちづくりを進める際に、最初のほうに勉強会といいますか、どんなまちづくりをしたらよろしいかといったようなときに、そういう団体をつくっていただきまして、それを申請していただければ。","voiceIndex":203,"id":"exchange-081"},{"speaker":"西本委員","kind":"質問","question":"実績がかなりあるというお話でした。こういう制度があるということが、私も気がつかなかった部分がありまして、区民の皆さんへの周知はそこら辺はどういうような活動をされているんでしょうか。","respondent":"浜脇住環境整備課長","answer":"ちょっと話が違ってしまうかもしれませんけれども、紛争などでこれからどんなまちづくりをしていったらいいんだろうかというようなことで、ご相談に来たときにも、これをご紹介をして、こういうまちづくりにするためにはこの制度を使ってやったらいかがでしょうかというので。","voiceIndex":205,"id":"exchange-082"},{"speaker":"西本委員","kind":"質問","question":"いろいろな広報をされているということですが、いろいろなところでホームページでという話をよくご答弁の中でお聞きするんですが、先ほども委員のほうからお話があったように、ホームページというのはまだ特定の方の利用になってしまうところがあると思います。今後もっとほかの媒体を使うとかというご検討はあるでしょうか。","respondent":"浜脇住環境整備課長","answer":"どちらかというと、皆さん方が集まったら呼んでいただくというほうが一番浸透していくのかなと考えていますので、そういった際にはぜひ呼んでいただいて、私か、あるいは職員が行って、こういうものをＰＲさせてもらえればありがたいと思ってあります。","voiceIndex":207,"id":"exchange-083"},{"speaker":"西本委員","kind":"質問・要望","question":"なるべくいい制度があるということは広く伝えていただきたいと思います。次に、２６７ページの、交通安全啓発費の中のヒヤリ地図ですが、４カ所ということですが、今後どういう形でこれを広げていこうとされているのか、その辺をお聞きしたいと思います。","respondent":"奈良交通安全担当課長","answer":"ヒヤリ地図は平成１３年から始めた事業ですけれども、区内４カ所、各警察署１カ所ずつ、計４カ所ということでやっていたんですが、これが順調に進行しておりまして、ちょっと計画変更をしまして、５年の２０カ所で、現在終わる予定にしております。","voiceIndex":209,"id":"exchange-084"},{"speaker":"西本委員","kind":"質問・要望","question":"これから２０カ所増えるということで、かなり網羅的になるのではないかなというふうに思うんですが、このつくり方ですが、ここが危ないとか、いろいろ注意事項とかあるかと思うんですが、そこはどういう形でこれをつくっておられるのか、作成の方法を教えていただきたいと思います。","respondent":"奈良交通安全担当課長","answer":"作成にあたりましては、その地域内に住んでいらっしゃる高齢者の方、あるいは学校のご父兄の方々、あるいは子ども、それからあとは、常日頃区内を回っております郵便局の職員の方、そういう方々に常日頃この辺はヒヤッとするよという地点を選び抜いていただいて、地点に落として。","voiceIndex":211,"id":"exchange-085"},{"speaker":"西本委員","kind":"質問・要望","question":"要望になりますが、地図ができたというところで、その地図をもとに安全対策というのが当然出てこようかと思います。例えば信号機が必要なところがあるのではないかとか、鏡とか必要ではないかというところが、多分そこらで露出されてくると思うんですけれども、そこのところの改善といいますか、リンクの仕方をお聞きして、終わりたいと思います。","respondent":"奈良交通安全担当課長","answer":"十分その点を配慮しまして、今後とも交通安全関係も十分やっていきたいと思います。","voiceIndex":213,"id":"exchange-086"},{"speaker":"田中委員","kind":"質問・要望","question":"私は、２８３ページ、運動施設改修工事、しながわ中央公園１点に絞ってお伺いをしたいと思います。区長の最終的ご決断に対しては、私自身も尊重していきたいということを冒頭に申し上げながら、しながわ中央公園に対する私なりの問題意識を持っておりますので、お伺いをしていきたいと思います。その後、議会からの要望がありまして、天然芝に変更するという政策変更の決定がなされました。","respondent":"岩田管理工事課長","answer":"政策変更というような大げさなこととは考えておりませんで、しながわ中央公園の目的というのは、第１期工事部分というのはあくまで区民の方のスポーツの場、健康増進の場として使っていただくというのが目的でございまして、そのための手段の一つだったわけです。","voiceIndex":216,"id":"exchange-087"},{"speaker":"田中委員","kind":"質問・要望","question":"私の問題意識の２点目としまして、公共施設の利用のあり方という部分ですが、ご案内のとおり、公共施設というのは全区民の共有の財産であります。まさに運用面で整合性を埋めていく必要が出てくるのではないかと思うんですが、公共施設の利用のあり方という観点で、このような結果になっていることをどう捉えていらっしゃるのか、お聞かせいただきたいと思います。","respondent":"岩田管理工事課長","answer":"結果として、たまたま申し込んでいただけたのが、残念ながらお隣の学校しかなかったということでございまして、私どもは問題はないと考えています。","voiceIndex":218,"id":"exchange-088"},{"speaker":"田中委員","kind":"質問・要望","question":"私の問題点の３点目として、緑化対策に対する今後の取り組みという観点でちょっとお聞かせいただきたいんですが、ご案内のとおり、温暖化対策の一環で品川区としての緑被率を向上させるために、特に民間に関しては屋上緑化の助成ですとか、生垣助成等々行っております。品川区自身としても公共施設の緑化対策が求められ、現に実行もされております。","respondent":"岩田管理工事課長","answer":"千葉などは何校かありますし、２３区の中でもちょっとやったところがあるようですけれども、なかなか大変なようです。そういうところを教育委員会のほうも現地を見てきているようですので、私どもとすれば、そちらのご判断にお任せしたいと考えています。","voiceIndex":220,"id":"exchange-089"},{"speaker":"田中委員","kind":"質問・要望","question":"ご案内のとおり、法治国家ですから、憲法があり、法律があり、地方自治体は条例があって、規制があって、要綱、要領、指針等々があるもとで、さまざまな事業がなされております。我々議会が関与できる部分というのは、議決が必要ですから、条例に対しては関与ができます。それ以外に対しては直接は議決を要さないという部分で言えば、議会側の関与がなかなかできません。","respondent":"岩田管理工事課長","answer":"一般論は差し控えさせていただきまして、公園条例に関しては、昨年の第１回定例会に条例でかけさせていただいたときにも、学校優先枠についてはきちっとご説明をさせていただきました。条例の別表の中で学校というものの表現が出てまいります。","voiceIndex":222,"id":"exchange-090"},{"speaker":"田中委員","kind":"質問・要望","question":"そのとき私は建設委員会におりましたが、今おっしゃられたように、条例が議決された後に規則を決めるということでしたので、そこの部分がどこまで思いを伝えられたかというじくじたる思いがありますが、ぜひ今後も条例にかからない規則、要綱が本来の事業の内容を大きく左右するものもたくさん含まれますので、これは議会側の要望として強く受け止めていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":224,"id":"exchange-091"},{"speaker":"藤田委員","kind":"質問","question":"そこでお聞きしたいのは、樹木を植えるにあたりまして、区民の皆さんより寄附を募って、その寄附をされた方々のお名前を銘板として残すんだという話ですが、これはどのような内容で残すのか、寺とか、神社のような未来永劫に名前を残していくのか、期限を切って残すのか、その辺をお伺いしたいのと、犬の散歩等は当然禁止をされていくのではないかと思いますが、その辺ちょっとお伺いしたいと思います。","respondent":"岩田管理工事課長、松代道路公園課長","answer":"素材は強化ガラスで、そこに印刷したものを張り付けるという形で、５００円の一般寄附と、樹木の特定寄附者のお名前を書かせていただきまして、お礼のお言葉と同時に、ここに書いて、未来永劫残すということで、今工事を進めております。犬の散歩の件です。しながわ中央公園も含めまして、現在のところ原則禁止という形をとってあります。","voiceIndex":226,"id":"exchange-092"},{"speaker":"藤田委員","kind":"質問","question":"時間の関係で続けます。ですから、今回も石で固められています、立派な石ですが、きれいに管理されていけばいいんですけれども、当然そういうのを予想してこういう公園というのはつくっているのかどうか。ですから、何を言いたいかといいますと、あと１５cmぐらい下げて土留をつくって、その前に生垣のようなもの、２０cmぐらいでもいいですよ、低いものをずっとやれば必ずいたずらをされません。","respondent":"岩田管理工事課長","answer":"芝桜については、少し検討をさせていただきたいと思います。","voiceIndex":229,"id":"exchange-093"},{"speaker":"藤田委員","kind":"質問・要望","question":"品川区の場合は緑のネットワークをつくるように考えられていますね。楠の木でしょうか、４本、５本とずっと残っていますね、高木も植えましたね。それともう一つ、申し込みがなくて、一般区民がグラウンドを使えるようなそういう状態になっているんでしょうか。申し込まないで、土曜、日曜にふらっと、どの団体も使っていない場合は一般区民が行って、少し走ろうかなと、こういう場合はできるんですか。","respondent":"岩田管理工事課長","answer":"巣箱のことについては、いろいろご意見もあるようですので、これは検討課題とさせていただきたいと思います。","voiceIndex":231,"id":"exchange-094"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私は、２９１ページの木造住宅耐震診断支援事業に関連しまして質問をしたいと思います。私は大いに歓迎したいと思うんですけれども、新年度予算では４０棟が予算化されております。当初、品川区の制度のほうは住宅の密集した危険度の高い地域というふうにおっしゃっていたと思うんですけれども、今回は地域の限定が外してありますけれども、そこら辺の考え方についてお伺いしたいと思います。","respondent":"片田建築課長","answer":"一応そんな中で、昭和５６年以前の建築物の想定につきましては、この約半数ぐらい、件数でいきますと２万３,０００棟ぐらいが木造住宅で、昭和５６年以前に建築された建物かということで一応認識しています。","voiceIndex":236,"id":"exchange-095"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今、危険地域を外した理由というふうに伺いたかったんですけれども、第４回定例会の一般質問でも私はこの問題を取り上げてお伺いしたんですけれども、そのときには、補強工事等も助成というふうな制度ができないものかというふうに要望したことがあります。診断を受けて、問題があったら補強するなり、場合によったら建て替えると。","respondent":"片田建築課長","answer":"私どもは今回初めての事業の見込みですので、他区の支援制度の状況を含めて今回４０棟というものを一応想定したものです。それと、利用者の対象についても、これは特に固定するわけでございませんで、区内の建物をお持ちの方を対象としているものです。","voiceIndex":238,"id":"exchange-096"},{"speaker":"宮崎委員","kind":"質問","question":"こういう方が実際にこの制度で救われていくということが、この制度の趣旨になっていくのではないかというふうに思うんですけれども、そういうところの実態というか、実際にこの制度がうまくかみ合っていくには、こういう方のところも利用できるような制度になっていかなければいけないと思いますし、そこの調査はどういうふうに考えているか、あるいはもう一つ。","respondent":"片田建築課長","answer":"一つ、周知の件につきましては、今回の制度と合わせて私ども耐震支援のパンフレットを策定して、区民の方に広くお知らせしていきたいということで考えております。","voiceIndex":240,"id":"exchange-097"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、実態がどうなっているか。２３区のところで、例えば台東区のところですと、これは補強工事のほうですけれども、高齢者等、または障害者の方が居住する木造住宅、全部ではないけれども、いわゆる社会的弱者という方のところに焦点をあてて、こういう制度を設けておりますけれども、そういうことも含めて、配慮はできないものかどうかお伺いしたいと思います。","respondent":"片田建築課長","answer":"したがいまして、今回の制度につきましても、地域のそういう資格を持った専門家に、地域密着型といいましょうか、そういう方向で考えているということもありますし、あと、支援制度のメニューとしても、住宅修築資金、融資あっ旋制度とか。","voiceIndex":242,"id":"exchange-098"},{"speaker":"宮崎委員","kind":"質問・要望","question":"この制度は新年度から始まるというわけですから、これは中身を見ながらということになってくるかと思うんですけれども、特に社会的弱者といわれる方々とか、あるいは今資金力がない方、そういう方々のところにも思いを寄せながら、この制度を運用していただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":244,"id":"exchange-099"},{"speaker":"山村委員","kind":"質問・要望","question":"交通弱者が東急ストアのほうに行こうとしますと、現在ですとかなり遠回りしないと、歩道橋のみですので、この大規模改修に伴い、駅改修後はエレベーターが設置されるようなことをお聞きさせていただきましたが、交通弱者の利用しやすいまちづくりのために、ＪＲ側に要望をさらにしていただき、それと伴い、周辺の道路環境を整備して、どうにかならないでしょうかということをお聞かせいただければと思います。","respondent":"奈良交通安全担当課長","answer":"１点目の区内の自転車の保有台数の件ですけれども、これは防犯登録上からすると、２０万台強です。ただ、防犯登録をされていない方の数ものぼりますので、２５万から２６万ぐらいというふうには推測しております。","voiceIndex":246,"id":"exchange-100"},{"speaker":"山村委員","kind":"意見","question":"動態調査のほうですが、確かに区民全員分というのは難しいとは思うんですが、特に自転車の駐輪問題が起きているところなどは動態調査をしていただいて、的確な政策をとっていただければと考えています。それに関して、自転車対策をまちづくり対策の中でどのように位置づけているかということのお考えを聞かせていただければと思います。","respondent":"中谷まちづくり事業部長","answer":"そういう方向はありますが、区内は、ご存じのとおり、道路が非常に狭い、そして自転車専用道を併せてつくるという方向はありますが、これにつきましても、区内ではなかなか難しい。","voiceIndex":252,"id":"exchange-101"},{"speaker":"山村委員","kind":"質問・要望","question":"そのような方向でぜひ頑張っていただければと考えています。次に、２９３ページの住宅改善資金融資あっせん・助成事業ですが、こちらの融資助成内容を教えていただきたいのとともに、防犯に関しての融資や助成はできるのか、できないのかということを教えていただければと思います。","respondent":"田村住宅課長","answer":"内容的には、一つは、住宅修築資金あっせん事業の内容の見直しということで、冒頭企画財政課長から説明がありましたけれども、金額の７００万円を１,０００万円に引き上げ、それと、今まで保証人必置でしたが、保証人に代わって保証機関も利用できる、二者選択できるという形と。","voiceIndex":256,"id":"exchange-102"},{"speaker":"山村委員","kind":"質問","question":"リフォームで鍵を一つではなくて二つにするですとか、窓に鉄格子を入れるとか、そういうことも融資の対象になっていると考えてよろしいんでしょうか。","respondent":"田村住宅課長","answer":"割れないように金網入りのガラスにするとか、今はマンションもそうですけれども、ピッキング対応で、鍵を取り替えるというのは、その意味からすれば、修復事業の内容はかなり弾力的に解釈できると思うので、既存のリフォームの範疇で対応できると、そのように考えております。","voiceIndex":258,"id":"exchange-103"},{"speaker":"山村委員","kind":"意見","question":"そういう意味で対処できるわけでしたら、防犯対策のほうも助成できますようなことをもう少し前面に打ち出していただいてもよろしいかと思いますので、どうかこれからも頑張ってください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":260,"id":"exchange-104"},{"speaker":"本多委員","kind":"質問","question":"例えば区議会で議案が出されて、そういう手続はもちろんあるんですが、その以前になるべく具体的な道路の位置というんでしょうか、図面上とか、机上で構わないと思うんですが、そういったものが協議を進展するために必要じゃないのかなと思うんですが、区内全域を見てどのような感じでしょうか。","respondent":"上野都市開発課長","answer":"再開発に関係して、その中で整備される区道の拡幅関係ということでお答えしますけれども、今までの通常の考え方というか、進め方といたしましては、計画すべき範囲を地区計画で決定いたしまして、その中で再開発事業を施行していくといったのが比較的多いかと思います。","voiceIndex":262,"id":"exchange-105"},{"speaker":"本多委員","kind":"質問・要望","question":"さきの本会議で議案が付託されました３４号議案、これは大崎第３地区の近隣の区道について変更と位置指定というところがありましたけれども、この都市再生の６０haに限ってちょっとお聞きしたいんですが、６０haの外枠は全部確定はされていると思うんですが、中の部分、道路の拡幅する部分ですとか、変更する部分ですとか、ある程度素案はできていると思うんですが。","respondent":"上野都市開発課長","answer":"大枠だけを示しているものでございまして、これにつきましては開発事業を進めている事業者などを通じて地元に対してご説明していますけれども、先ほどの都市再生の１０年との絡みで申しますと、今後１０年間で具体的に動いてくる地区があります。","voiceIndex":264,"id":"exchange-106"},{"speaker":"本多委員","kind":"意見","question":"測量を進めるにあたりましては、道路の拡幅するにあたりましては、原則道路の中心線から拡幅する、中心線から基準にするんだと思うんですが、必ずしもそうでないと思いますので、そういった意味で早め早めの情報があれば、それが判断材料になると思いますので、その辺ぜひお願いしたいと思います。","respondent":"上野都市開発課長","answer":"センター振り分けにするか、片側振り分けにするかとか、詳細についてはこれから決まっていくことですけれども、再開発事業の中で整備するものにつきましては、施行区域内で道路をつくっていきますので、施行範囲がどこになるのか。","voiceIndex":266,"id":"exchange-107"},{"speaker":"堺委員","kind":"質問・要望","question":"私のほうから３点、簡単にお尋ねします。３点目が、２８５ページにあります東中延公園の便所の件についてお尋ねをします。今回このように７１０万円の予算が計上されたわけですので、大変喜んでいるわけですが、そこで予算が可決決定になりましたら、地元としては、速やかにぜひここを早期着工、早期完成をお願いをしたい、こういう強い要望がありますので、その辺についてのご見解をお聞かせください。","respondent":"中島街路事業担当課長、岩田管理工事課長、上川内生涯学習課長","answer":"したがいまして、計画どおり進みますと完成年度が平成２０年度、平成２１年３月末です。東中延公園の便所の新設の件ですけれども、委員のご趣旨に沿ってできるだけ早めに完成するよう努力してまいりますが、これは一般建築物になりますので。その数と一般の有料で借りられた方たちの数を合わせますと５７６回一般が借りられ、学校が４８６回借りられているという状況です。","voiceIndex":269,"id":"exchange-108"},{"speaker":"堺委員","kind":"質問・要望","question":"先ほど来からもいろいろお話が出ておりましたが、もう一回月曜から金曜までは学校が優先的に利用できるけれども、土曜、日曜については一般が利用できるですけれども、今もちょっと、使っていないときは無料開放で２８３とか、いろいろ数字を挙げられましたけれども、例えばふだんの日の夜間の一般の利用実績、あるいは土曜、日曜の一般の利用実績が出れば教えていただきたいと思います。","respondent":"上野都市開発課長、上川内生涯学習課長","answer":"１点目の明電舎の整備の完成時期ですけれども、本年秋頃着工いたしまして、平成１９年の秋の遅い時期に竣工予定というふうになってあります。土曜、日曜と夜間は分かれていなくて、数字はわかりません。","voiceIndex":273,"id":"exchange-109"},{"speaker":"堺委員","kind":"質問・要望","question":"ご存じかと思いますが、蛇窪支線の広町ガード第１とか、第２とか、あるいは国際自動車の先に行きますと大井工場乗り越し線歩道橋というんですか、ここは特に狭いですよね。したがって、歩道の拡幅ですから、当然ここも含めて拡幅してくれるだろうと思うんですが、その辺のところの計画はどのようになっているか。それから広場の利用の件です。その辺も含めてちょっとご見解をお聞かせいただきたいと思います。","respondent":"中島街路事業担当課長、岩田管理工事課長","answer":"１点目の百反坂下から補助２６号線までの間ですけれども、私ども今やっております事業をやる段階では、一括でやりたいということで申し入れたわけですけれども、財源、あるいは緊急性等を勘案して今回の事業になったということで。実は利用制限はかけておりまして、一般の区民の方が利用されるであろう夏休み期間中とか、春休みとか、冬休みは学校優先枠に制限をかけております。","voiceIndex":276,"id":"exchange-110"},{"speaker":"川西委員","kind":"質問・要望","question":"その２つについて質問をいたします。平成１７年度設計委託、そして平成１８年度をもって完成ということになっていますが、平成１６年度分の予算上の設計委託までに至る事務上の段取りについて教えていただきたい。例えば設計委託をする前に区民の声をどう聞くのか、これだけの大きな公園ですから、所管課のほうで全部設計して委託してしまうということはまずないでしょう。","respondent":"岩田管理工事課長","answer":"今回は工事をやるための詳細な設計、すでに決まっております基本設計に基づいて設計をするということになりますので、極めて技術的な問題だということ、ただし、当時下水道局が設置しております下水道ポンプ場の屋上も区がお借りして庭園とする予定だったんですが。","voiceIndex":280,"id":"exchange-111"},{"speaker":"川西委員","kind":"質問・要望","question":"若干基本計画の修正部分もあり得るということですから、私も詳細にもう少し勉強し直しまして、またさらに、どこでどういうふうに影響のない程度に意見が入れられるか、あるいは今開園しております部分についての利用勝手とか、使い勝手、それから、あそこの住民の皆さんの人気とかありますから、そういうものをどこかの時点で申し上げさせていただきたいと思いますので、よろしくお願いします。","respondent":"岩田管理工事課長","answer":"したがいまして、今まで以上に適正な管理を行って、占用している部分については使用料をいただくし、不要になるものについては積極的に売却をしていくということで、現在払い下げのご希望のあるところの方との詰めの作業をしておるところです。","voiceIndex":282,"id":"exchange-112"},{"speaker":"川西委員","kind":"質問・要望","question":"それで、要望があります。そういうものについては、これはしようがないですから、ちゃんと賃料をいただくとか、買い取っていただくとかという方法が必要だと思います。ですから、無償で使っていらっしゃるというわけではありませんが、こういうものも整理しながら、では、残った公共溝渠部分は区がどうするのかということをしっかり平成１６年度に進めていただきたいと思います。","respondent":"岩田管理工事課長","answer":"ですから、将来的には日本ペイントの開発計画と、それから、東京都のほうの中央環状の換気塔の計画等を勘案しながら、どうするかを決めてまいりたいと思います。","voiceIndex":284,"id":"exchange-113"},{"speaker":"川西委員","kind":"質問・要望","question":"日本ペイントは同じ町会なんです。いつもあそこの場所を借りて総会をやっています。大体状況は分かるんですけれども、開発といいますか、危険物の作業部門は東京都の外に出ました。ですから、開発計画がもうほとんど終わりに近いというふうに思いますので、よく調査をしていただきたいと、要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":286,"id":"exchange-114"},{"speaker":"須貝委員","kind":"質問","question":"２９１ページ、建築行政費と、２８２ページ、公園管理費について、質問をします。現在は閉鎖されております。そうすると、１階部分はお店ではなくて、ただの住宅になってしまいます。こういう考え方、本来なら、やはり商店街の中は１階部分に関しては商店を建ててくださいと、そういうふうな規制を立てなければいけないんじゃないかなと思うんですけれども、その辺についてご見解をお聞かせください。","respondent":"浜脇住環境整備課長","answer":"そういった意味では、あの頃ちゃんと私どもがやっておれば、そういった商店街の支援が検討できたのかなと考えています。そういった意味では残念だと思いますけれども、現実的にはこういうふうになっているというのが実情です。","voiceIndex":288,"id":"exchange-115"},{"speaker":"須貝委員","kind":"質問","question":"まちづくり事業部としてもちょっとお聞きしたいんですけれども、今までそういうふうに助成して、装飾灯を整備をしてきて、商店街づくり、まちづくりをしてきたわけですね。でも、区の施策として、片一方は商店街を応援してきて、今までいろいろ助成してきたのにもかかわらず、こういうふうに建っていってしまうということに対しまして、まちづくり事業部の見解をお聞かせください。","respondent":"中谷まちづくり事業部長","answer":"産業振興課のほうと十分連携を図りながら進めていきたい、このように考えております。","voiceIndex":290,"id":"exchange-116"},{"speaker":"須貝委員","kind":"質問・要望","question":"今後とも地域ということ、まちづくりということを念頭に入れましてやっていただきたいと思います。運動会は年に３回か４回という話を聞いております。そういうことを考えておかないと、後でけがをした、捻挫した、何か事故があったら、それこそせっかく立派な多目的広場をつくっておいて、かえって汚点が残るのではないかなというふうに私は思うんですけれども、ご見解をお聞かせください。","respondent":"岩田管理工事課長","answer":"今のトラックの部分はゴム系の舗装になっておりますので、そこがきちっと段差のないように、つっかかったりなんかしないような形で設計をするようにしてまいりたいと思います。","voiceIndex":292,"id":"exchange-117"},{"speaker":"須貝委員","kind":"意見","question":"現在も段差はないんですね。だけど、走っていて突然クッションが変わるというのは、スポーツをやっている身になると大変なんです。急にそこで感覚が違ってきてしまうんです。膝にもよくないし、捻挫もしやすいんです。これは我々はスポーツをやっているので、一番身にしみて感じているところなんです。今のままだったら、必ずけが人が出てくると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":294,"id":"exchange-118"},{"speaker":"松澤委員","kind":"質問","question":"２９１ページ、６款土木費、５項建築費、１目建築行政費、何人かの委員から質疑がありましたけれども、建築紛争に関連して質問をしたいと思います。","respondent":"中谷まちづくり事業部長","answer":"そういう意味では、それを進めていく上では、まずは法律に基づく、あるいは条例を設けて、各施策を整合性をとりながら進めるですが、これらまちづくりを進めていく上で、条例ではなかなか補完できないもの、これらで地域に対して、あるいは事業主に対して協力をお願いする。","voiceIndex":296,"id":"exchange-119"},{"speaker":"松澤委員","kind":"質問","question":"ただ、これは今の建築基準の改正前ですから、斜線制限、道路斜線があるんですよ、あるいは北側斜線があるんですよ、２０ｍを超える高い建物は隣地との斜線もあるんですよという中で、制限があるので、大きな敷地がないと建てられない。大変に働いてきたんですけれども、例えばこれが平成１５年１月１日施行の建築基準法の一部改正によって斜線制限がなくなったんですね。天空率という概念が出てきました。","respondent":"片田建築課長","answer":"ただ、一定程度道路斜線と同様の空地あるいは空間がみなせるという中で、いろいろなメニューを設けた中で、まちづくりの一つの支援としてつくってきたということで認識しております。","voiceIndex":298,"id":"exchange-120"},{"speaker":"松澤委員","kind":"質問・要望","question":"今話題になりました戸越銀座の話、最初は１４階という話だったんです。そうしますと、確認申請を出します、事前協議をしたときに、ワンルームマンションを全部建てるんだ。建築確認法の中で一番厳しいのが消防法なんですね。斜線があったから、そんな小さい建物ができなかったんですから。建築確認も通っているから合法になります。今の話に間違いがありましたら訂正していただきたいんです。","respondent":"片田建築課長","answer":"その中で地域にあったということで、ほかの都道府県とは別に東京都独自で条例を定めまして、安全上の基準を別途設けているといったようなことです。","voiceIndex":300,"id":"exchange-121"},{"speaker":"松澤委員","kind":"質問","question":"違反も何もしていないわけですから、合法的です。どうすればいいと思いますか。前の質問の話を聞きましたらば、品川都市白書をつくってからやりますなどという話をしているけれども、すぐやらなくてはできない。建築基準法は坪数を書いてないものですから、ちょうど４０坪がここに当たるかなというのでちょっと数字を出しましたけれども、指導要綱、あるいは指導指針、すぐ変える気持ちがおありでしょうか。","respondent":"浜脇住環境整備課長","answer":"ですけれども、ほかの１４項目については、この土地においてもちゃんとやっていただいて、それなりの住環境整備、緑や歩道空地、管理人室、そういったものもつくっているわけですので、飛ばしの駐車場になってしまったから、すべての要綱なり。","voiceIndex":302,"id":"exchange-122"},{"speaker":"松澤委員","kind":"質問・要望","question":"法律が改正になって、できたばかりですから、どこの区でもいろいろな問題があるんでしょう。先ほどうちの政調会長も質問をしましたけれども、２３区もどんどん改正している。「区都市計画部指導課、法的義務はないが、厳しい姿勢を打ち出すことで、業者にも、ハード面にもきちんと設置を促したい」、やはり指導要綱、指導指針を泣かさないように十分に話し合いをしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":304,"id":"exchange-123"},{"speaker":"高星委員","kind":"質問・要望","question":"いろいろとスケジュールがあるものですから、できるだけ時間を短く残してやめたいというふうに思っていますので、端的にお聞きしますので、端的に明快なご回答をお願いいたします。そこでお聞きします。例えば品川区内全部の五署でやられているのか、あるいは都道が対象なのか、区道も含むのか、あるいは青空駐車についてはどうなのかということをちょっとお聞かせいただきたいと思います。","respondent":"市岡企画財政課長、矢部下水道河川課長、奈良交通安全担当課長、藤田都市計画課長","answer":"区の保有している公共施設、あるいは区有財産の管理、活用のビジョンということだと思いますが、それぞれ各事業部。説明会だけでも５回開いて工事を進めております。その中で施工時間帯について皆さんの要望をいろいろ聞きながら、苦心をしながらやっております。青空駐車の関係につきましては、国道、都道、区道に関係なく、昼間であれば、１２時間、夜間であれば８時間以上止まっている車両については。中央環状線の関係の意見等ですけれども、平成１５年１２月１２日から１月１３日まで縦覧を行いまして。","voiceIndex":306,"id":"exchange-124"},{"speaker":"高星委員","kind":"質問・要望","question":"これは間違いなくなると思います。こういうことでありますので、これは品川区が実施母体でないですから、何とも言えないけれども、しかるべきところに大きな声を上げていっていただきたいというふうに思います。私が言いたいのは。結果として、新しくできたマンションの１階部分のかなりの平米数を保育園の一部として区が受け取ったじゃないですか。これについてはお考えをお聞かせいただきたいと思います。","respondent":"本間総務部長、奈良交通安全担当課長","answer":"今後もこういうことで対応をしていきたい、かよう考えているところです。鍵付の路線の指定ですけれども、これは確かに警視庁管轄、全部やっているわけではございませんけれども、各地域に応じて緊急的な部分のあるところについては優先的に鍵付の指定路線をしておりますけれども、これは警視庁の方針としては。","voiceIndex":311,"id":"exchange-125"},{"speaker":"高星委員","kind":"質問・要望","question":"１４階建てのマンションの建築が始まって、今日あたりから根切り工事に入っているんですね。ですから、もう間もなく日照ゼロになってしまう。だから、幹部の皆さんがそういうフォローをしっかりと考えていただいて、しかるべき首脳部会議等々でもできることならやっていただきたいなというふうに、これは要望したいと思います。何か苦労話がありましたら、一言いただいて、私の質問を終わりたいと思います。","respondent":"奈良交通安全担当課長","answer":"議会の皆さん方も、いろいろな話の中で、こういった委員会を通じても、地域住民のことをよく考えているのはさすがだなということで、つくづく思って、区議会の議員方も本当によく地域住民に目を向けて仕事をしているんだなということをつくづく今感じているところです。","voiceIndex":314,"id":"exchange-126"},{"speaker":"沢田委員","kind":"確認","question":"地元の地域の要求の問題を取り上げたいと思っていたんですが、今高星委員の質問がありましたので、若干関連して建築費の問題でお尋ねしたいと思います。建築基準法で合法だと言われて、建築確認がおりても、実際に保育園があったり、公的なものがあったり、住宅が１日丸々日影になってしまった場合には、調整をするということで、品川区の中高層棟の紛争予防条例があるわけです。","respondent":"岩田管理工事課長","answer":"したがって、受忍限度を越えるような騒音、振動、影響を与えない範囲で工事を行うし、設計も行う。これが公共工事です。","voiceIndex":317,"id":"exchange-127"},{"speaker":"沢田委員","kind":"質問","question":"私は、そういう点では、この間代表質問で言いましたけれども、寝たきりの夫を抱えて、自分がここに将来夫の介護をしながら看取りたいと言って、自分の１階を改造しただけではなく、２階も子どもが入って騒がしくならないように、３階をヘルパーのために宿泊できる施設をと三つもマンションを買って、その方が、１階、２階、３階と、７時間の日影を受けるというのは。","respondent":"上野都市開発課長","answer":"五反田駅の改修工事関連のご質問ですけれども、先般ＪＲ東日本が五反田駅改修計画なるものを地元の代表者の方に説明したいということで、私どもに事前相談があったという内容を、３月２日の建設委員会でご説明をしたところです。","voiceIndex":321,"id":"exchange-128"},{"speaker":"沢田委員","kind":"提案","question":"約５億円かかるという話を聞いたんですけれども、そこまで具体的に話し合いの中で答えているんですけれども、先ほど何か、まだ進んでいないようだということなので、もう少し詳しく教えていただきたい。横断歩道橋があるけれども、横断歩道橋はお年寄りの人たちはちょっと無理だと思うんです。具体的な問題を一つ提案したいと思うんですが、たくさんの施設が次々と出てくる。旧正田邸の公園もそうですね。","respondent":"上野都市開発課長、市岡企画財政課長","answer":"私から、１点目と２点目についてお答えいたします。五反田駅周辺につきましては、今回まちのサインの書き替えということで、東口、西口それぞれ書き替えを行うものです。","voiceIndex":323,"id":"exchange-129"},{"speaker":"沢田委員","kind":"提案","question":"改めて、今日言って明日ということではないんですけれども、ぜひ提案の趣旨を汲んでいただいて、取り組んでいただければと思います。２点目は、昨年の決算特別委員会でもあったんですが、品川駅の東口の開発に伴った八ツ山公園通りの中ほどに横断歩道をつくってほしいという声が地元の町会からも出ているんですけれども、この問題はその後どうなったか、経過を教えていただければと思います。","respondent":"奈良交通安全担当課長","answer":"今委員ご指摘の八ツ山公園通りについて、いわゆる横断歩道を設置してもらいたいというお話については、いろいろな形でご要望が多いところですけれども、この件につきましては、警察のほうの見解が平成１９年度にアンダーパスが開通をしますので、その際の交通量の流れとか。","voiceIndex":326,"id":"exchange-130"},{"speaker":"沢田委員","kind":"質問・要望","question":"ある意味でこれは非常に危険です。そこで、再度お尋ねしたいんですけれども、警察のほうに行って、４月の信号を付けた際の交通量などを判断して結論を出したいというふうにも言っておりますので、もう一段言って働きかけていただきたいということと、アンダーパスができれば、相当な交通量が増えて、２３０ｍの間に三つも信号ができたら危ないからというんだけれども、これは交通を優先した考え方ですね。","respondent":"奈良交通安全担当課長","answer":"横断歩道の件につきましては、４月以降に信号がついた段階で考えるというお話については、委員のご指摘を踏まえて警察のほうには要望をしてまいりたいと思います。","voiceIndex":328,"id":"exchange-131"},{"speaker":"沢田委員","kind":"質問・要望","question":"私はあの道路をああした形態にするときに、インターシテイなどに通って働いている人や、近所の町会の人や、都営住宅に住んでいる人に、こういうまち、こういう構造の道路にしたいけれどもどうかという話があれば、まだ納得できるんでしょうけれども、皆さんは納得していないんですね。ですから、その点で後追いになりますけれども、区としてできるだけのことはやっていただきたい、このように思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":330,"id":"exchange-132"},{"speaker":"三上委員","kind":"提案","question":"目黒線の不動前駅について、駅の整備というのはでき上がって、これから高架下の利用について、歩道の設置とか、いろいろ工事をやっておるわけですけれども、話を聞き及ぶのには、高架下に東急ストアができてくる、こういうことで、ここの東急ストアと駐輪場との間に荷捌き場のような形のものを取り付けるというような計画であるのかわかりませんけれども、東急ストアに来る客のことを考えたら。","respondent":"矢部下水道河川課長、中島街路事業担当課長、田村住宅課長","answer":"そういうことで、まちづくり事業部の中で検討をします。確かに、先ほど委員も言われておりましたように、ここにそういったストアができますと、当然車の交通量が増えるだろうというふうに認識してございまして。小山台民生住宅ですが、昭和３３年に建設しまして、戸数が５４棟ということで、閉鎖住宅というのはお聞きしていますが、現在閉鎖して。","voiceIndex":332,"id":"exchange-133"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、そこらあたり、まちづくり事業部全体として、それはしっかりと取り組んでいただきたいと思います。それから、目黒線の不動前駅については、Ｕターンできるというふうに、最初からつくっておいていただきたい。ですから、一旦山手通りから入ってきたら、完全に商店街を通らなければ出ていけないという状況になるわけですから、そこの仕組みについては、最初の段階でやっていただきたい。","respondent":"田村住宅課長","answer":"今、三上委員のほうからご指摘がありましたので、都営住宅ではありますが、そういう現況があるということでしたら、私どものほうから住宅局の所管のほうに伝えて、早急に対応するなり、調査してもらうというふうに考えております。","voiceIndex":336,"id":"exchange-134"},{"speaker":"三上委員","kind":"意見","question":"最後に、近隣住民の方も大変心配しておりますので、そういった意味にあってはぜひ早急に東京都のほうと話し合いを進めていっていただければと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":338,"id":"exchange-135"},{"speaker":"伊藤委員","kind":"質問","question":"地元の議員として質問をします。端的に２点質問をします。ですから、そういうようなことを考えていきますと、りんかい線のどこ行きが何時出発するという掲示板、これが実は入口から３分経たないと見えない状況にあるわけです。ですから、エスカレーターの途中でもいいから、例えばどこ行きが何時に出るとか、電光掲示板を付けたらいかがでしょうかということをお伺いしたい。その二つを答弁お願いいたします。","respondent":"奈良交通安全担当課長、藤田都市計画課長","answer":"ただ、その後にまたあそこに二、三人たむろといいますか、住み込んでいるといいますか、そういったホームレスがいるのは承知しておりますので、区と警察で連携を図りながら。私もとりあえず走っていっておこうかなというのが、毎回思っているところです。そういったこともありますので、改めまして、りんかい線のほうにはそういった要望があるということを伝えてまいりたいというふうに考えてあります。","voiceIndex":340,"id":"exchange-136"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、ぜひお願いしたいのは、追いかけて我々が指摘をして、初めて今答弁をいただきましたけれども、やっていくところではなくて、それぞれの部署の中で、こういうような仕事一つに対しても責任を持ってやっていただきたいということをお願いすると同時に、改めて大井水神公園に対するホームレスの皆さんに対する対処の仕方をもう一つはっきりした答弁をお願いしたい。それが一つ。","respondent":"松代道路公園課長","answer":"私ども数年前から大井水神公園のホームレスに全力を上げて対応してまいりました。今ご指摘を受けたような点、反省をしまして、先ほど申しましたように、連携を図って、再度適正な管理をするように努めてまいります。","voiceIndex":343,"id":"exchange-137"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=830#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":113578,"voices":345}},{"id":"h16-20040315-3","meetingId":"h16-c-budget","date":"2004年3月15日","dateIso":"2004-03-15","committee":"予算特別委員会","time":"午前１０時０4分～午後６時１６分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を179件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１６年度品川区一般会計予算","agenda":"平成１６年度品川区一般会計予算","exchanges":[{"speaker":"大沢委員","kind":"意見","question":"おはようあります。私は、３２０ページ、生涯学習費のうち、次のページ３２１ページのＰＴＡ活動支援事業について、お尋ねをします。","respondent":"上川内生涯学習課長","answer":"それで、保護者と学校側だけではなくて、地域の青少年委員とか、民生・児童委員、あらゆる子どもたちを取り巻く地域の方たちを含めた協議会、実際は情報交換、それからテーマを決めて、こういうことには具体的にどう対応したらいいか。","voiceIndex":4,"id":"exchange-001"},{"speaker":"大沢委員","kind":"意見","question":"平成２年度ということで、その当時の学校が荒れていたということで、協議会が設立されたということで理解をしますが、今、おっしゃいました構成メンバーのうち、ＰＴＡの方、地域の方、民生委員、児童委員ということで、そこのところをちょっと、地域でどの程度の職責といいますか、ボランティアでされている方を具体的に網羅なくお答え願えればと思います。","respondent":"上川内生涯学習課長","answer":"各学校に応じて、地域の実情に応じて、その学校で情報交換が必要な方たちを個別に選定しております。基本的には、子どもたちを取り巻く団体の代表者、それから、民生委員、町会長が入るところもありますし、各校独自で行っております。","voiceIndex":6,"id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"各校独自で行っているということで、それは学校によって多少ばらつきがあるということでしょうか。","respondent":"上川内生涯学習課長","answer":"ばらつきがあるというよりも、その学校と親御さんたちが必要だと思う方をメンバーに選んでいるです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"ＰＴＡの独自性ということで、私たちがどうのこうのという問題ではないんですが、地域にとっては不必要なものはないと思うんですが、そこら辺のご見解が、ボランティアで民生委員、児童委員、そして、町会長たちがいらっしゃるわけですけれども、その辺はＰＴＡの方たちが選んで、お声かけをして話し合いをしているということでよろしゅうありますでしょうか。","respondent":"上川内生涯学習課長","answer":"おっしゃるとおりです。","voiceIndex":10,"id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"そうしますと、１８校独自ということなので、平成１４年度なんですが、１８の中学校で４８回の健全育成運営協議会が開かれておりますけれども、これは横並びで、単純に４９割る１８という理解でよろしいんでしょうか。","respondent":"上川内生涯学習課長","answer":"こちらのほうとしましては、地域の方々と、子どもたちのまちの中の状況、学校の状況等を情報交換していただくという趣旨で、春休み、夏休み、冬休みの前に３回程度をお願いしているものですが、現実に２回から３回、３回が圧倒的に多うあります。","voiceIndex":12,"id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"時期的なものは、春休み、夏休み前に随時開かれるという理解をさせていただいてよろしいでしょうか。","respondent":"上川内生涯学習課長","answer":"あくまで、ＰＴＡは自主的な団体ですので、私たちのほうで３回という枠を決めたのは、休み前ですが、その学校の実態によりまして多少ずれることもあろうかと思います。","voiceIndex":14,"id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"ＰＴＡが自主的にということですけれども、せっかく地域の方に時間を割いていただいて、協議会を皆さんで活発な情報交換をしていただいているわけですけれども、それについて、行政のほうから、何か意見の集約とか、取りまとめとかというのは、１８校の横のつながりでなされているのでしょうか。","respondent":"上川内生涯学習課長","answer":"また当課のほうのＰＴＡ支援事業の一つですが、ＰＴＡのほうでは研修会を設けておりまして、その中で、幹部研修会、専門部研修会等、かなり研修会を行っております。その中で、情報交換等をしております。","voiceIndex":16,"id":"exchange-007"},{"speaker":"大沢委員","kind":"意見","question":"各中学校のＰＴＡの独自性というか、自主的な協議会ということで、理解をさせていただいたのと、区のほうでその集約といいますか、横のつながりで、各協議会に出た話を吸い上げているということで理解をします。それについてですけれども、地域健全育成運営協議会というものを、生涯学習という見地から見た場合、どのような意義を持ち合わせるものか、ご見解をお願いしたいと思います。","respondent":"上川内生涯学習課長","answer":"地域健全育成運営協議会というものでございまして、青少年の健全育成に、生涯学習課としては、家庭教育の支援事業というものもありますし、青少年の健全育成という課題もあります。その観点から、生涯学習課のほうで管轄しているものです。","voiceIndex":18,"id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"生涯学習という観点から、もう一つお伺いをしたいんですけれども、広くＰＴＡの方が地域の方をリストアップをして、お呼びしていると。それについて、もちろん話ができるような常識的な人数だとは思うんですが、人数のおよその目安みたいなものはあるんでしょうか。","respondent":"上川内生涯学習課長","answer":"特にこちらのほうからお願いしているものではございませんが、情報交換が細かくできる範囲の中で、各ＰＴＡは実施しているものです。","voiceIndex":20,"id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"現状は、話ができる範囲内ということなんですが、地域健全育成運営協議会に、生徒の参加している学校といいますか、生徒を協議会に参加させているような学校ってあるんでしょうか。","respondent":"上川内生涯学習課長","answer":"保護者のほうとしましては、校区の役員等、地域としましては、町会長、自治会長、あと、先ほど言いました青少年委員とか、地区委員、体育指導委員等々ですが、生徒につきましては、協議会の中で生徒会長から話を聞いたりしたということもあったと認識しております。","voiceIndex":22,"id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"したがいまして、地域のＰＴＡが選んだ参加はあるんですが、子どもたちの参加もこれから視野に入れながら、行政の側でも、地域健全育成運営協議会についてのご指導をお願いしたいと思いますけれども、そのような形をお考えの中に入れていただけるかどうか。はっきりは難しいですけれども、最後に方向性だけお伺いしたいと思います。","respondent":"古川教育次長","answer":"最終的な今後の方向性の中には、当然当事者である生徒の視点から、さまざまな課題に対する提議、またそれに対して大人と一体となった解決、こういうこともこれから大事なことだろうと思ってありますので、やり方等についてはＰＴＡのほうに委託していますけれども。","voiceIndex":26,"id":"exchange-011"},{"speaker":"大沢委員","kind":"質問","question":"あらゆる方面からの構成員ということで、上辺だけの話ではなくて、より突っ込んだ話がこの協議会でされることを、またできるようにご指導していただくことをお願いいたしまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問","question":"３２１ページのシルバー大学、それから、３２３ページの総合体育館、２点、お聞きしたいと思います。総合体育館のほうです。昨年、たしか申込み方法が充実をしたといいますか、変更された部分があります。それについて、それまでの申込み状況、それから、ここまでの申込み状況、数とか、団体であるとか、何か変化があればお知らせを願います。","respondent":"梶教育委員会事務局副参事","answer":"応募状況のほうですけれども、体育館のほうは、まず、インターネットで登録する団体は、１カ月に関して１０の時間帯、あるいは日にちまで申込みができますので、そういう意味では、非常に使いやすくなったとは思うんですけれども、それにつきまして。","voiceIndex":30,"id":"exchange-013"},{"speaker":"若林委員","kind":"質問","question":"そうしますと、取り立てて変化はないということで、お伺いをいたしました。そういう中で、４種類の登録団体以下障害者の団体まで、例えば、各団体がかち合った場合とか、どういう抽選方法になるのか。優先順位をつける考え方とか、また平等にしていくのか、その辺の考え方をお知らせ願います。","respondent":"梶教育委員会事務局副参事","answer":"その場合については、４カ月前の抽選には参加できない。ただし、４カ月前に申込みしてから、その次に、抽選をいたします。","voiceIndex":32,"id":"exchange-014"},{"speaker":"若林委員","kind":"意見","question":"個別の事例で大変恐縮ですが、ある社会教育団体で登録されている、大体８割方障害を持っている団体があるそうです。先ほどのご説明ですと、特に件数とか、またキャンセルも含めて特段の変化はないという中で、新規の方がどんどん入ってくださるのは大変にありがたいんですが、そういう変化がない中で、こういう事態を把握していらっしゃるかどうか、ちょっとお知らせ願います。","respondent":"上川内生涯学習課長","answer":"まだ実施してから１年余り程度なので、抽選は公平にやっておりますので、利用しやすくなったために、申込みも早くなったり、増えたりしているという状況もありますので、よろしくお願いします。","voiceIndex":34,"id":"exchange-015"},{"speaker":"若林委員","kind":"確認","question":"そこら辺の申込み方法とかを、周知徹底をお願いするとともに、どうしても、普通考えますと、インターネットで申込みが可能になりますと、使いたい時間帯、曜日とかが毎週大体決まってくるわけですね。今までずっと毎週使っていたものが、例えば２カ月、３カ月全然当たらないというのはいかがかなと思いましたので、私もそこら辺を確認しながら、また公平さを保ちながら、ご相談したいと思います。","respondent":"上川内生涯学習課長","answer":"それが過ぎると、今度は趣味のうるおい塾というものを実施しておりまして、今まで、個人のキャリアを磨いていただくということに重点を置いておりましたが、今は元気な方たちも多くなっておりますので、それを地域に生かしたいという声もあります。","voiceIndex":36,"id":"exchange-016"},{"speaker":"若林委員","kind":"質問","question":"内容が、いろいろプログラム等豊富なようで、大変に好評を博していると伺っております。区のほうとして、受講者からの評価、そこら辺、どのようなお声が届いておりますでしょうか。","respondent":"上川内生涯学習課長","answer":"皆様、必ず入学式がありまして、卒業式等あります。そういう中で、自分が専門的に進んだ成果発表等をしておりまして、今まで会社人間だった男性もシルバー大学に入ることによってお友達が増えたと伺っておりますので、生き生きとした活動をなさっております。","voiceIndex":38,"id":"exchange-017"},{"speaker":"若林委員","kind":"意見","question":"ぜひ、このシルバー大学、今後ともさらなる充実をお願いしたいと思いますが、今、入学式と卒業式という言い方がございました。多分、卒業式は修了式のことだと思いますが、どのような枠でここに参加されるのか、お知らせ願います。","respondent":"上川内生涯学習課長","answer":"その後、成果発表をパーティ形式でやるんですが、その中には、ＯＢの方、それからさまざまなボランティアとしてご援助いただいた方等を含めまして実施しております。ちなみに、入学式は４００名、修了式は３６０名の参加が、近年ではございました。","voiceIndex":40,"id":"exchange-018"},{"speaker":"若林委員","kind":"質問","question":"今の入学式では４００名、修了式では３６０名の参加ということでございました。いろいろなチラシを見ておりますと、特に修了式のほうですが、ただの修了式ではなくて、修了パーティを兼ねてです。ここら辺の意味と、４００名の入学に対して、修了式に参加される方がなぜ４００名でないのか、これをお聞きいたします。","respondent":"上川内生涯学習課長","answer":"修了式は全部式典ではなくて、全体のパーティ等も含めたものですので、講師の方とか、リーダーの方とかも入ります。それから、入学式につきましても、これから決まっている講師の方等の数字も入りますので、イコールシルバー大学生という数字ではございません。","voiceIndex":42,"id":"exchange-019"},{"speaker":"若林委員","kind":"質問","question":"わかりました。対象が若干違うということですね。修了式、修了パーティに、会費という言い方でいいのでしょうか、それを納めて参加する。普通、修了式といいますと、入学式で一緒になった方が、受講を終わって全員そろってということなんですが、会費があるために出られないという方もいらっしゃいます。ここら辺の、これからの対応をお願いしたいと思うんですが、お答えください。","respondent":"上川内生涯学習課長","answer":"会費というのはパーティの飲食代でございまして、式典には皆様出られますが、式典とパーティとは時間と会場を別にしております。パーティの中にはＯＢの方の参加もありますので、飲食のパーティですので、その実費の部分を実行委員会の中で賄っております。","voiceIndex":44,"id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"私は、青少年教育、そして地域スポーツの支援という角度から、スケートボードの施設をぜひ設置していただきたいということでお伺いをいたしたいと思います。その後、どういう検討をされてきているのかを、ちょっと伺いたいと思うんです。インターネットで見てみると、ほんとうに全国的に広がっているという実態があります。そういう点で、ぜひ、その辺の検討状況について伺いたいと思います。","respondent":"上川内生涯学習課長","answer":"それで、品川区の中で、野球場とか、サッカー場が足りないといっている状況を鑑みますと、スケートボードにつきましては、まだまだ危険性が伴うものでもありますし、要請が具体的にありましたら考慮していきたい。","voiceIndex":47,"id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"今、子どもたちの問題というのは、私たち大人の側は一面的に見がちなところがありますけれども、しかし、主体的にいろいろ考えさせていくことが、この時代、ほんとうに大事だし、先ほど、大沢委員のご質問で、教育次長の答弁では、当事者の立場が大事だとおっしゃってくださって、ほんとうに心強いなと思ったので、ぜひ、スケートボードの問題でも。","respondent":"岩田管理工事課長","answer":"したがって、臨海部のほうの、住宅からかなり離れて騒音の問題がないようなところで何とかならないかということで、私どものほうでも検討しております。","voiceIndex":49,"id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"そういう作業することが、子どもが社会に出ていく上でも、やっぱり必要な、超えなければいけないものだし、大人の社会のほうも、子どもたちを受け入れていくという角度から見るのがやっぱり大事だと思うので、中央海浜公園でやっていただくこと、そのことは否定しないし、進めていただきたいんですが、騒音があるからということで、内陸部じゃだめだとなると。","respondent":"古川教育次長","answer":"スケートボードに限らず、いわゆる青少年、特に中高校生の居場所という中でも、スポーツの環境づくりは大変重要な問題だと思ってありますので、これは一般論になりますけれども、さまざまなニュースポーツに対する場の整備につきましては。","voiceIndex":51,"id":"exchange-023"},{"speaker":"木下委員","kind":"質問","question":"おはようあります。この間の決算特別委員会で、英語学習を大体何校ぐらいでやっていらっしゃいますかとお聞きしましたら、大体半分ぐらいの学校が１年生から教えていると聞いたんです。やっぱり全小学校で教えるべきじゃないかということでお願いしておりましたら、一応導入するようなお話を聞いたんですけれども、１年生から英語学習を導入する方向性が決まったのか、どうなのか、お答え願いますでしょうか。","respondent":"中島指導課長","answer":"品川区では、プラン２１推進の中で、小学校における英語学習を推進していますけれども、今後、小中一貫校の全区展開に伴いまして、小中一貫校でも、現在、取り入れております１年生からの英語学習を全校的に展開していきたいと考えています。","voiceIndex":54,"id":"exchange-024"},{"speaker":"木下委員","kind":"質問","question":"ということは、小学校全校で導入するという理解でよろしいんでしょうか。","respondent":"中島指導課長","answer":"そのとおりです。","voiceIndex":56,"id":"exchange-025"},{"speaker":"木下委員","kind":"質問","question":"ちょっとお聞きしたいんですが、小学校における英語学習で、５、６年生とそれ以外の学年の子どもたちの英語学習というのは、国際理解教育のほうに当てはまるという理解でよろしいんでしょうか。","respondent":"中島指導課長","answer":"したがいまして、今後、展開されていく小学校におきましても、こういったコミュニケーションを中心とした形での単元として実施していくという形から、英語学習という一本化したものにしていくというような方向性を考えてあります。","voiceIndex":58,"id":"exchange-026"},{"speaker":"木下委員","kind":"質問","question":"ほんとうにありがとうあります。国際を理解するのに、英語だけじゃなしに、日本はアジアの一員ですし、これからアメリカとの貿易以上に、中国との貿易ですとか、アジア全体で言えば、もっと貿易力も増えていくわけですから、１０年後、２０年後をにらんだ形で、そういうのを導入するのもいいんじゃないかなと思うんですが、そこら辺の考え方としてはいかがでしょうか。","respondent":"中島指導課長","answer":"多様な国々と多様な交流をしていくというのが、国際理解教育におきましては大変重要な視点だろうと思いますので、今後の各学校の取り組み、また、英語学習を推進していく中での発展という部分で、私どもの課題ととらえさせていただければと考えています。","voiceIndex":60,"id":"exchange-027"},{"speaker":"木下委員","kind":"質問","question":"実際に品川区として、教頭先生になりたがっている方とか、傾向としてはどういう傾向がありますでしょうか。","respondent":"中島指導課長","answer":"教員の筆頭というような意味合いの教頭から、副の校長という形で、今後の権限移譲に伴いまして、さまざまな学校の運営、経営という部分に大きくかかわっていく職務であろうと考えていますので、教員のそういった管理職選考、また。","voiceIndex":64,"id":"exchange-028"},{"speaker":"木下委員","kind":"意見","question":"そのものずばり、教頭というのは教師の頭と書きますから、教員のリーダー的な役割を果していらっしゃるかと思います。もし副校長になった場合に、教頭先生からどういう部分の権限が増えるのか、代表的なものをお教えいただけばと思います。","respondent":"中島指導課長","answer":"こちらにつきましては、先ほどもちょっとご答弁させていただきましたけれども、現在、東京都のほうで具体的な事案決定につきまして協議をしている状況でございまして、またそういった情報を踏まえながら、私どもも検討をしていきたいと考えています。","voiceIndex":66,"id":"exchange-029"},{"speaker":"木下委員","kind":"質問","question":"検討段階ということで、なかなか答えられないということはあるかと思います。ほんとうに、教頭先生は地域社会の行事等ですとか、先頭を切ってやっていらっしゃいますので、教頭先生がやりがいがあるような形で、いろいろな面、ご検討をいただければと思います。ということで、お願いいたしまして、私の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私からは、２項の学校教育費の中で、３０７ページ、プラン２１関連事業関係、それから、３０９ページ、学校運営費関係で、ちょっと質問をさせていただきたいと思います。前回、決算特別委員会だか予算特別委員会だか忘れたんですが、学校研究発表会の件で、ちょっとお聞きしたいと思っています。総合的学習の中で、中学生が発表をしている。その２点、お答えをいただきたいと思います。","respondent":"中島指導課長、谷田部学務課長","answer":"具体的に何か一つ、道路上の対応が必要だというような部分、細かいところにつきましては、一つ一つを教育委員会で対応しているというわけではございませんけれども、それぞれの学校の中で。小中学校、幼稚園の維持管理費経費の中の光熱水費ですけれども、学務課予算の中に計上いたしまして、学務課が直接支払いをするという仕組みになってあります。","voiceIndex":70,"id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問","question":"概算なので、大きい額、小さい額ばらばらですから何とも言えないんですけれども、平均だと１,２００万円です。月１００万円かかったものが、今月は８０万円になりましたよ、９０万円になりましたよというのが具体的に生徒に見えれば、もっと協力できるんじゃないかなと思うんですけれども、その辺については、お考えはいかがでしょうか。","respondent":"中島指導課長","answer":"そういった部分につきましては、私ども、また地域が手を携えて、その環境をよくしていく方向に取り組んでいくことが大変重要と考えています。これからも、またそういった情報収集にも努めてまいりたいと考えております。","voiceIndex":73,"id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問","question":"内容がわかりました。学校の中で、当初予算と比べて、例えば年間で１０万円、２０万円浮いたと、その分は学校の努力として認めてあげて、例えば学校の図書を買うとか、そういったものを考えてあげることができないのかという、そっちの思いです。予算上とか、法的な縛りとか問題があるかもしれませんが、そこら辺のお考えを教えてください。","respondent":"谷田部学務課長","answer":"今は、維持管理費という品目の中でのお話ですけれども、私ども、プラン２１を進めるに当たりまして、学習環境の整備、それから、特色ある活動に対しまして、計上予算のほかにプラン２１関連予算という形で、各学校の取り組み、計画に対して、その取り組みの内容、熱意に対して。","voiceIndex":79,"id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"質問","question":"予算配分じゃなくて、結果として、それだけ努力した学校。プールの水１回取りかえ分が２０万円という、それをやるのがいいのか悪いのかは別で、プールの水ですから、衛生上やらなければいけない問題だと思うんですけれども、ほかの部分で、例えば節電したことによって幾らかでも減ってきた、そういったものを使うことができないか。その辺がどうなのかなと思うんですけれども。","respondent":"市岡企画財政課長","answer":"これは学校に限らず、現在、予算編成については、事業部編成枠方針をとっておりまして、施設の維持管理経費の節減を、新しい事業、その他、政策的な経費に振り向けるという趣旨がありますので、この趣旨と共通の考え方で。","voiceIndex":81,"id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"というのは、もう一つ、当初予算の段階で、ヒヤリングをなさったときに、学校で今、特色を出している、その予算と、要するに費用対効果と言ったら、学校ですからちょっと表現は悪いかもしれないけれども、校長先生、学校の思いが伝わった部分というのは結果が出ているんじゃないかと思うんですが、その辺はどうでしょうか。","respondent":"中島指導課長","answer":"学校では，それに応じた形で、この年度末におきまして、最終的に十分な成果を出していただいていると伺っております。","voiceIndex":83,"id":"exchange-035"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"やっぱり、校長先生、皆さん一生懸命やっている部分は評価していただきたいと思います。もう１点、外部評価者制度です。それから、２年経って、成果と今後の課題という点では、どのようにお考えでしょうか。","respondent":"中島指導課長","answer":"しかしながら、学校を見ていくという視点からは、内部評価の基準といったものはありますので、そういったものもまた手がかりにしながら、今後、外部評価の精度を高めていくために、この制度のあり方を、来年度、見直していきたいと考えています。","voiceIndex":85,"id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"学校の内部の評価という点と、外部の評価の基準、各々あると思うんですけれども、なぜこういう質問をするかというと、昨年、議会の議決をいただきまして、海外調査団に参加させていただきました。要するに学校がいかにあるべきか、そういったものがかなり強く出てきている。外部評価者制度を変えるということも、お話があったんで、その辺もちょっと、最後にいただきたいと思います。","respondent":"中島指導課長","answer":"もちろん、教員のほうは、外部評価者制度と同じ視点でも評価をしておりますので、それが内部評価の部分とも整合性を保たれて、より客観性が持てるように、今後、検討してまいりたいと考えています。","voiceIndex":87,"id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"私のほうから、３０１ページのプラン２１関連事業の中の小中連携、それから小・中一貫教育、教科担任制、学力定着度調査、時間があれば習熟度別学習もろもろ、時間の許す限り、お願いしたいと思います。もしも時間がなければ、別途個別にお聞きしたいと思います。小・中連携教育というのと、小・中一貫教育というのがあるんですが、この違いはどんなふうにとらえていかれるんでしょうか。","respondent":"中島指導課長","answer":"この小・中連携教育ですけれども、基本的には、小・中連携教育の実践がプラン２１で推進されてきている中で、より接続を滑らかにしていこうという形で考えたのが、小・中一貫教育というような視点でとらえていただければと思ってあります。","voiceIndex":90,"id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"そうすると、今後、小・中一貫教育を進めていくという上では、予算のほうも、連携教育から一貫教育のほうに移行し、連携というところはなくなってくるという理解でよろしいんでしょうか。","respondent":"中島指導課長","answer":"予算項目として、現在、その二つが両立していますけれども、ご承知のように、小・中一貫教育は全区展開で考えてありますので、そのときに、小・中連携という部分が、小・中一貫のさまざまな特色ある小・中一貫という形に補完されていく可能性はあろうかと思います。","voiceIndex":92,"id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"全区的に展開するという中では、校長会等々と連携をとりながら平成１６年度の全教科のカリキュラムにとりまとめるということなんですが、それは、もう少し具体的にどういう時期に、どういうものをしてというところ。それから、各学校への周知の方法、連携の方法、学校によって温度差はいろいろあると思うんです。そこら辺の対応を、どういうふうにされるのか、教えていただきたいと思います。","respondent":"中島指導課長","answer":"最後の保護者の不安ですけれども、こちらにつきましては、現在もやっております小中一貫校での説明の場ですとか、それからまた、必要に応じまして、小Ｐ連、中Ｐ連等での説明の場でもって、一つ一つご説明をしていきたいと考えております。","voiceIndex":94,"id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"そうしますと、平成１８年度以降から移行していくということは、大崎地区での完全移行、開校になると思うんですが、そこと同時並行という形になるという感覚なんでしょうか。","respondent":"中島指導課長","answer":"ただ、小中一貫校におきましても、例えば、１年生から９年生までのカリキュラムが、平成１８年度から全部そのままぼんと始まるかというと、今、研究開発は進めておりますけれども、その前の年までそのカリキュラムで進んできてないと状況も一部ですので。","voiceIndex":96,"id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"徐々に、様子を見ながらということなんですが、昨年、文教委員会の行政視察で広島の呉市に行ってまいりました。そこは、小中一貫校を、もう４年ぐらい実績を積まれていまして、その話を聞くことができたんです。その辺、教育委員会としてはどういうふうに指導されていこうとされているのか、お聞きしたいと思います。","respondent":"中島指導課長","answer":"現在、大崎地区と大井地区でやっております小中一貫校、この両方を見ましても、教員認識は随分違っている状況があろうと思います。大崎地区のほうは、やはり１年先んじているだけに、それぞれの教員認識は非常に高まっているところです。","voiceIndex":98,"id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"課題もいろいろあろうかと思いますので、こういう課題は、今こういうふうに取り組んでいますというような、具体的なものをニュースであるとか、保護者会があったとき等に、先生のほうから説明するとかいうことで、いろいろ疑問点、それから、親側としてこういうことをお願いしたいということも、多分要望として出てくるかと思いますので、それをぜひお願いしたいと思っています。","respondent":"中島指導課長","answer":"小・中一貫教育の全区展開におきましても、こういった教科担任制がどこまで可能かという部分がこれからの検討になっていくわけですが、進めていきたいと考えています。","voiceIndex":100,"id":"exchange-043"},{"speaker":"西本委員","kind":"質問・要望","question":"それのメリットとしては、やはり１人にしない、先生方が１人で悩まない、それから子どもたちの様子をいろいろな目で見ていくという、そういう視点が大切だとおっしゃっていた部分がありますので、その辺、教科担任制とは限らず、これから小中一貫も含めて考えていくと、なるべく多くの教員の目、いわゆるお互いに教育に関する相談ごとができるという、チームでいろいろやっていけるというような。","respondent":"中島指導課長","answer":"ご指摘のように、例えば、東京都が実施しております教員加配、教員を１名増員するという制度も、チームティーチングですとか、少人数指導といった内容で、子どもたちをより多面的に教えていける、見ていけるというようなシステムをつくっていこうというような部分が。","voiceIndex":102,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"公表するということに対しては、私の感覚ですと、あまり序列化が進んだりというようなことはないように思うんです。ただ、学力定着度調査の結果がどう反映されたのか、現場の子どもたちにどういうふうに反映されたのかというところでは、まだまだ改善が必要かなという部分があって、そこら辺を、今後、どういう方向で学力定着度調査を進めていこうとしているのか、お考えをちょっとお聞きしたいと思います。","respondent":"中島指導課長","answer":"中学校におきましても、去年の２学期の段階でもう既に、学校だよりに、このような手を打っていきますということを大きく表明していただいている学校もあります。今後、中学校におきましても、こういった態度表明のあり方を検討していきたいと考えています。","voiceIndex":104,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"習熟度別については、時間がありませんので別途お聞きしますが、学力定着度調査は、ホームルームの中でカルテをつくって、その子どもの指導に当たっているというところがありました。これは非常にいいんじゃないかなと、私は思っています。あゆみのほうも、それにあわせていろいろと考えていただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-046"},{"speaker":"武内委員","kind":"質問","question":"私のほうから、３１３ページの小中一貫校推進経費と、３０１ページのまちの人々に学ぶ授業、２９７ページの教職員研修についてお伺いしたいと思います。初めに、小中一貫校推進経費についてですけれども、ご説明の中で、実施設計等委託ということで ４,０００万円が計上されておりますが、この委託先と、「等」とありますけれども、実施建設以外の「等」の内容を教えてください。","respondent":"鷹倉庶務課長","answer":"大井地区における小中一貫校につきましては、実施設計、それから一部、仮校舎の借り上げ等が入ってあります。","voiceIndex":108,"id":"exchange-047"},{"speaker":"武内委員","kind":"質問","question":"実施設計等委託のところで、委託先の内容と、また、今、「等」というのが仮校舎の賃借というお話ですけれども、そうすると、場所等もお決めになられたのか、その辺を教えてください。","respondent":"鷹倉庶務課長","answer":"大井地区の仮校舎ですけれども、これにつきましては、現在、基本設計のプロポーザルで受けた部分で、今、検討していますけれども、仮校舎は、伊藤中学校の敷地の中でうまく回しながら運営していきたいと考えているところです。","voiceIndex":110,"id":"exchange-048"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、ちょっと変わりますけれども、昨年１０月１日に説明会を開かれた以降、説明会をもし持たれていれば、その回数と状況等がございましたら、教えてください。","respondent":"鷹倉庶務課長","answer":"大井地区におきまして、今、ご指摘のございましたように、１０月１日に説明会をさせていただきました。","voiceIndex":112,"id":"exchange-049"},{"speaker":"武内委員","kind":"質問・要望","question":"いろいろそういった質疑が行われた中で、今後もまた、建設等の実施設計ということなので、いろいろな形で、建物の改築の周りの環境の問題とか、今、大崎地区のほうでもいろいろあったと伺っていますので、その辺のところをしっかり、ぜひ、近隣の状況を聞いていただきながら、問題ないように進めていただければと思います。これは要望としてお願いしておきたいと思います。","respondent":"中島指導課長","answer":"こういった地域の貴重な方々に授業に参加していただきまして、教員と一緒に子どもを指導することで、教育活動を豊かにすると同時に、そのことで学校と地域社会とのより一層強い連携を図る、結果として開かれた学校づくりに寄与していく、こういったところが。","voiceIndex":116,"id":"exchange-050"},{"speaker":"武内委員","kind":"質問","question":"そうすると、具体的なところで、地域の方たちが教壇に立って、生徒に対していろいろなお話をされるというイメージなんですけれども、例えばいろいろなお仕事の方がいると思うんですけれども、その仕事の技術的なものとかいろいろあると思うんですけれども、どのようなお話をされるか、もし、ありましたら教えてください。","respondent":"中島指導課長","answer":"失礼いたしました。昨年度の実績ですけれども、実は、小学校全４０校で、年間１８時間の実施、そして、１８校の中学校で年間１０回、１０時間の実施というのが、予算上上げられている部分です。","voiceIndex":118,"id":"exchange-051"},{"speaker":"武内委員","kind":"質問","question":"今、教えていただいたとおり、非常にいい内容なんじゃないかなと思っています。ただ、その中で、事務事業評価のほうでは、もちろんＡにはなっているんですけれども、内容の充実、拡大を行うとなっておりますけれども、予算のほうは、昨年と比べて減っているんでしょうか。それとも増えているんでしょうか。","respondent":"中島指導課長","answer":"今年度と同額という形です。","voiceIndex":122,"id":"exchange-052"},{"speaker":"武内委員","kind":"質問・要望","question":"要望します。では、最後に２９７ページの教職員研修というところでお聞きしたいと思います。これは、教職員に対しての研修ということなんですけれども、学校経営研修ですとか、２９９ページに四つぐらいありますけれども、生活指導主任研修、ほか８研修は結構ですけれども、この四つの研修、大体どんな研修をされているか教えてください。","respondent":"中島指導課長","answer":"生活指導主任の研修ですけれども、こちらのほうは、およそ月に一遍という形で、情報交換の部分と、さまざまな学校に関係する機関の方々からのレクチャー、または具体的なワークショップといったもの中心に進めているものです。","voiceIndex":124,"id":"exchange-053"},{"speaker":"武内委員","kind":"質問","question":"教育事情視察、これは、どういったものを視察されるのか。教育研究奨励費、この辺も内容を教えてください。","respondent":"中島指導課長","answer":"視察ですけれども、これは同和教育関係の教育委員会、そして、学校の教員の管外視察という形で予算を組ませていただいております。この視察が年に４回ほどございまして、そういった中で、先進地区の視察等を含めて実施しているものです。","voiceIndex":126,"id":"exchange-054"},{"speaker":"武内委員","kind":"質問","question":"これも事務事業評価のほうに、研修の方法や内容を見直しをすると載っておりますけれども、これは見直しをされた予算なのか、それともこれから見直しを考えられるのか、その辺をあわせて教えてください。","respondent":"中島指導課長","answer":"現在、もう既に見直しをしている部分があります。ただ、研修の内容につきましては、教育事情が刻々と変わる現在ですので、また、来年度も、それに伴いまして、その内容につきましては見直しを図っていきたいと考えているものです。","voiceIndex":128,"id":"exchange-055"},{"speaker":"武内委員","kind":"意見","question":"やはり、子どもたちの成長というのは、学校の先生の成長が伴わなければ成し得ないものかなと考えていますので、いろいろご苦労は多いとは思いますけれども、ぜひ研修をよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":130,"id":"exchange-056"},{"speaker":"石田委員","kind":"確認","question":"それは、例えば、しながわ中央公園でこういうふうにしたいという子どもたちの意見を聞いたら、そういう場所でもいいから、必ずそういうところをつくってほしいんだという話があって、それじゃあ、区もそういう形で対応しましょうということで、今、そういう動きになったということで理解をしているわけだけれども、その考え方でいいのかどうかだけ、答弁をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-057"},{"speaker":"石田委員","kind":"質問","question":"じゃ、それはよろしくお願いします。学校給食について、お話をします。私も、一般質問で食育について質問をいたしました。そのとき、もちろん食については、家庭における教育が最も重要であるというようなことで、まずそこが最低限必要なんだと。そこら辺の点もあわせて、わかったら教えてください。","respondent":"谷田部学務課長","answer":"ちなみに品川区で言えば、小学校で行われたのが昭和２５年でして、中学校につきましては、たしか昭和４１年に１校で始まりまして、昭和４６年までに中学校全校で給食が実施されたという経過になってあります。","voiceIndex":136,"id":"exchange-058"},{"speaker":"石田委員","kind":"質問","question":"滞納はいいです、０.２％だから、新聞に載っているのと大分違うみたいなので、品川区はいい方向だなと考えています。今の給食の話であります。それから、給食法の四つの目標というのがあります。だからそういうことを考えるんであれば、名称からスタートして、制度自体をいろいろな形で変えていくというのも、一つの給食のあり方だと、私は思うんですが、そこら辺の考え方を教えてください。","respondent":"谷田部学務課長","answer":"そんな中で、「日常生活における食事について、正しい理解と望ましい習慣を養うこと」、これが１点目です。２点目は、「学校生活を豊かにし、明るい社交性を養うこと」。３点目が、「食生活の合理化、栄養の改善および健康の増進を図ること」。","voiceIndex":138,"id":"exchange-059"},{"speaker":"石田委員","kind":"質問","question":"そういう意味合いの中で、支給だ、配給だという形の給食という名前があるわけでありまして、海外でもそう訳されているものについて、給食ということの今の意味合いをどうとらえているか。その言葉だけのとらえ方を教えてください。","respondent":"谷田部学務課長","answer":"長く定着している言葉だというふうに、私は理解しています。ただその辺で、いろいろと委員のほうで、例えば、そういう言葉が児童生徒に与える影響等々があるんだということがあれば、私どもも、そういう中で愛称も含めて検討するということも、方向性等はあるなと思ってあります。","voiceIndex":140,"id":"exchange-060"},{"speaker":"石田委員","kind":"質問・要望","question":"食育を含めた子どもに対する食の教育ということで、意気込みを見せてもらうことだと、私は思っております。これは、私が考えたことなんで、意味合いは別でありますが、そういう意味を含めて、ぜひそういう形で食に対しての考え方を改めて考えていただく、もしそういうことがあるんであれば、例えばそういう意味合いを広くアンケートを取るとか、そういう考えがもしありましたら、ぜひ教えていただきたい。","respondent":"鷹倉庶務課長","answer":"たしか、品川区には品川めしというものもかつてあったと聞いてあります。今、委員のご提案の品川のごはん、これも一つのネーミングだと思いますので、今後、十分検討してまいりたいと思ってあります。","voiceIndex":142,"id":"exchange-061"},{"speaker":"石田委員","kind":"質問・要望","question":"今、小中一貫校も各地域に１校ずつなんていうソフト面のことは、もう少し皆さんお話しされていると思いますが、じゃあ、小学校はこれぐらい単独として改築をしていこうと、そういう部分をある程度出していっていただかないと、もうそろそろ地域では、そういう話が結構出ていますので、そこら辺の、いつごろということも含めて、そういうことを言っていくんだというお考えだけ、ちょっとお聞かせください。","respondent":"鷹倉庶務課長","answer":"基本的な考え方は、私ども、品川区の総合実施計画の中で、今回も新たに改定したものをお出ししていく予定です。学校改築につきましては、小中一貫校も絡みますし、あるいは、今、お話がございました耐震の補強も絡んでまいります。","voiceIndex":144,"id":"exchange-062"},{"speaker":"石田委員","kind":"質問・要望","question":"やめようかと思ったんですけれども、具体的にソフトの部分はある程度示していただきたいと思いますので、その具体的な考え方だけ、最後に。","respondent":"鷹倉庶務課長","answer":"具体的な考え方ですけれども、小中一貫の問題、地区をいろいろ考えていかなきゃいけないという問題があります。小中一貫校の展開をにらみながら、学校改築が出てくるのかなと、この辺が基本的に考えられることかと考えております。","voiceIndex":146,"id":"exchange-063"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、３０１ページの小・中一貫教育と、同じページのすまいるスクールに関連して伺いたいと思います。初めに、今年の２月５日のプレス発表の中で、小・中一貫教育の全区展開を目指しますと発表されましたが、いつ、だれが、どこで最終決定を行ったのでしょうか。大切なことなんで、何月何日に決定したのか教えていただきたいと思います。","respondent":"鷹倉庶務課長","answer":"何月何日までは、ちょっと出ませんけれども、基本的に、私ども教育委員会で政策予算の審議をしてまいります。これが１１月から１２月にかけてやりまして、企画財政当局にお出ししていく、その過程の中で、企画部門、あるいは、三役査定の中で決まっていくということかと思います。","voiceIndex":149,"id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が聞いたのは、教育委員会というのは、月２回開催されていると思うので、何月何日というのはきちんと出ると思いますので、今直ちに調べていただきたいのと、これまでも決定してから発表すると言っているわけですから、いつ決定したのかというのが出ないわけがありませんので、もう一度答えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-065"},{"speaker":"中塚委員","kind":"質問","question":"教育委員会の決定ですと、１１月２７日に審議をされたということでよろしかったんでしょうか。もう一度お答えください。","respondent":"富田教育改革担当課長","answer":"それに至る過程での背景と申しますか、考え方としては、施設一体型の小中一貫校に限らず、施設が別々の学校においても、小・中一貫教育を実施していけるようにしたいという内容での特区申請を行ったものであり、その時点で、全区展開での決定をとったということとは別の問題です。","voiceIndex":155,"id":"exchange-066"},{"speaker":"中塚委員","kind":"質問","question":"私が伺いたいのは、７月１０日の時点で、品川区長としては、全区展開をするということを政府に上げているわけですよね、申請をしているわけですよ。ということは、品川区の意志として、小・中一貫教育の全区展開をするんだと決めたのがいつかと伺っているんです。教えてください。","respondent":"富田教育改革担当課長","answer":"先ほど申し上げましたように、特区申請の中で、全区展開をすると書いているわけではございませんで、できるところでは、こういった小・中一貫教育を他の小・中学校でも実施していきたいという考え方を述べたところまでです。","voiceIndex":157,"id":"exchange-067"},{"speaker":"中塚委員","kind":"質問","question":"説明がよくわからないんですけれども、結局、７月１０日の前には、品川全区で小・中一貫教育をやるということを意志決定しているわけですよね。次にいきたいんですけれども、結局、７月１０日の時点で、少なからず全区展開をするという申請書を政府に上げておきながら、私たち議会を含め、区民に品川区の小・中一貫教育を全区展開するという説明をしたのは、一体いつでしょうか。説明してください。","respondent":"富田教育改革担当課長","answer":"これで３度目になりますけれども、特区申請の中では、すべての区立小中学校で小・中一貫教育を実施していくというふうに述べたものではございません。小・中一貫教育を、施設一体型の小中一貫校以外の学校でも実施していく旨を書いているものです。","voiceIndex":159,"id":"exchange-068"},{"speaker":"中塚委員","kind":"質問","question":"なぜ追及するかというと、そもそも小・中一貫教育が区民に明らかになったのは１月１８日の朝日新聞、つまり議会に報告される前に、新聞社が先に報告をして、議会でも大問題になったことを、議事録でも見ました。しかし、今の話では、半年前に政府に上げておきながら、議会に対して説明があったのは、２月５日のプレス発表、半年後なんですよ。その辺について、一言伺いたいと思います。","respondent":"古川教育次長","answer":"２月５日のプレス発表、あるいはさらには、今回、こういう形でご審議していただいておりますので、それぞれの段階におけるものの考え方、これは必ずしもすべて何月何日、どこどこでどういう決定したということとはまた違うと、私は考えてあります。","voiceIndex":161,"id":"exchange-069"},{"speaker":"中塚委員","kind":"質問・要望","question":"区民への説明はもちろん、議会に対してあまりにも説明不足で、私は以前から指摘していますけれども、そういうトップダウンの姿勢は改めるべきではないかと考えています。実施される教育内容は、資料もおろか報告もされてないんで、なぜ、報告せずに実施するのか。それと、４月から実施する初年度の教育課程の内容とは一体何なんでしょうか、説明していただきたいと思います。","respondent":"中島指導課長","answer":"４月から、大井地区の小中一貫校で実施します教育課程ですけれども、教育課程の実施につきましては、学校の管理運営規則によりまして、各学校長がその教育課程を編成し、その届け出を教育委員会にするというシステムになってあります。","voiceIndex":163,"id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"計算したんですけれども、国語だと、３年生で年間３０時間増えますよね。そのまま４月に実行するということは、一体どんなカリキュラムをやるかも報告せずに、なぜそれを現場でするのか、私には到底理解することはできません。質問だけ、次に進めさせていただきたいと思います。改めて、戦前の教育は何が問題で、一体今の教育基本法はどんな人間像をつくろうとしているのか、説明していただきたいと思います。","respondent":"若月教育長","answer":"その結果や何かは、それは議会の方に当然報告をし、ご説明をするということでありまして、トップダウンだから、品川区が戦前のような教育をやっているというのは全くこれは筋違いの話でありますので、ここだけははっきりさせておきたいと思います。","voiceIndex":165,"id":"exchange-071"},{"speaker":"中塚委員","kind":"質問・要望","question":"５分なので、次のことを質問したいと思います。ここに平成１４年４月１６日の小中一貫校準備委員会資料２というものがあります。この資料というのは、どこの所管の責任で、だれが提出したものなのか、説明していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":167,"id":"exchange-072"},{"speaker":"中塚委員","kind":"質問","question":"私が伺いたかったのは、この資料を提出した所管の責任者はだれかということです。もう一度だけ説明してください。","respondent":"富田教育改革担当課長","answer":"小中一貫校のコンセプトにつきましては、主に教育委員会事務局指導課のほうで、たたき台としてはつくってきているものです。小中一貫校開設に向けては、教育委員会で決定をとっているものです。","voiceIndex":171,"id":"exchange-073"},{"speaker":"中塚委員","kind":"確認","question":"教育委員会事務局が作成して、準備委員会に提出したということなんで、作成した責任者は教育長ということで、よろしいのでしょうか。そこだけ１点、確認させてください。なぜかというと、ここに、こう書かれているんですね。区が掲げる考え方というのは、そういうものなのかどうか、確認させてください。","respondent":"中島指導課長","answer":"この小・中一貫教育の内容につきましては、平成１４年のその時期以降にも、カリキュラム検討委員会の中でさまざまな検討をする中で、よりまた新しい視点、そして新しい研究を内容をもとにして、少しずつそれを改良してきている状況があります。","voiceIndex":173,"id":"exchange-074"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が言っているのは、この時点で、教育委員会事務局の責任で提出した資料に、こう書かれていると。さきの資料と合わせると、品川区は、能力の高い生徒を早期に発見し、特定分野を優れた能力を伸ばしていく、結局、一部の子どもたちだけに特別な授業を行うエリート教育じゃないかと思うので、ぜひ、教育長のご見解を教えていただきたいと思います。","respondent":"中島指導課長","answer":"このステップアップ学習の中で、一人一人の子どもたちが興味、関心、そして自分が取り組みたい内容、そして自分が課題として認識している内容、こういったものをクリアしながら高めていく、そしてより高い資質や能力を身につけていく。","voiceIndex":175,"id":"exchange-075"},{"speaker":"中塚委員","kind":"質問・要望","question":"１分なんで、すまいるスクールについて一言だけ聞きたかったので、話題を変えさせていただきたいと思います。先日の区長の答弁で、すまいるスクールについて、塾にかわるものがすまいるスクールであると、こういう説明がございました。教育委員会の説明と区長の発言はあまりにも食い違うのではないかと思いますので、この辺について、区長はどのような趣旨で言ったのか、説明していただきたいと思います。","respondent":"富田教育改革担当課長","answer":"すまいるスクールは、さまざまな役割を持ってあります。その中では、遊びやスポーツだけでなく、保護者のニーズにこたえ、学習面も含め、また４月からは放課後児童健全育成事業も担っていく、さまざまな役割を持って、これからさらに進んでまいりたいと考えております。","voiceIndex":177,"id":"exchange-076"},{"speaker":"三村委員","kind":"質問","question":"引き続きになって申しわけないんですけれども、３１３ページ、３０１ページの小中一貫校推進経費についてと、小・中一貫教育についてお聞きしていきたいと思います。公平性、透明性を図るためには複数の申請者の中から選定するということともに、第３者機関的な選定委員会が必要かと思いますけれども、公募でなかった理由、そして複数公募について、選定委員会設置について、ご所見をお伺いしたいと思います。","respondent":"榎本行財政改革担当課長","answer":"公募が前提というのもありますけれども、綿密な打ち合わせの中で、専門性を生かしたＮＰＯを使った形で検討してまいりましたので、そこから新たに公募をして、今年の６月に間に合わせるというのはなかなか難しいという判断で、特に公募等はしておりません。","voiceIndex":180,"id":"exchange-077"},{"speaker":"三村委員","kind":"質問","question":"選定委員のメンバーは、どのような方だったのかお聞きしたいと思います。今回、ぷりすくーるで指定管理者制度を導入されましたけれども、本来であれば、手続条例制定が必要かと思いますけれども、それについてのご意見をいただければと思います。","respondent":"市岡企画財政課長","answer":"公募が前提とはなっておりません。地方自治法の改正の中では、直営か、指定管理者の指定方式による選択をすることになっておりますが、選定の方法については、法律は決めておりませんので、公平な選定を行うための選定委員会を設置したです。","voiceIndex":182,"id":"exchange-078"},{"speaker":"三村委員","kind":"質問","question":"小中一貫校と小・中一貫教育についてなんですけれども、昨年の決算特別委員会においては、小中一貫校の実施、一体型と分離型、先ほども出ていましたけれども、分離型が当初念頭にあったかと思うんですけれども、全く今回のプレス発表を見ると、分離型の扱いについてはなくなったという理解でよろしいのか、変更になったという形でよろしいのか、ちょっとその辺よくわからないので。","respondent":"中島指導課長","answer":"小・中連携教育という部分は、小中一貫校のメニューにその成果を生かしている部分もありますけれども、連携といった場合には、行事のみの連携とか、いろいろな要素が入ってまいりますので、そこのところが、一貫教育という部分とは大きく変わっているところと考えております。","voiceIndex":184,"id":"exchange-079"},{"speaker":"三村委員","kind":"質問","question":"ちょっとよくわからない。特区申請を見る限りにおいては、一体型と分離型を合わせて５校程度となっていたんですけれども、分離型を広げて全区展開ということなんですか。じゃなくて、分離型は全く念頭に置かなくなったという理解でよろしいんでしょうか。","respondent":"中島指導課長","answer":"分離している学校で一貫教育を推進するですので、いわば、分離型が全区で実施をするというふうにとらえていただければと考えています。","voiceIndex":186,"id":"exchange-080"},{"speaker":"三村委員","kind":"質問・要望","question":"わかりました。このような計画が進められていきますと、小学校、中学校の場所、形態が変わってきます。保護者や子どもたちに、こういうような形で展開をしていく、今後の小中一貫校や小・中一貫教育をどういう形でやっていくかというのを、ぜひきちんと長期展望を示していただきたいと思うんですけれども、お考えのほうをお聞きしたいと思います。","respondent":"中島指導課長","answer":"校長会とのプロジェクトチームをつくりながら、それぞれの学校の実態に応じて、どういう形で平成１８年度からの移行に入っていくかということを、この２年度間かけて準備、企画いたしまして、学校の実態に合わせる形で。","voiceIndex":188,"id":"exchange-081"},{"speaker":"三村委員","kind":"質問","question":"これからプロジェクトをつくってということですので、今後、５年後、１０年後、小学校がどういう形になっていくのか。この状態ですと、小学校のブロックをなくしていくのかなというような危惧を覚えるんですけれども、小学校のブロック制については、荏原地区の小中一貫校に関連してどういうふうにお考えなのかお聞きしたいんです。","respondent":"谷田部学務課長","answer":"小学校の場合、学校選択は５年になりますので、ある面では、学校選択制の上では、４ブロックが定着しているというのと、それから行政の地区とはまた別の話です。私ども学校選択制は、この４ブロックを基本として、今後も学校選択を進めていきたいと考えています。","voiceIndex":190,"id":"exchange-082"},{"speaker":"三村委員","kind":"質問","question":"荏原地区だと二つの小学校のブロックがあるので、そこに１校だけ小中一貫校をつくると、小中一貫校は選べない学校のブロックが出てくるかと思うんです。２校つくるのか、ブロックをなくすのかという判断をされるんじゃないのかなと思ったんですけれども、その辺もう１回、お聞きしたいんです。","respondent":"古川教育次長","answer":"今ある小学校の４ブロックは、あくまでも学校選択制におけるブロックということで、それはそれとして機能していますし、今後、変化はあるかもしれませんけれども、一応それが一つの流れです。","voiceIndex":192,"id":"exchange-083"},{"speaker":"三村委員","kind":"質問","question":"小中一貫校実施に伴って、小中の連携をなだらかにして、不登校をなくしていくということも目的としてあるかと思うんですけれども、小中一貫校内であれば、小学校から中学校への移動というのは、たしかにハードルが低くなるかと思うんですけれども、小中一貫校に外の小学校から入ってきた場合、全く知らない施設で、中から上がってくる生徒はもう顔見知り状態で、自分たちは外からというようなことで。","respondent":"中島指導課長","answer":"したがいまして、教育内容、ソフトの部分では、すべての小学校で４、３、２、分離校の場合には、５、６年生までしかありませんから、その後の７年生を見越した形での３ということになりますけれども、それを実施していく。","voiceIndex":194,"id":"exchange-084"},{"speaker":"三村委員","kind":"質問","question":"そういう状況にある中で、すまいるスクールの校庭利用や体育館利用が制限されるんじゃないか、その辺の整合性とか、調整をどういうふうに考えていらっしゃるのか、お聞きしたいんです。","respondent":"中島指導課長","answer":"小学校の体育館におきましても、中学校と同じだけの非常に大きなスペースを確保しています。こういった有効的なスペースをフルに活用していきながら、すまいるスクールにおきましても、遊び場、居場所の確保、これが一番のねらいですので、それを実現していきたいと考えています。","voiceIndex":196,"id":"exchange-085"},{"speaker":"三村委員","kind":"質問・要望","question":"今回私がお聞きしただけじゃなくて、保護者の方からいろいろ質問があるかと思います。ちょっともう１点だけ、３０１ページのプラン２１に関係して、時間があるのでちょっとお聞きしたいんです。ホームページを見たんですけれども、まだ公表がされてないんですね。いつごろ公表するのか。その中の主な意見、３点とか、５点とか、どういった意見が出されているのかお聞きしたいんですけれども。","respondent":"中島指導課長","answer":"実は、言い訳みたいになってしまうんですけれども、まだ、座談会の録音起こしという部分で時間が大変かかってございまして、また、年度切り換えで予算上の措置もございまして、新年度に入ってからの処理という形になる見込みです。","voiceIndex":198,"id":"exchange-086"},{"speaker":"三村委員","kind":"質問・要望","question":"いろいろな方からご意見が多数集まったということなので、ぜひそういった意見に真摯に耳を傾けていただいて、今後の教育委員会の進め方についても反映をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":202,"id":"exchange-087"},{"speaker":"原委員","kind":"質問","question":"私のほうからは、３１２ページ、学校施設建設費の学校改築のことについてお伺いをいたします。今、小中一貫校および校舎改築ということで、５８校中の８校ということで行われているわけですけれども、児童生徒のそこにおける精神的、心理的な影響とか、または事業に対するいろいろな影響、あるいは対策があると思うんで、その辺についてお伺いをします。一つは、ハード面の部分です。","respondent":"鷹倉庶務課長","answer":"部屋の隅で、壁との関係でわずか１mmとか２mmあいているわけですけれども、そこを突っ込むような形にすれば、通るような現況がございましたので、そこについてはすぐにふさぐということを考えてあります。","voiceIndex":204,"id":"exchange-088"},{"speaker":"原委員","kind":"質問","question":"そういった事情の中で、プレハブ仮校舎というのは、これまでも幾つか建てられているわけですよね。しかも、いろいろ行ってきた経緯があり、そしてまた、今回も決定をするまでのいろいろ経緯を持っていると思うんですが、確かにプレハブの仮校舎だということですから、そんなにきっちりいかないのはもうわかっている話なんですが、しかしその中においても、これから幾つかの学校を改築していくわけですよ。","respondent":"鷹倉庶務課長","answer":"これから、いろいろ改築していく中で、仮校舎不可避の問題です。今回、ご指摘いただいている点も踏まえながら、万全な態勢をとっていきたいと考えています。","voiceIndex":206,"id":"exchange-089"},{"speaker":"原委員","kind":"質問","question":"ぜひ、今後の中で対応していってほしいのと、今回の第日野小学校の部分も、しっかり対応方をよろしくお願いします。次に、ソフト面についてお伺いします。それからまた、生徒児童は十分に体を動かすことができない、そういうところからくるストレス、ストレスからいろいろな問題も波及してくるんではないかと思うんですが、その辺のところのお考えはどうでしょうか。","respondent":"中島指導課長","answer":"これは、学校だけの力では十分な情報収集ができない部分もありますので、教育委員会と学校が一体となりまして、教育課程に合わせる形で、そこが賄えるようにフォローしてまいりたいと考えています。最後に、ご質問のございましたストレスの部分です。","voiceIndex":208,"id":"exchange-090"},{"speaker":"原委員","kind":"質問・要望","question":"今まで平穏であった学校が、そのために荒れてくるとか、あるいは、そこでの授業のおくれをどういうふうにしたらいいのかとか、いろいろ出てくると思うので、十分にお考えをいただきたいと要望しておきます。例えば、プールの使用のときに工事をちょっと避けるとか、あるいは、全体の工事の計画を考えながら予定を組んでいくとか、その辺はいかがでございましょう。","respondent":"鷹倉庶務課長","answer":"ただ、そこの学校の敷地条件、近隣の住宅の条件だとかいろいろございまして、その中で、最終的に選択されていくことになります。ただ、今お話のあった点が重要な点だということは認識しておりまして、今後もそのようにしていきたいと思ってあります。","voiceIndex":210,"id":"exchange-091"},{"speaker":"原委員","kind":"質問・要望","question":"ぜひ、言ったところの部分も、かなり隣接した住居もありますので、お考えをいただきたいと思います。今までのことを総合して、父母の中には、工事中は学校を敬遠してしまう、ほかの学校に行っちゃうという生徒、あるいは児童、そしてそのご父兄もいるわけなので、その辺の対策については、いかがでございましょう。","respondent":"中島指導課長","answer":"私どもといたしましては、例えば、小学校であれば、子どもたちが６年間在籍をする形になりますので、その流れを、当然工事も含めまして十分に説明をすると同時に。","voiceIndex":212,"id":"exchange-092"},{"speaker":"原委員","kind":"質問・要望","question":"そういったことを、なるべく外にお話をされていって、ぜひ、工事中であっても、その学校を選ぶ、来ていただく、来てくれるような形をとっていただきたいなと思います。そういったところの交渉について、そしてまた現改築の学校の施設を利用しているいろいろな団体がありますけれども、そういった団体にはどういう配慮をされていくのか、お伺いをさせていただきたいと思います。","respondent":"古川教育次長","answer":"これは、品川区における一つの最大のメリットだろうと思ってありますので、一つの学校で改築があれば、当然、近隣の小中学校、あるいは公共施設、さまざまな資源を使いながら、新しく生まれかわる学校のために総力を傾けながら教育環境。","voiceIndex":214,"id":"exchange-093"},{"speaker":"山村委員","kind":"質問","question":"私からは、先ほど石田委員からも質問がありましたが、３１１ページの学校給食費について、３０５ページ、インターネット活用教育推進事業、それから、３０１ページの国際理解教育および、時間がありましたら３０３ページ、和楽器による音楽教育について質問したいと思います。会計を閉めてから給食費が納入された場合の会計処理はどうなされているのかということをお聞きしたいと思います。","respondent":"谷田部学務課長","answer":"金銭債権の時効はたしか２年だと聞いてありますので、卒業した後も、粘り強く納めていただくような働きかけは、各学校とも取り組んです。","voiceIndex":217,"id":"exchange-094"},{"speaker":"山村委員","kind":"質問","question":"次に３０５ページのインターネット活用教育推進事業について、ご質問したいんですが、インターネット活用教育推進事業というものをやられていると、要するに学校の教育現場で、パソコンを使っての学習やインターネットを使って学習をやられているんだと思うんですが、教員のパソコン習熟度というものは、現在、どのぐらい達成しているのかということを、北品川の人がすごく疑問に思っていたようなので。","respondent":"中島指導課長","answer":"平成１４年度のデータですけれども、小学校のほうでは、８８％、９０％に近い教員がコンピュータを操作できるというような状況にあります。その中で、指導にも活用できるという教員は７１％という状況になってあります。","voiceIndex":219,"id":"exchange-095"},{"speaker":"山村委員","kind":"質問","question":"ただいまお伺いした、指導にも活用できるのが、小学校で７１％、中学校ではさらに悪くて４３.８％ということなんですが、先ほど言われた中学校の場合は、専門分野に特化しているという部分があると思うんですけれども、インターネットを活用した教育といいますと、別にそれに特化する必要もなく、すべての分野で扱えるとは思うんですよ。","respondent":"中島指導課長","answer":"ただ、本区におきましては、すべての学校にコンピュータ室を設置させていただいておりまして、その中で、各学校ごとの研修、そして、夏に６日間集中研修ということで、午前中、午後の研修会を実施しています。","voiceIndex":221,"id":"exchange-096"},{"speaker":"山村委員","kind":"質問・要望","question":"そういう意味では、もっと徹底すべきだと思うんです。よもや習うことを拒否しているような先生はいらっしゃらないとは思うんですけれども、今後、徹底すべきだと思うんですけれども、それに対しての障害というわけじゃ、言い方がちょっと難しいんですが、もっと徹底していただきたいという思いがありまして、今後、どのように徹底していくのかというのを聞かせていただければと思います。","respondent":"中島指導課長","answer":"コンピュータを活用した教育指導、または教育事務処理といったような部分は、もう今後の趨勢ですので、今の研修体制の充実を図っていくほか、公務等の処理におきましても、またパソコンを活用をしていく、こういったような環境を整備していきながら。","voiceIndex":223,"id":"exchange-097"},{"speaker":"山村委員","kind":"質問","question":"でも、何だかんだ言っても、まだまだ、なかなかできない方がいらっしゃると思うんですが、インターネットを使った授業をやるということは決まっているわけですから、習わない先生というのは、逆に言えば、すごく問題だと思うんです。このことについて、教育委員会のほうではどのようにお考えなのか、教えていただければと思います。","respondent":"古川教育次長","answer":"研修というのも、確かに一つの方法ですし、研修を活用しながら学んでいくのは結構ですけれども、既にもうパソコンというものは、一昔前そろばんから電卓に変わった時代と同じでございまして、パソコンなしにこれからの業務は到底務まらないと思ってありますので。","voiceIndex":225,"id":"exchange-098"},{"speaker":"山村委員","kind":"質問・要望","question":"教育次長の心強いお言葉で、期待が持てる次第ですので、次の質問にいかせていただきたいと思います。３０１ページの国際理解教育、プラン２１、小学校における英語学習のところで、大使館、学校の施設、インターナショナルスクール等々の交流、連携という文字が見えるんですが、どのようなことをやっていらっしゃるのか、教えていただければと思います。","respondent":"中島指導課長","answer":"その交流活動の部分で、実際に本区におきまして実施されている交流といたしましては、例えば、本区の第三日野小学校のほうでは、近くに大使館が多くありますので、こちらの方々を招きまして、特に文化交流という形で進めてあります。","voiceIndex":227,"id":"exchange-099"},{"speaker":"山村委員","kind":"意見","question":"ただいまのご説明ですと、インターナショナルスクールが全然きていないような気がするんですが、インターナショナルスクールは、外国の施設の中等では唯一学校施設でありますので、そういう意味では、教員の交流ということも考えられますし、インターナショナルスクールの１日体験を生徒にさせるということも考えられます。","respondent":"中島指導課長","answer":"教育委員会として、特にインターナショナルスクールとの交流という部分での取り組み、授業は、現在のところ考えてございませんけれども、国際交流という形での国際理解教育の推進という部分では。","voiceIndex":229,"id":"exchange-100"},{"speaker":"山村委員","kind":"質問","question":"第三日野小学校でやられているということはわかっているんですが、具体的にどのようなことをやられているんでしょうか。","respondent":"中島指導課長","answer":"第三日野小学校の児童、またインターナショナルスクールの生徒、これの相互訪問というような交流をやっていると聞いてあります。","voiceIndex":231,"id":"exchange-101"},{"speaker":"山村委員","kind":"質問","question":"相互訪問ということだと、ちょっといまいちよくわからないんですけれども、あまり英語の授業とは関係なくということでしょうか、例えば中学校では。","respondent":"中島指導課長","answer":"お互いの国の文化ですとか、生活習慣といったものを、交流をしながらコミュニケーションし合うといったような形の取り組みですので、英語学習といった要素は、若干低くなってくる部分だろうと考えています。","voiceIndex":233,"id":"exchange-102"},{"speaker":"山村委員","kind":"質問","question":"英語学習、教育における活用というものは、何かやられているのか、考えているのか教えていただければと思います。","respondent":"中島指導課長","answer":"本区の英語学習におきましては、これから、１年生からすべての小学校で実施していきたいという、一貫教育の全区展開とも重ね合わせられるところです。","voiceIndex":235,"id":"exchange-103"},{"speaker":"山村委員","kind":"質問","question":"あまり今の説明だとよくわからないんですが、インターナショナルスクールとか、大使館、外国の施設を利用したことで、何か考えられている案があるんでしたら、教えてください。","respondent":"中島指導課長","answer":"英語学習の中で、私どもが作成しているカリキュラムの中には、そういった体験的な部分も織り込まれてはありますけれども、それを教育委員会として特別固定化した形で学校に実施をさせるというような状況は、現在のところ考えてございません。","voiceIndex":237,"id":"exchange-104"},{"speaker":"山村委員","kind":"質問","question":"小学校でこれから英語の学習をするということだと思うんですけれども、小学校の時代から文法をやるということではないと思うんですね。小学校で今後６年間英語学習をするという上で、要するに文法が基本なのか、それとも会話が基本なのか、そこら辺、何を基本をした英語学習をされるつもりなのか教えていただければと思います。","respondent":"中島指導課長","answer":"私どもが考えている小学校段階での英語学習の基本は、コミュニケーションの部分です。小学校から文法を教えるというような予定は全くございません。","voiceIndex":239,"id":"exchange-105"},{"speaker":"山村委員","kind":"質問","question":"今後は、インターナショナルスクール等の活用を考えられたほうが、ほんとうの英語力が身につくと思いますし、インターナショナルスクールで教えられている先生方というのは、要するに小学校だとか、小さい子どもに英語を教えるエキスパートですから、どう考えても、そちらの方のほうがうまいというか、いろいろなノウハウを持っていると思いますので、いろいろと取り入れていっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":241,"id":"exchange-106"},{"speaker":"嶋委員","kind":"質問・要望","question":"一つ目は、３０１ページのまちの人々に学ぶ授業、それから、二つ目には３２３ページ、地域スポーツ施設の開放の学校施設について、もしお時間があれば、３１７ページの幼稚園運営費について、お伺いをいたします。そういう意味で、これからは環境教育ということで、午前中にありましたけれども、私のほうからは、環境体験学習ということでお話を伺わせていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":243,"id":"exchange-107"},{"speaker":"嶋委員","kind":"質問","question":"環境省が環境教育ということで、環境体験学習ということで、もっともっと自然に触れていく、ともに共生をしていくという中の環境学習を、昨年１０月に施行されました環境保全活動・環境教育推進法ということで、いよいよ昨年１０月にスタートして、そういう中の体験学習、指導者の育成という形になってくると思いますが、環境教育のほかに、環境体験学習ということで、ちょっとお聞きをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":245,"id":"exchange-108"},{"speaker":"嶋委員","kind":"質問","question":"ベランダの発泡スチロールの中に、今、品川生まれの蛍が１,５００匹おります。そういう中で、ぜひ、環境教育体験学習ということで、地元、八潮南小学校はビオトープもありますので、学校施設の開放をしていただきながら、学校と、子どもたちと、その方たちが、まちの人々に学ぶ授業の一貫としてやっていけないかどうかとても気になっておりますので、お聞きいたします。","respondent":"中島指導課長","answer":"それぞれ学校が実態に応じた形で取り組んでいる中で、私ども教育委員会のほうで支援をして、その学校がよりそこの部分を高められるという状況も多くあるのではないかと思ってありますので、その辺につきましては、今回のＩＳＯの小学校全校展開というような状況もありますので。","voiceIndex":248,"id":"exchange-109"},{"speaker":"嶋委員","kind":"質問・要望","question":"いろいろな形があると思います。今実際問題、発泡スチロールの中に１,５００匹の蛍がいて、上陸を待っているという形があります。そういう意味でも、ぜひ、今ある施設の中で活用して、地域の方たちに学ぶ、それをプラスさせたら、もっともっとすばらしく、一人でも多くの子どもたちに、または大人たちに感動を与えるのではないかと思ってお聞きをいたしましたので、ご答弁いただきたいと思います。","respondent":"中島指導課長","answer":"おそらく、今のようなすばらしい取り組みについて、十分に情報を各学校にも伝わっていないような部分もあるんではないかなと思いますので、早速に情報提供いたしまして、そういった体験を、少しでも多くの子どもたちができるような体制づくりを進めたいと思います。","voiceIndex":251,"id":"exchange-110"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひ、よろしくお願いいたします。二つ目に、３２３ページの学校施設開放について。今、学校施設開放をされているということで、ほんとうに地域の方たちが身近でスポーツを楽しむということで、大変喜ばれておりますが、その中で、いわゆる規則とか、守りとか。どのような決まりをされているのか、お聞かせいただきたいと思います。","respondent":"上川内生涯学習課長","answer":"ただし、いろいろなハンディキャップを持った方等、ご事情がある場合は、事前に校長先生なり、学校のほうと協議をして、車をとめる場所等を決めて利用してくださいというお願いをしているところです。","voiceIndex":253,"id":"exchange-111"},{"speaker":"嶋委員","kind":"確認","question":"学校の側の校長先生との取り決めの中にあるということで、確認をしてよろしいでしょうか。３１７ページの幼稚園運営費ですが、先ほどから給食のお話がございましたが、小学校に隣接しているところなどは、月に１回、幼稚園児も給食を体験できているということで、学校に入るまでの体験学習としては大変うれしいです。これは、品川区内で何園ぐらい実施されているのかお聞きしたいと思います。","respondent":"谷田部学務課長","answer":"小学校を訪問して、そこで交流を行っているという話は聞いてありますけれども、給食のことについては、ちょっと存じ上げておりません。","voiceIndex":255,"id":"exchange-112"},{"speaker":"嶋委員","kind":"質問・要望","question":"私のほうに要望的なものが来ておりまして、台場幼稚園だと思うんですが、今、月１回給食があります、子どもたちが大変喜んで、学校に入るための準備ができて、親御さんから喜ばれている。月１回でなくて増やしてほしいとか、そういうご要望でございましたので、ちょっとお聞かせをいただいたものです。","respondent":"谷田部学務課長","answer":"その給食の話は、私どものほうでは、ちょっと耳に届いてございません。基本的には、学校給食はそこの児童生徒のために提供するものですので、幼稚園は弁当を持参するのが基本になってあります。","voiceIndex":257,"id":"exchange-113"},{"speaker":"嶋委員","kind":"質問・要望","question":"わかりました。ちょっとまだ時間がありますので、プラン２１の小・中一貫教育の中で一つだけ、平成１８年開校ということですので、まだまだ準備がいかないかと思いますが、親御さんたちから、もし自分たちの子どもが入ったらということで、標準服に関してどのようになっていくのか、もしお考えがあればお聞かせいただきたいと思います。","respondent":"中島指導課長","answer":"ほかの学校でもすべて標準服を着用していますので、標準服の着用という部分は考えてあります。これが、７年生からになるのか、５年生からになるのか、この辺はまた、協議してまいりたいと考えています。","voiceIndex":259,"id":"exchange-114"},{"speaker":"松澤委員","kind":"質問","question":"７款の教育費、１項教育総務費、３目教育指導費、３０３ページに当たる人権尊重教育推進費、この関連で。実は、間もなく卒業式がまいります。それが済むと、またすぐ入学式なんですけれども、子どもたちの名簿なんです。最近、混合名簿というのがはやっているんですね。これは、どのような形で取り入れられてきたのか、ちょっとお聞きしたいと思います。","respondent":"中島指導課長","answer":"男女平等教育の推進につきましては、大きな部分で人権尊重教育を推進していく中で男女共同参画社会の実現、こういったような区の方針の中に、学校におきましても、男女平等教育を推進していくことが必要であるという方向性があります。","voiceIndex":262,"id":"exchange-115"},{"speaker":"松澤委員","kind":"質問・要望","question":"男女混合名簿にすることによって、何が男女平等なんだろうか。これは差別ではなくて区別なんですから、これを、男女共同参画の一つのシンボルだみたいな形で、混合名簿にすることがいいんだと。学校にすべて混合名簿にしなくちゃいけないという指令か何か来ているんでしょうか。その点、なぜ、男女混合名簿にこだわるのかということについて、もう少し詳しくお話しいただきたいと思います。","respondent":"中島指導課長","answer":"少なくとも、そういった男女混合名簿という一つの形があることで、教職員の意識、また、子どもたちの認識、そういったものの男子、女子という序列については、もっとオープンに考えていくようなきっかけにできるんではないかと、こんなふうに考えてあります。","voiceIndex":264,"id":"exchange-116"},{"speaker":"松澤委員","kind":"質問","question":"混合名簿のことについて、いろいろお話を伺いました。今、このジェンダフリーに色どられたこれが間違えているよ、そのような形になっていくわけですから、それに対して、教育委員会のほうは黙って受けるだけじゃなくて、実際にその大もとが間違えているんじゃないかという発信はできないんでしょうか。その辺はいかがでしょうか。","respondent":"中島指導課長","answer":"各学校が、それぞれの実態の中で、子どもたちの人権教育の視点を踏まえながら、名簿につきましても実施していき、一番大切なのは、先ほども申し上げましたけれども、その中身をどのように充実していくか、ここの部分であると考えています。","voiceIndex":266,"id":"exchange-117"},{"speaker":"松澤委員","kind":"質問","question":"２点目に入ります。職業体験というんでしょうか、職場体験というんでしょうか、いろいろな商店街、あるいは駅とか保育園なんかに、中学生ですか、子どもたちが学習に行きながら、現場の職業を学んでくるということがあります。これは品川区でも大変に盛んになっていますけれども、いつごろから始まったのかということと、全校でやっているのかどうか、それについてお伺いしたいと思います。","respondent":"中島指導課長","answer":"小学校のほうでも、近くのお店で体験というような取り組みをやっていただいている学校はありますが、平成１５年度の実施状況ですけれども、ダブりますが、職場訪問のほうは主に中学校１年生でやられておりまして、平成１５年度は９校で実施、職場体験のほうは。","voiceIndex":268,"id":"exchange-118"},{"speaker":"松澤委員","kind":"質問","question":"職場体験というもの、私の知り合いの家がコンビニをやっているものですから、結構いろいろ中学校の方が職場体験に見えるんです。やはり学校ですから、全体で行っていないということ、いろいろばらつきがあるんでしょう、それぞれ学校の温度差が違うんですけれども、すばらしいところはすばらしいというんです。全校的な展開ではないですけれども、どのように広げようとしているのかお聞きしたいと思います。","respondent":"中島指導課長","answer":"この体験活動は、先ほど申し上げましたように、いろいろ学校で実施されておりますけれども、その中で、もちろん働くことの尊さを知ったとかいう部分がメインですが、訪問を通してマナーを知ることができたとか、自分の進路を。","voiceIndex":270,"id":"exchange-119"},{"speaker":"飯沼委員","kind":"質問","question":"３２９ページ、図書館の窓口業務のこと、あと２９９ページ、人権尊重教育について、お伺いをいたします。図書館の窓口の業務委託なんですが、ここのところで、特に維持運営費というところに載っていると思うんですが、この載せ方が非常にわかりにくいと思うんですが、どこに載っているか教えてください。","respondent":"市岡企画財政課長","answer":"非常勤の人件費につきましては事業費として見るという関係がありますので、維持運営費のところに載せている。これを逆に、一般的な人件費として扱いますと、人件費を含めた予算全体がわからなくなるということで、このような扱いをしています。","voiceIndex":274,"id":"exchange-120"},{"speaker":"飯沼委員","kind":"質問","question":"多分、委託なので、全体の金額の下の項目では全館清掃等とか、こういうところに入っているんでしょうか。１億２,２００万円と、かなり大きな額なんですが、窓口業務の委託という項目が全くないんですよね。その辺が、どうしてこんなにわかりにくいのか、まず率直な疑問なんですが。","respondent":"古里品川図書館長","answer":"今の民間委託の経費ですが、予算書上は、委員ご指摘のとおり、全館清掃等委託。例年、この項目で挙げてございまして、その名称をそのまま使ったものです。金額については、委員がご発言なさった金額です。","voiceIndex":276,"id":"exchange-121"},{"speaker":"飯沼委員","kind":"質問・要望","question":"窓口の委託という大きな項目にもかかわらず、それより額の小さい清掃のところに入っているというのは、ちょっと大変わかりにくいので、ぜひこういうのはわかりやすい表示をお願いしたい、これは要望です。それから図書館に関して、この間、どこでも論議がなかったんですが、なぜ区はこの大切な窓口業務を委託にするのかというところと、区民への影響をぜひ教えてください。","respondent":"古里品川図書館長","answer":"窓口等の民間委託につきましては、既に２３区の中で、数区が平成１５年度、あるいは平成１４年度から実施しています。","voiceIndex":278,"id":"exchange-122"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺をちょっと、これからお尋ねをしたいと思います。１点、委託の単価を知りたいので、ちょっと調べておいていただきたいんです。直接雇用の非常勤の時間単価と、委託になったところの１時間の単価を比較したいので、ぜひ計算をよろしくお願いいたします。もう１点は、委託によって正規の職員と、委託業者の職員との関係がどう変わるのか、指示、命令系統、指導のところを教えてください。","respondent":"古里品川図書館長","answer":"荏原図書館につきましては、正規職員が６名、再任用職員が２名という配置を検討しています。ゆたか図書館につきましては、６名を正規職員、五反田図書館、大崎図書館につきましては、５名の正規職員と１名の再任用嘱託員を配置をする予定です。","voiceIndex":280,"id":"exchange-123"},{"speaker":"飯沼委員","kind":"意見","question":"仕事の内容は、委託の業者に出す中身を知りたかったのと、あと、職員体制なんですが、荏原図書館だけで結構なんです。現状の正規、非常勤、嘱託非常勤の数と、今後変わって委託をするときの数を対比をして知りたいんです。よろしくお願いします。","respondent":"古里品川図書館長","answer":"荏原図書館ですが、現在、正規職員１０名、それから、嘱託員２名、非常勤職員が４名の配置です。","voiceIndex":282,"id":"exchange-124"},{"speaker":"飯沼委員","kind":"質問","question":"利用者に実際に接するという意味では、大変重要なところだと言われていますが、この重要な部門を委託に出してしまうのは、一体、この辺はどうとらえていらっしゃるのかなと思うのが１点。先ほど、サービスがよいという他区の評判ということでしたが、あちこちで委託によって問題点が出ているんですが、その辺の認識はあるのでしょうか。","respondent":"古里品川図書館長","answer":"問題点がさまざまあるですが、２３区、先行区で実施をしている例を見まして、いろいろな問題点というのはほとんどないと考えています。","voiceIndex":284,"id":"exchange-125"},{"speaker":"飯沼委員","kind":"質問","question":"例えば、路上生活者がいらしたり、ある区では、児童室で、子どもが２回連続で痴漢におそわれたという話とか、トイレで中学生がなぐり合いをしたとか、本を貸し借りするだけじゃなくて、その建物の安全を図るといった意味では、正規の職員がすごく気配り、目配りをしているんだという、そういうところも含めて業務であるということが言われていましたので、この辺も含めて、問題意識をお伺いしたいと思います。","respondent":"古里品川図書館長","answer":"その役割というのは、区民の皆さんに対する図書館サービスのレベルアップをより一層していくためのバックヤードの仕事、あるいは、区民の皆さんにご利用していただくための安全な利用環境づくり、こういうことをするのは、職員として当然の責務ですから。","voiceIndex":286,"id":"exchange-126"},{"speaker":"飯沼委員","kind":"提案","question":"こういった点では、委託に出すよりも、非常勤体制を維持したほうが、私は内容的にいいと思うんですが、その点が１点。利用者とのトラブルを防いでいくという意味では、利用者の懇談会を、形だけじゃなく実質のあるものにしていくことを提案したいんですが、いかがでしょうか。","respondent":"古里品川図書館長","answer":"利用者懇談会のことですが、これらにつきましては、図書館法を含めて、必置の義務はございませんが、区民の方のご意見を多く聞いていくということについては、これからの図書館サービスは地域とともに歩む図書館サービスということを考えてありますので、図書館協議会の設置。","voiceIndex":290,"id":"exchange-127"},{"speaker":"飯沼委員","kind":"質問・要望","question":"地域の利用者との懇談会は、ぜひつくっていただきたいと思います。財政のことを言いたいと思います。これは、あっちの区、こっちの区でも言われていますが、私がちょっと伺ったところによると、企業は、パートの賃金と同じぐらいの比率でもうけを上乗せしている。こういった面では、パートの賃金の２倍が委託料、単価になっていると聞いたんですが、その辺はどうなんでしょうか。","respondent":"古里品川図書館長","answer":"私どもは、さまざまな観点から、委託の経費について検討をしまして、契約係に予算を提示し、契約を依頼してきた内容でございまして、現実的にそれが倍の単価なのか、上乗せしているのかという問題は企業の努力の問題ですし、今回の入札につきましても。","voiceIndex":292,"id":"exchange-128"},{"speaker":"飯沼委員","kind":"質問・要望","question":"委託のところは、ぜひ、実際に行われている仕事と単価のところでどうなのかという比較を、今後していきたいと思うんです。こういった面で、ぜひ数字の検証をしていきたいと思いますが、委託の仕事の内容からすると、決して安くはないという面では、非常勤の制度を活用してやっていきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":294,"id":"exchange-129"},{"speaker":"大西委員","kind":"質問","question":"学校が今うたっている内容と、現実にやっている内容、これがどのぐらいの整合性があるかという点は、把握されていますでしょうか。","respondent":"中島指導課長","answer":"年度当初に計画していたものと、単元の進捗状況、または子どもの習熟ぐあいに応じて、実施の時期が若干ずれているような部分はあるかもしれませんが、基本的に、年度当初の計画に従って実施をするものですから、今、委員のご指摘のあったような。","voiceIndex":297,"id":"exchange-130"},{"speaker":"大西委員","kind":"質問・要望","question":"一番問題となるのは、算数ではないかなと考えています。私の娘の学校の場合は、教えている先生が１人いて、ボランティアの学生が１人見えて、それもボランティアですから、学生の都合に応じてという形でやっているために、現実的な習熟度ということで、おくれている子を何とかここまで引き上げようということに、担任の精力が傾注して、ほかの子どもたちが少し放っておかれているということがあったりする。","respondent":"中島指導課長","answer":"これは算数と数学ではないんですけれども、英語活動などでは、ＡＬＴのほかに地域の英語ボランティアの方々が英語の授業にＴＴなりで参加するための経費を見込んだ予算を、今回も計上させていただいてあります。","voiceIndex":299,"id":"exchange-131"},{"speaker":"大西委員","kind":"質問・要望","question":"理解できない部分が随分積み重なった後に、さて習熟度別で、あなたはここまで理解してますかという部分を、１時間や２時間で解消するのは非常に難しいんじゃないかと思います。本来的に習熟度を目指すんであれば、表面上の、言葉上の習熟度よりも、ほんとうに中身のある習熟度、そのために、行政としてできる得る限りの力を注いでいただきたいなと、これは要望しておきたいと思います。","respondent":"中島指導課長","answer":"そういった子どもたちの、特に評価になるんでございましょうか、こういった状況につきましては、例えば習熟度別学習においては、１年間取り組んできた状況を、各学校から、私どもは報告を受ける形になっております。","voiceIndex":301,"id":"exchange-132"},{"speaker":"大西委員","kind":"質問・要望","question":"私はこれが、今、教育者に求められているもので、子どもたちも、そういうことをできる先生たちを求めていると思うんです。そういった意味での教員に対する対策、おもしろい授業、わかりやすい授業、そういったものに対して、品川区として独自に先生たちに何らかの研修で、子どもたちにとって、褒めて励ませばとか、こういう共通の点を、何らかの形で求めているというものはありますか。","respondent":"中島指導課長","answer":"それからもう一つには、それぞれの学校の教員が、自分の専門の教科ごとに、月一度集まって研修会を実施する状況があります。その中で、その教科の専門性に入った指導についての研修を行う場面もあります。","voiceIndex":303,"id":"exchange-133"},{"speaker":"大西委員","kind":"質問・要望","question":"中学校で言えば、松濤中学校なんかが英語の教育に力を入れるということで、朝から校長先生が朝礼なんかで英語でスピーチをする、体育の教諭も英語、美術の教諭も英語でということで、すごく特化して、ほんとうに魅力のある学校づくりというんですか、選択のしがいのある学校づくり。次に、すまいるスクールでちょっとお尋ねしたいと思います。","respondent":"富田教育改革担当課長","answer":"例えば、おやつを希望制にした場合、食べるお子さんと食べないお子さんが出てくる、こういったところでの心の問題のほうが心配であるということで、充実した５時まで、あるいは６時までの利用で、そういったすまいるスクールでの授業内容を。","voiceIndex":305,"id":"exchange-134"},{"speaker":"大西委員","kind":"質問・要望","question":"そういう点では、金額的な面もあるでしょうから、ぜひ、何らかのリーダーシップをとっていただいて、ウェアなり、板なり、そういったものを皆さんのほうに広く呼びかけて、ボランティアで出していただいて、それを林間学校のほうに置いておけば安く利用できる、親御さんの負担が軽くなる、そして、広くいろいろな体験ができるという意味で、ぜひ、そのような形で対応していただけることをお願いして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":307,"id":"exchange-135"},{"speaker":"本多委員","kind":"質問・要望","question":"私からは、２点お願いいたします。３０１ページのプラン２１関連事業、小学校における英語学習と、もう１点は３２７ページの文化センター事業、プラネタリウム室運営費について。取り組みの時間ですとか、時期ですとか、４０校ということになりますので、ＡＬＴの人材確保ですとか、その辺のスケジュールですとか、ちょっと教えていただきたいと思います。","respondent":"中島指導課長","answer":"すべての時間をＡＬＴとのチームティーチングとは考えてございませんけれども、子どもたちが英語を学ぶ上で、ＡＬＴの方と触れ合う時間というのを、これから多くの学校で重視した取り組みを展開していきたいと考えています。","voiceIndex":309,"id":"exchange-136"},{"speaker":"本多委員","kind":"質問・要望","question":"それぞれ総合的な学習での時間で、特色ある内容を充実していただきたいと思うんですが、時間的には、学校それぞれの特色で取り組めるということですか。","respondent":"中島指導課長","answer":"こういったようなことを、各学校で勘案していただいて、１年生からの英語学習の展開に向けて、今後、体制を整えていくというような流れになろうかと考えています。","voiceIndex":311,"id":"exchange-137"},{"speaker":"本多委員","kind":"質問","question":"ＰＴＡなどの土曜スクールなどでのイングリッシュですとか、すまいるスクールでのイングリッシュですとか、いろいろな機会が多くて、拡充ということではほんとうに望ましい方向だと思うんですが、その辺の線引きというか、整理というのはされているんでしょうか。","respondent":"中島指導課長","answer":"ここのところにおきましては、英語を身につける段階ということで、５、６年生、そして７年生の滑らかな連携ということで、文法に頼ることなくて、しかもその中で、具体的な場面に応じた学びの中で、または劇とかほかの教科を英語でトライしてみるような場面として。","voiceIndex":313,"id":"exchange-138"},{"speaker":"本多委員","kind":"質問・要望","question":"リベラル・デモクラティック・パーティでも、ほんとうに堪能な方がたくさんいるんですけれども、世論でも、そういった堪能になるように生きた英語という意味では、当然、国も、都も連携した取り組みが必要だと思うんですが、小学校、中学校での取り組みというのは、品川区の役割がほんとうに大きいと思われまして、その辺のプラン２１での夢と力をはぐくむという意味での期待感について、どのようにお考えか。","respondent":"中島指導課長","answer":"そのさまざまな歩みにつきましては、課題が幾つか出てくるかと思います。現在、先行的に進めております英語学習の推進校もありますので、多くの情報を取り入れながら、英語学習の充実に資していきたいと考えています。","voiceIndex":315,"id":"exchange-139"},{"speaker":"本多委員","kind":"質問・要望","question":"どうぞよろしくお願いいたします。次の３２７ページの文化センター事業、プラネタリウム室運営費について、教えていただきたいと思います。天体望遠鏡は幾つぐらいあるんでしょうか。","respondent":"上川内生涯学習課長","answer":"五反田文化センター本館に大きいのが１台、小型が１台、計２台あります。","voiceIndex":317,"id":"exchange-140"},{"speaker":"本多委員","kind":"質問","question":"東京都の取り組みで、ディーゼル車の規制で、ほんとうに空がきれいになったなと思うんです。年中できるものではないと思うんですが、１年に何回か、五反田文化センターのプラネタリウム室での知識を深めて、実際の星空を見るような星空観測でしょうか、そういった取り組みについて、お考えはいかがでしょうか。","respondent":"上川内生涯学習課長","answer":"今現在では、学校等の行事に、ボランティアとして自分の天体望遠鏡を持って、１０名とか、２名とか、ボランティアで学校の屋上で観望会をしているということは、こちらで把握しております。","voiceIndex":319,"id":"exchange-141"},{"speaker":"本多委員","kind":"質問・要望","question":"子ども、児童を対象にしたものですとか、当然、生涯学習で一般区民への取り組みですとか、さまざまあると思うんですけれども、より一層拡充をしていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":321,"id":"exchange-142"},{"speaker":"藤田委員","kind":"質問","question":"私からは、３点お伺いいたします。第１点は、葛飾区の教育委員会で、夏休みを短縮するという記事が載っていました。これは、学力の定着が不十分な生徒を対象にして行うんだという趣旨で、これまで希望制だったのを、全生徒を対象にして夏休みに集中的にやろうと、こういうような事業展開らしいんですけれども、品川区として、これについて何か感想があれば、お伺いしたい。この辺をお伺いしたいと思います。","respondent":"中島指導課長、谷田部学務課長","answer":"１点目、葛飾区教育委員会の実施を受けてというところで、ご答弁します。３点目の、子どもの入学者の数の２０人以下ですけれども、小学校でいきますと、昨年４月の入学の段階ですが、１４人の入学者が２校、１０人が１校、それから中学校におきましては、１３人の入学者が１校という状況です。","voiceIndex":323,"id":"exchange-143"},{"speaker":"藤田委員","kind":"質問・要望","question":"何も短縮をしなくても、十分に今の中で、ぜひともご努力をいただきたいと強く要望しておきます。それから、動物の件ですが、今、お聞きしますと、子どもたちがインコとか、アヒルとか、鳩とか、さまざまな飼育をしておりますけれども、例えば餌やりとか、糞尿の処理とか、抱き方とか、こういうのは誰が教えていらっしゃるのか。","respondent":"中島指導課長、谷田部学務課長","answer":"現在、学校での対応はそのような形の中で、あくまでも飼育をやめるとか、そういうことではなく、飼育動物を通して動物愛護ですとか、生命尊重というような教育的な意義を継続していきながら、また最新の情報も取りながら。デメリットといたしましては、これも逆の関係になりますけれども、学年、学校での児童生徒のコミュニケーションが希薄化されるとか、使用施設に限界だとか、学校施設に余裕がなくなるとかいうようなことが言われているです。","voiceIndex":326,"id":"exchange-144"},{"speaker":"藤田委員","kind":"質問・要望","question":"ですから、今ご答弁があったとおり、早めに地域の獣医と協議をしていただいて、ぜひとも正しい飼い方を遂行していただきたいと思いますので、よろしくお願いいたします。これはちょっと考えをお聞きしておきたいんですが、例えば、小学校はブロックをつくっていますけれども、ブロックの中で、兄弟校というんですか、姉妹校とも言うのかもわかりませんが、何か交流をしながらやるものはないのか。","respondent":"中島指導課長","answer":"特に、非常に少人数の中で６年間という流れを、固定化された人間関係の中でという部分は、大きいな課題の一つであると認識しています。","voiceIndex":329,"id":"exchange-145"},{"speaker":"藤田委員","kind":"質問・要望","question":"ぜひ、そういう形で取り組んでいただきたい。今、プラン２１はどんどん遂行していただいて、いろいろな希望、強い要望等がたくさんありますけれども、これはやっぱり改革をするわけですから、当然、受ける問題なんですね。しかし、それを乗り越えて、ぜひとも遂行してもらいたいと思うんですが、その反面、そういう面をぜひともこれから検討していただきたいと、このように強く要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":331,"id":"exchange-146"},{"speaker":"須貝委員","kind":"質問・要望","question":"ちょっと大ざっぱですけれども、２９６ページ、教育指導費と、３０４ページ、学校管理費、全般についてお聞きしたいと思います。昨今、半径１０cmの円の面積を求める問題がありました。円周率３.１４という副題も書いてあります。それでも、小学校５年生の約半分の子は、円の面積が求められない。つまり、１教科５０点という現実なんですね。数学に至っては０点から１０点が８人います。","respondent":"中島指導課長","answer":"私どもが実施いたしました学力定着度調査、これを学習指導要領に合わせた形で、達成度を確認していくという形で、この夏に小学校のほうが態度表明しましたけれども、その中には、大方の部分でその達成ができているけれども、やはり、その学校として課題が出てきている。","voiceIndex":333,"id":"exchange-147"},{"speaker":"須貝委員","kind":"質問","question":"そうしたら、何か考えなきゃいけないんじゃないですか。例えば一番簡単なことは、毎朝、５分でも１０分でも読書をさせて、宿題を毎日出せばいいんじゃないですか。そういうふうに、やはり、教えていかなきゃいけないんじゃないですか。結局、子どもの学力云々、きめ細かくやはり見てやって、我々大人が指導していく、それが教育委員会じゃないかなというふうに思うんですけれども、その辺どうでしょうか。","respondent":"中島指導課長","answer":"実際問題、委員がご指摘になったような低い平均点が出てきたときに、ある程度、その問題の難易度を難しくして、そういうふうに出させようと思ったその教員の意図があるのか、それとも、８０％の学習指導要領の内容でつくったにもかかわらず、そういった結果が出てきているのか。","voiceIndex":335,"id":"exchange-148"},{"speaker":"須貝委員","kind":"質問・要望","question":"そこら辺はやはり早く救済してほしい。そこら辺をよくわかってほしいんですよ。一応、これはちょっと要望だけで、時間もないので次に進めたいと思います。じゃあ、現実に品川区教育委員会では、その後何をしたんですか。かぎの施錠ですか。今、どうするんですか。こういうことも、じゃあ、入ってきたらどうするんだ、そこら辺も考えないで、女の先生がバットを持って立ち向かって、勝てるんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":337,"id":"exchange-149"},{"speaker":"須貝委員","kind":"質問","question":"今の話で理解できました。では、ちょっとお聞きしたいんですけれども、今、これだけ世間が騒がれていますよね、もし不審者が入って、また殺傷事件が起きた場合に、ある意味で、品川区教育委員会の過失責任を問われるんでしょうか。それとも、あくまで保護者の責任になるんでしょうか。その辺をちょっとお聞かせください。","respondent":"中島指導課長","answer":"これは、不審者侵入に限らず、私どもが設置している小中学校で起きた事故に関しては、区と教育委員会がその責務を負う形です。","voiceIndex":341,"id":"exchange-150"},{"speaker":"須貝委員","kind":"意見","question":"自分のお子さんが万が一刺されたり、死亡したりするようなことがあったら大変だと思うんですよ。今、それでいいとおっしゃっている、でもほんとうに親の身になって、小学校１年生も含めて、２年生、３年生、絶対にこれで安全なのかという、そこら辺。やはりもっともっと教育委員会で考えなきゃいけないと思うんですけれども、その辺ちょっとご回答ください。","respondent":"古川教育次長","answer":"確かに、日々の対応についての取り組みの部分と、それから、全体をとらえて、今後、学校の安全を地域の方々、あるいは保護者も含めて、どう取り組んでいけばいいだろうか。こういう中に、一つは、今回、ＮＰＯとの研究を視野に置いてあります。","voiceIndex":343,"id":"exchange-151"},{"speaker":"須貝委員","kind":"質問","question":"今、これから、教育次長が頑張って取り組みますということなんで、ほんとうに早急に、親の身になって、先ほどの学習のほうもそうですけれども、よろしくお願いいたします。同じ子どもという条件に立った場合に、やはり、これはしてあげるべきじゃないかと思うんですけれども、何かあるんでしょうか、そのご見解だけお聞かせください。","respondent":"谷田部学務課長","answer":"平成１４年度、１５年度の２カ年度にわたりまして、普通教室に空調機を設置させていただきました。基本的には、児童生徒が学校で大半を過ごす、普通教室の環境を整備していくのが第一だということでの取り組みです。","voiceIndex":345,"id":"exchange-152"},{"speaker":"塚本委員","kind":"質問","question":"私のほうから、教育委員会制度の課題と、すまいるスクールについて伺います。あるいは、教育委員会と学校の関係、経営に関して、どこまでどういう指導をするか。いろいろな課題がさまざまあるんですけれども、戦後、導入されたこの制度、制度疲労の部分もあろうかと思いますが、現状で何を課題としてとらえ、どういう議論がなされているのか、お知らせ願いたいと思います。","respondent":"鷹倉庶務課長","answer":"首長との関係は、ご案内のとおり、私ども教育委員会、特に教育長と区長との関係がスムーズにいっているということで、私ども品川区に関しては、今のところうまくいっていると考えております。","voiceIndex":348,"id":"exchange-153"},{"speaker":"塚本委員","kind":"質問","question":"そういう意味で、悩める教育委員会制度を抱える日本、そしてうまくいっていると自負される品川区ですけれども、教育委員会と学校現場、学校の経営権、それに対しては、どういう分野のことは指導監督し、あるいは、どういう分野のことは相談する、これはときによってだんだん考え方が変わってきて、教育現場の力の強さ、特に教員の組合の強さとの変化による部分がかなりあると思いますけれども。","respondent":"中島指導課長","answer":"東京都との県費職員としての教員が、区の学校の中でさまざまな関わりを持つ上で、学校長の裁量権がない、また区市教育委員会と都道府県の関係で裁量権が取れない部分、こういったようなところの見直しということにつきましては、私ども、これまでにも都のほうに申し入れを行い。","voiceIndex":351,"id":"exchange-154"},{"speaker":"塚本委員","kind":"提案","question":"学校現場と教育委員会との責任のあり方、どういうコミュニケーションをとればいいのか、問題点はどこにあるのかということが、今やっている最中だろうと思いますけれども、そろそろ政策的に打ち出して、全国の注目を浴びているわけですから、教育委員会と学校現場、学校の経営権、こういうことは教育委員会の指導のもとに一定レベル形をつくっていくんだ、この話は。","respondent":"富田教育改革担当課長","answer":"しかしながら、平成１６年度、放課後児童健全育成事業としての役割も入ってくるわけですけれども、これらを進める中におきましても、学校とのさらなる連携、また地域のボランティア、保護者の方々のご協力、この辺につきましても、今後ともさらに追求していきたい。","voiceIndex":353,"id":"exchange-155"},{"speaker":"塚本委員","kind":"質問","question":"いつまでも、親の子に対する心配というのはついて回るわけですから、これは親が心配すべきことですよ、このレベルではお預かりしますけれども、このレベルの責任範囲はここですと、こういうことをそちら側から言わなきゃいけない。何でもそうですかと、この心配、そうですね、工夫すればどうにかなりますと。そして、何でもお金がかかるようになる。そう思いますが、見解はいかがでしょうか。","respondent":"古川教育次長","answer":"こういう観点で、すまいるスクールの運営につきましては、十分に意を尽くしてまいりたいと、このように考えてあります。","voiceIndex":355,"id":"exchange-156"},{"speaker":"土井委員","kind":"質問・要望","question":"私は、２９７ページの教育総務費、安全衛生管理費、あるいは、３１３ページ、学校保健費に当たるんでしょうか、このあたりのところで２点ばかり。それとあわせて、先ほど質問がありましたけれども、いわゆる学校でどういう小動物を、どう飼っているのかという調査等をやりたいやにも伺っているんですよ。これが、今の現状だと思うんです。その中のプラン２１、現在進行形でどんどん進んでいる。","respondent":"鷹倉庶務課長、中島指導課長","answer":"４月１日から会議体を興していくために、今、教職員の推薦を求めているという段階です。これらの中で、すべてではないかもしれませんが、こちらの医師会のほうにご提供させていただいて、学校にとりましては同じ調査を二度やらず、また、獣医師会のほうもに早く情報を提供できる部分があろうかと思いますので。","voiceIndex":358,"id":"exchange-157"},{"speaker":"土井委員","kind":"質問・要望","question":"要するに、人間も含めて、生きとし生きるものが生まれたら死んでいくんだ、その過程を、この小動物を通じて、悲しいこともうれしいことも、みんなに知ってもらって、情操教育をしていくということのための必要があるんですから、ぜひ、そういう場面に使っていただきたいと思うんで、そこら辺が、今例えば病気になったときに、死亡したときに、どうしているのかというのがちょっと気になるものですから。","respondent":"谷田部学務課長、若月教育長","answer":"そういうことで、日常的には、動物病院の先生方とは、飼育動物に変化があった場合についてはご相談するようにという対応をとってあります。そうしたものをさまざま開発し、そして、子どもたちが野球のゲームに、試合に参加できる意欲を持たせる、これが我々教師というプロ集団に求められている要請ではないだろうかと、こんなふうに考えています。","voiceIndex":361,"id":"exchange-158"},{"speaker":"土井委員","kind":"質問・要望","question":"と同時に、子どもたちの間でも、例えば死んじゃったというときにどうするのか、みんなで話し合ってうまいぐあいにやってもらいたいと思うんですよ。よろしくお願いします。それから、プラン２１のほうですが、ぜひ、先生方を含めまして、これからご努力をいただいて、さまざまの形での、いわゆる生きる力をつけてもらう、そういうためにご努力をお願い申し上げて終わらせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":364,"id":"exchange-159"},{"speaker":"沢田委員","kind":"質問","question":"私は、３０１ページのプラン２１、あるいは小中一貫校にかかわって、１点だけ質問をしたいと思います。小中一貫校を全区展開をする、その中で、習熟度別学習の占める位置が大きいと思いますけれども、これまでの習熟度別学習をどう展開をしていくのか、区側の考えをお知らせ願いたいと思います。","respondent":"中島指導課長","answer":"現在、プラン２１で取り組んでおります習熟度別学習ですけれども、現在の取り組みの形は、もうすべての小中一貫校での実施という形になっておりますので、来年度も、今年度の各学校の取り組みをより充実していく形で、実際の予算的には継続をする形で取り組んでいく。","voiceIndex":366,"id":"exchange-160"},{"speaker":"沢田委員","kind":"意見","question":"ちょっとここで別の角度なんですけれども、世界的に見て習熟度別学習というのは、いろいろなところで研究をされて現在に到達していますけれども、世界的に見た検証、あるいは実践がどうなのかということと、それから、習熟度別学習がより優秀だという研究結果は果たしてあるのかという点。説明願いたいと思います。","respondent":"中島指導課長","answer":"その中には、個に応じた指導の一層の充実というような追加の部分がございまして、具体的に、学習内容の習熟の程度に応じた指導を充実していくというような部分が追加されてあります。習熟度別学習の充実というのは、日本で申し上げれば、全国的な方向かなという考えがあります。","voiceIndex":368,"id":"exchange-161"},{"speaker":"沢田委員","kind":"質問","question":"私が不十分ながら勉強した範囲で、ヨーロッパで言うと、トラッキングと呼ばれる、要するに能力別学級編成で教育をしている国というのは、ドイツ、オーストリア、スイスの３カ国だけで、その他の二十数カ国はみんな平等教育、混合教育とでも言うんでしょうか、そういうふうになっている。もしこのテストのねらい、結果をどう分析するかということが区側にありましたら、ご説明願いたいんですが。","respondent":"中島指導課長","answer":"今、委員のご指摘いただきましたトラッキングシステムですけれども、これは、進学予定者の進路のことをトラックというわけですが、これを振り分ける社会構造のことを指していると、私どもは理解しています。","voiceIndex":370,"id":"exchange-162"},{"speaker":"沢田委員","kind":"質問","question":"そこを知らないとすれば、子どもたちをここに影響させるものですから、今からでもいいから研究してほしい、勉強してほしいと、まず思います。１９８０年代に２０％の失業率、東欧やソ連が崩壊して、どうにもならなくなった段階で、これからは、子どもたちに教育を重視しようというので、ほかの予算は削ったけれども、教育予算は削らずに、教育委員会の権限を学校と教員に下ろした。そういうふうに思います。","respondent":"中島指導課長","answer":"やはり私どもは、子どもたちの実態、それから、教師の実態、そして何よりも、今私どもが進めている中での子どもたちの育成をベクトルをそろえる形で進めていくのが重要と、このように考えてあります。","voiceIndex":372,"id":"exchange-163"},{"speaker":"沢田委員","kind":"質問・要望","question":"先ほど、トラッキングに対しての研究はないとおっしゃいました。ほんとうに勉強したんでしょうかね。「すべての子どもが背伸びとジャンプとしての学びを実現するには、どうすればいいのでしょうか。私は、世界の教育の実践にてらしても、先進国で４０人学級をやっているところはないわけですから、少人数学級、小グループの共同の学びの場をつくることを強く求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":374,"id":"exchange-164"},{"speaker":"三上委員","kind":"質問","question":"３０４ページ、学校教育費につきまして、２点お伺いしたいと思います。それからもう一つは代表質問でお伺いしましたが、学校事務職員の職務について、本来であれば、再質問すべきであったと思うんですけれども、やはり、身近な顔を見ながら少し質疑をさせていただいたほうがいいかなと思ったものですから、この件についてちょっとお伺いしたいと思います。先にグラウンドのほうをお願いしたい。","respondent":"鷹倉庶務課長","answer":"今回、予算化をさせていただきまして、具体的にどういう形で対応していくかというのは、実は砂ぼこりの点と、それから、植栽の関係についても随分ご意見が出てありますので、その辺を、予算をいただければ、具体的に地域に入りながら、どういう対策をしていくか。","voiceIndex":376,"id":"exchange-165"},{"speaker":"三上委員","kind":"質問","question":"こういうことで、今、芝生を植えるということが表に出ている話になっているんですけれども、こういうふうに改良されたものであれば、２月の宇都宮ですから非常に気温が下がるところでも、まだ緑色をしている。ですから、そこらあたり、今後の研究にぜひ取り組んでいただいて、対応をお願いしたいと思っているんですが、ご意見をちょっとお伺いしておきたいと思います。ちょっとお伺いしたい。","respondent":"鷹倉庶務課長","answer":"まちづくり事業部とも、いろいろ歩調をそろえながら、一緒に研究していきたい、取り組んでいきたいと考えています。学校事務の関係ですけれども、確かに今、区費の正規職員、中学校において３名におります。","voiceIndex":378,"id":"exchange-166"},{"speaker":"三上委員","kind":"質問・要望","question":"それはわかりました。そういったこともありますので、それについてはしっかりと計画を立ててやっていただきたいと、こういうふうに要望しておきたいと思います。現実、今そういうふうに区の職員が残っている中にあって、学校間格差ということについては、どういうふうにお考えになっていらっしゃいますか。","respondent":"鷹倉庶務課長","answer":"私ども、それぞれの学校、小学校なら小学校の中で、中学校なら中学校の中で、若干要素が違いますので、それぞれ力を均質になるような形で、もう少し言いますと、県費負担の事務職員の力、あるいは非常勤の力。","voiceIndex":380,"id":"exchange-167"},{"speaker":"三上委員","kind":"質問","question":"なぜかというと、一つの計算方式として、都費職員、区費職員の週４０時間勤務と計算して、最大年間３６５日を７日間で割ったら５２週ある。生徒数もやっぱり仕事量的には考えるべきだろうと、こう考えたときに、児童数が大井第一小学校は７２１名います。人数的には、それなりの配置をされていると、そういうふうに受けとめたいんですけれども、第二日野小学校に、今何名配置されているんですか。","respondent":"鷹倉庶務課長","answer":"第二日野小学校につきましては、事務が県費職員が１名、そして区費職員はいませんので、非常勤が１名配置されているところです。","voiceIndex":382,"id":"exchange-168"},{"speaker":"三上委員","kind":"意見","question":"現段階と４月の段階でちょっと違いがあるということで申し上げておきましたので、そこらあたりの数字がちょっと違っているのかわかりませんけれども、７４名しかいない第二日野小学校と、７２１名と１０倍いる生徒数のところの職員数は違いはありますか。","respondent":"鷹倉庶務課長","answer":"実際、今回も引っ越しをするというか、いろいろ引っ越しの準備だとかやったわけですけれども、今後、本格的な小中一貫校に向けて、日野中学校との事務の連携だとか、いろいろ打ち合わせをしていくという要素があります。","voiceIndex":384,"id":"exchange-169"},{"speaker":"三上委員","kind":"質問","question":"そういった部分について、ほんとうにこのままでいいのかどうかということがありますよ。時間があれですから、ちょっと先に進みますけれども、こういった都費職員の代表質問の流れからいったら、都費職員の異動について伺っています。基本原則として、都費職員の異動条件というのは、どういうふうになっておりますか。","respondent":"鷹倉庶務課長","answer":"代表質問でもお答えしておりますけれども、まず、都の人事異動基準というのがございまして、それに基づきますと、現任校に引き続き５年以上勤務する職員は異動するものとなるということがあります。","voiceIndex":386,"id":"exchange-170"},{"speaker":"三上委員","kind":"質問","question":"そうしますと、今、品川区に２０年以上いる人がいますか。１５年以上とか、１０年以上とか、同じ品川区内に１０年以上になったら異動するということが一つの原則論として、今おっしゃったわけですから、２０年以上いるような人っていますか。ちょっと長い人について、ちょっと言っていただけますか。","respondent":"鷹倉庶務課長","answer":"確かに、２０年以上いらっしゃる方もいらっしゃいます。","voiceIndex":388,"id":"exchange-171"},{"speaker":"三上委員","kind":"質問","question":"これだけ長い年数いると、やはり以前に、品川区の保育園でも、長くいる人がいると、その保育園の中でやっぱりボス化してくる。長い経験上のことは、あればいいですよ。だけれども、東京都の異動の基準が、１０年以上になったら他区へ移るということになっているわけでしょ。それが移らないということについて、それでいいと思っていらっしゃるんですか。どうなんでしょう。","respondent":"鷹倉庶務課長","answer":"確かに、原則的には、１０年勤務した時点で他区へ異動するということになっているわけですけれども、それぞれの個別の事情をいろいろ勘案した中で、異動しない場合も例外的にあります。","voiceIndex":392,"id":"exchange-172"},{"speaker":"三上委員","kind":"質問","question":"こういう長くいる人たちが、じゃあ、教育委員会でほんとうに指導しきっているのか。１０年以上が原則という、原則というのはどういうことですか。少なくとも１０年ということで考えたら、その後何年かぐらいのものはわかりますよ、そうじゃなくて、もう２０年を超えた人が何人もいるじゃありませんか。なぜ、そういう異動ができないんですか。どうなんですか。","respondent":"中島指導課長","answer":"東京都の区市町村学校事務に関しましての異動実施基準というのが、東京都教育委員会の中で作成されてありますので、その関係で、私のほうから、今の部分をご答弁をさせていただきたいと思います。","voiceIndex":394,"id":"exchange-173"},{"speaker":"三上委員","kind":"質問・要望","question":"平成１０年にできてから、今年は平成１６年ですよね。６年間も経っているということですから、そのところを十分に考えていただきたい。それから、時間がありませんのでもう一つだけ。図書館部会で、そういう監査前監査なんてやっていますか、どうですか。","respondent":"古里品川図書館長","answer":"通常の事務的なレベルでは、各館の職員にチェックをするように申し伝えてありますが、他の館から他の館に行って、それをチェックするというようなことはしてございません。","voiceIndex":396,"id":"exchange-174"},{"speaker":"三上委員","kind":"質問","question":"今、例えでまず聞きました。時間があればずっと皆さんにお伺いしたかったんですけれども、それができないからですけれども、これは、本来だれが聞いたっておかしいと思いますよ。足りない書類をつくりしょう、そういうことを仲間うちでやっているんですよ。本来、監査というのはどういうことかといったから、品川区の監査委員だって、そこの現地に行って調べるわけでしょ。おかしいじゃありませんか。","respondent":"古川教育次長","answer":"そういう観点から、内部で監査を受けるに当たっての基本的な事項、あるいは、監査資料等について整理をしているわけであって、決して不適切な処理をしているわけではございません。","voiceIndex":398,"id":"exchange-175"},{"speaker":"伊藤委員","kind":"質問・要望","question":"お疲れさまです。ご承知のように、これは３５０m2を削る計画案が示されました。そのたびごとに指摘をしてきたんですけれども、今回も同じようなことに見えますので、これから、プラン２１を推進していくに当たっても、当然、議会に対する姿勢、対象、それから協力を求めることがあるかと思いますので、まずこのことは基本的な部分としてきちっと答弁をいただきたいんですが、いかがでしょうか。","respondent":"鷹倉庶務課長","answer":"この点につきましては、先日、教育次長からもいろいろお話をしていますけれども、私ども、去年の６月９日の文教委員会で、小中一貫校の基本的な考え方、基本設計等をご説明申し上げたところです。","voiceIndex":401,"id":"exchange-176"},{"speaker":"伊藤委員","kind":"質問","question":"経過についてはいろいろご説明いただいておりますので、最も本質的な部分の問題というのは、議会の決定とか、議会をどう考えているんですかということをお伺いしているわけです。ですから、議会の議決の重みをどう考えているかということを、もう１回、きちんと答弁をお願いしたい。それから、削った修正案が、いわゆる最終的な案であるかどうか、そのことをお伺いしたいんですが、いかがでしょうか。","respondent":"鷹倉庶務課長","answer":"１月１９日に提案したものが最終案かですけれども、私ども、３回目のときに、区としてこれが最終案ですという形で、住民説明会に臨んでおります。","voiceIndex":403,"id":"exchange-177"},{"speaker":"伊藤委員","kind":"質問・要望","question":"お伺いしたのは、だれが、いつ、決定したかですので、教育委員会が決定したことはわかっているんですけれども、もう少し具体的な答弁をいただきたいのが一つ。それから、最終案としてぜひ進めていただきたい。それを品川区が選択してしまったわけですから、そのことについての、これからの将来的な対応、そのことについての取り組みをぜひお聞かせください。","respondent":"古川教育次長","answer":"しかし、現実の対応というのは、また場合によってはあるかもしれませんが、それはないような形で、事前に周辺住民の方との合意というもの、あるいは私どもの説明を加えることによって、少なくとも基本設計を固めていきたいと、このように考えてあります。","voiceIndex":405,"id":"exchange-178"},{"speaker":"伊藤委員","kind":"質問・要望","question":"立派な行政としての制度をつくっていく上に当たって、反対したら変わるという風潮が出てきてしまったわけですから、結果として、それについてどう対処していくかということを、もう一つ答弁いただきたい。それから、公金として迷惑料を支払うこと自体、私たちはおかしいと思いますが、もし払うんであるんでしたら、何かしら法的な対応があるんでしょうかということをお伺いいたしますが、いかがでしょうか。","respondent":"古川教育次長、本間総務部長","answer":"あくまでも、小中一貫校の必要な事業を平成１８年４月に向けて完成させていくということの一点に絞り込みながら、最終的には全体をとらえて判断をしたと、こういうふうに考えてあります。区が近隣に行いました補償的な面ですが、例えば、今までですと、電波障害等々について対応したということはありますが、具体的な迷惑料として、金額で、法規制に合致した建物で賠償責任を生じたということは、今まで１件もございません。","voiceIndex":407,"id":"exchange-179"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=832#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":128951,"voices":411}}]);
